def target_rows(target_envs):
    rows = []
    for m, e in target_envs:
        for agent in (True, False):
            rows.append({
                "machine": m, "env": e, "agent": agent,
                "label": f"{m} · {e} · {'agent' if agent else 'shell'}",
            })
    return rows

