class VRow:
    __slots__ = ("data", "kind", "pin_band", "pin_section", "stop", "text")

    def __init__(self, text, stop=None, kind=None, data=None):
        self.text = text
        self.stop = stop          # selectable stop id or None
        self.kind = kind          # 'band' | 'section' | 'colhdr' | None
        self.pin_band = None
        self.pin_section = None
        self.data = data


def _resolve_mock_mode(explicit=None):
    """Whether the picker runs in explicit **mock mode** (a safe dev sandbox).

    Mock mode is the ONLY thing that enables the picker's simulated behaviors:
    the in-TUI progress *walker* (instead of the real Cleanup/Sync executor, so
    no worktree is mutated) and the no-op profiles *apply*. It never turns on
    implicitly -- a normal launch always runs real ops, and a real launch that
    is somehow missing an IO hook fails honestly rather than silently mocking.

    Precedence:
      1. an explicit ``mock_mode`` argument (tests / ``picker mock``),
      2. the canonical env ``AGENT_WORKTREES_PICKER_MOCK`` (truthy),
      3. the deprecated env ``AGENT_WORKTREES_PICKER_REAL_OPS=0`` (back-compat).
    Default: ``False`` (real).
    """
    if explicit is not None:
        return bool(explicit)
    val = os.environ.get("AGENT_WORKTREES_PICKER_MOCK")
    if val and val.strip().lower() not in ("0", "false", "no", "off"):
        return True
    # Deprecated alias: REAL_OPS=0 used to force the mock walker.
    if os.environ.get("AGENT_WORKTREES_PICKER_REAL_OPS", "1") == "0":
        return True
    return False


def _native_list_enabled() -> bool:
    """NF5-5 (#88): the native ``OptionList`` data body is now the **default**.
    ``PickerScreen`` composes ``_PickerNativeData`` (native focus/cursor/scroll/
    click, sticky section header, clickable checkbox gutter) for the data region.
    Set ``AGENT_WORKTREES_PICKER_NATIVE_LIST`` to a falsey value
    (``0``/``false``/``no``/``off``) to force the legacy text-line
    ``_PickerBodyData`` -- a temporary rollback escape hatch until it is retired."""
    val = os.environ.get("AGENT_WORKTREES_PICKER_NATIVE_LIST", "1").strip().lower()
    return val not in ("0", "false", "no", "off")


class _PickerSegment(Widget):
    """One NF2 screen segment (or a row-slice of one) -- a leaf widget that
    renders its slice of ``PickerScreen._frame_segments()`` (#88 NF2/NF3).

    The screen owns all state and content; a segment is a pure view that reads
    its named slice back off the parent screen at render time. An optional
    ``rows`` selects a sub-range of the named segment's rows (used to split the
    header into its ``title`` and ``pivots`` region rows, #88 NF3). Not
    focusable -- the compose tree is the *visual* skeleton only; focus/keys stay
    on the manual ``sel``/``on_key`` model until the later NF slices migrate
    regions and rows to real focusable widgets.
    """

    can_focus = False

    def __init__(self, screen: "PickerScreen", seg_key: str,
                 rows: "slice | None" = None, **kw) -> None:
        super().__init__(**kw)
        self._screen = screen
        self._seg_key = seg_key
        self._rows = rows

    def render(self):
        seg = self._screen._frame_segments()
        lines = seg[self._seg_key]
        if self._rows is not None:
            lines = lines[self._rows]
        return self._screen._join_lines(lines, seg["W"])


class _FocusRegion(Widget):
    """Base for a focusable chrome/data region in the NF3 compose tree (#88).

    A region widget holds native framework focus and mirrors the picker's manual
    ``sel`` model, forming the bridge that lets native Tab move between regions
    while the manual dispatcher still owns the actual navigation (retired only at
    NF5):

    * ``on_focus`` -- the framework put focus here (Tab, or click): point ``sel``
      at this region's head (unless it already sits in this region).
    * ``on_key`` -- forward every key to the manual ``_dispatch_key`` (the single
      source of truth), then mirror focus back onto whatever region ``sel`` now
      names and repaint. Consuming the key here suppresses Textual's own Tab so
      region movement runs through ``region_heads`` exactly as before.

    Subclasses set ``_zone`` (the ``sel`` zone this region represents) and
    implement ``render``.
    """

    can_focus = True
    _zone: str = ""

    def __init__(self, screen: "PickerScreen", **kw) -> None:
        super().__init__(**kw)
        self._screen = screen

    def on_focus(self) -> None:
        scr = self._screen
        if scr._nf_syncing or not scr._nf_mounted:
            return
        # Only move sel if it isn't already within this region (so a focus that
        # merely mirrors sel doesn't stomp the in-region index).
        if scr._widget_for_zone(scr.sel[0]) != (self.id or ""):
            scr.sel = scr.region_head(self._zone)
            scr.refresh()

    def on_key(self, event) -> None:
        scr = self._screen
        key = event.key
        # Global pivot/machine shortcuts stay owned by the picker's BINDINGS: let
        # them bubble (do NOT stop) so the action_* fires, exactly as
        # PickerScreen.on_key does. Everything else runs through the manual
        # dispatcher, then we mirror focus back onto whatever region sel names.
        if key in scr.BINDING_KEYS:
            return
        event.stop()
        event.prevent_default()
        if event.character in ("[", "]"):
            key = event.character
        scr._dispatch_key(key)
        scr._sync_focus_to_sel()
        scr.refresh()

    def on_click(self, event) -> None:
        # Pointer parity (#88 NF4): clicking a region focuses it (Textual does
        # this for a focusable widget; on_focus then points sel at the region
        # head). Subclasses that address a finer target (a data row) override.
        event.stop()


class _PickerPivots(_FocusRegion):
    """The WORKTREES/Tasks/Bridges pivot-tabs row + ⚙ Configuration entry, as a
    focusable region (zone ``V``) (#88 NF3)."""

    _zone = "V"

    def render(self):
        scr = self._screen
        seg = scr._frame_segments()
        return scr._join_lines(seg["header"][1:2], seg["W"])


class _PickerMachine(_FocusRegion):
    """The machine-scope (``All / <machine> <env>``) row, as a focusable region
    (zone ``M``) (#88 NF3). Height auto -- it's the leading chrome rows up to the
    button region."""

    _zone = "M"

    def render(self):
        scr = self._screen
        W = scr.size.width or 100
        chrome = scr._build_chrome_vrows(W)
        machine, _buttons = scr._chrome_split(chrome)
        return scr._join_lines([vr.text for vr in machine], W)


class _PickerButtons(_FocusRegion):
    """The New/Clean/Sync (or Cleanup/Sync) button row, as a focusable region
    (zone ``BTN``) (#88 NF3). Empty (and effectively skipped) for pivots without
    a top button region, e.g. Tasks."""

    _zone = "BTN"

    def render(self):
        scr = self._screen
        W = scr.size.width or 100
        chrome = scr._build_chrome_vrows(W)
        _machine, buttons = scr._chrome_split(chrome)
        return scr._join_lines([vr.text for vr in buttons], W)


class _PickerBodyData(_FocusRegion):
    """The scrolling data body as a focusable region (#88 NF3) -- windows just the
    pivot's data rows (the fixed chrome renders above), scrolling with the
    selection while the chrome stays put. ``height: 1fr`` so it fills the space
    below the chrome; the window is sized to its own height. Its ``_zone`` is a
    placeholder -- the data region's head is resolved per-pivot via
    ``region_head`` on focus."""

    _zone = "L"

    def on_focus(self) -> None:
        scr = self._screen
        if scr._nf_syncing or not scr._nf_mounted:
            return
        # The data region's head zone varies by pivot (L / C / T / PR); land on
        # the current pivot's default body stop rather than a fixed zone.
        if scr._widget_for_zone(scr.sel[0]) != "nf-body-data":
            scr.sel = scr.default_sel()
            scr.refresh()

    def render(self):
        scr = self._screen
        W = scr.size.width or 100
        _chrome, data = scr._build_body_split(W)
        h = max(1, self.size.height or 1)
        return scr._join_lines(scr._data_lines(data, h), W)

    def on_click(self, event) -> None:
        # Click-to-select a data row (#88 NF4); double-click activates it (opens
        # the row's action -- the submenu for a worktree, etc.), the natural
        # pointer parallel to Enter. Maps the click's row offset onto the drawn
        # window and, if it lands on a real data row, points sel there.
        scr = self._screen
        event.stop()
        W = scr.size.width or 100
        _chrome, data = scr._build_body_split(W)
        h = max(1, self.size.height or 1)
        stop = scr._data_stop_at(data, h, int(event.y))
        if stop is not None:
            scr.sel = stop
            scr._wt_track_focus()
            if getattr(event, "chain", 1) >= 2:
                scr._activate()
            scr.refresh()

    def on_mouse_scroll_down(self, event) -> None:
        scr = self._screen
        event.stop()
        scr._dispatch_key("down")
        scr._sync_focus_to_sel()
        scr.refresh()

    def on_mouse_scroll_up(self, event) -> None:
        scr = self._screen
        event.stop()
        scr._dispatch_key("up")
        scr._sync_focus_to_sel()
        scr.refresh()


class _PickerStickyHeader(Widget):
    """NF5-5 (#88): the pinned section header for the native OptionList body.

    A native ``OptionList`` scrolls all options uniformly, so a section header
    (Active / Recent / Completed, or a maintenance group) scrolls off the top --
    unlike the text-line body, which pins the current section. This 1-row widget
    sits just above the list and shows the current top section's header while
    that section's own header row is scrolled out of view; it is hidden
    (``display = False``, taking no space) at the top of the list or when the
    header itself is visible, so the unscrolled layout is unchanged."""

    can_focus = False

    def __init__(self, **kw) -> None:
        super().__init__(**kw)
        self._line = None
        self.display = False

    def set_line(self, line, keep_space: bool = False) -> None:
        # ``keep_space`` decouples *what to show* from *does the row exist*: while
        # the list is scrolled we keep this 1-row region present with a blank
        # line (rather than collapsing it to height 0) so a section boundary
        # never reflows the OptionList by a row. That reflow -- the pin toggling
        # ``display`` on/off as headers passed the top -- was the visible flicker
        # (#169). Only the unscrolled top fully hides it, preserving the at-rest
        # grid parity the feature was built to keep.
        cur = self._line.plain if self._line is not None else None
        new = line.plain if line is not None else None
        want_display = bool(line is not None or keep_space)
        if cur == new and self.display == want_display:
            return
        self._line = line
        self.display = want_display
        self.refresh()

    def render(self):
        return self._line if self._line is not None else Text("")


class _PickerNativeData(OptionList):
    """NF5-5 (#88): swappable *native* data body -- the pivot's data rows as real
    ``OptionList`` options (native focus, cursor, up/down, click, scroll, a11y)
    instead of painted text lines driven by the manual ``sel`` cursor. This is
    the **default** body since dev351; set ``AGENT_WORKTREES_PICKER_NATIVE_LIST``
    to a falsey value to fall back to the legacy text-line body.

    Bridged to the engine ``sel`` model both ways so the rest of the picker
    (chrome, activation, tests) is unchanged: native cursor moves mirror into
    ``sel`` (``OptionHighlighted``), and external ``sel`` changes mirror onto the
    native highlight. Non-selectable rows (column header, section headers,
    live-pulse sublines) become *disabled* options -- the native cursor skips
    them, exactly as the manual ``stops`` list did. Options are rebuilt only when
    the data signature changes, so plain cursor navigation stays smooth/native.
    """

    can_focus = True
    _SENTINEL_SEL = ("__native__", -1)
    #: Keys OptionList owns natively (its own BINDINGS handle these); everything
    #: else routes through the manual model so Tab/pivot/machine behave as
    #: elsewhere.
    _NATIVE_KEYS = frozenset({"up", "down", "home", "end", "pageup", "pagedown",
                              "enter"})

    def __init__(self, screen, **kw) -> None:
        super().__init__(**kw)
        self._screen = screen
        self._stops = []          # option index -> sel stop (None = header row)
        self._sections = []       # option index -> section label active there
        self._section_texts = {}  # section label -> its header Text (for sticky)
        self._kinds = []          # option index -> VRow kind ('section' etc.)
        self._l_rows = {}         # worktree row id4 -> (option index, rec, li)
        self._sig = None          # last data signature (rebuild only on change)
        self._syncing = False
        self._suppress_activate = False   # one-shot: gutter click toggled, don't open

    # ---- data <-> options -------------------------------------------------
    def _signature(self):
        scr = self._screen
        wt = tuple(sorted(scr.wt_sel.ids)) if hasattr(scr, "wt_sel") else ()
        kind = scr._kind()
        # A cheap per-pivot data-size probe so the options rebuild when the
        # active pivot's rows change (tasks load, maintenance candidates), not
        # only when the worktrees list does.
        try:
            if kind == "registered":
                nrows = len(scr._task_rows())
            elif kind == "maintenance":
                nrows = len(scr.maint_records())
            else:
                nrows = len(scr.list_records())
        except Exception:
            nrows = -1
        return (kind, scr.htab, scr.machine_idx, nrows, wt,
                getattr(scr, "pulse", 0), getattr(scr, "update_state", None),
                scr.size.width)

    def _rebuild(self):
        scr = self._screen
        W = scr.size.width or 100
        # Data-only build (the native widget renders no chrome); resilient to an
        # early mount before the screen's setup() has populated records.
        try:
            data = scr._build_data_vrows(W, sel=self._SENTINEL_SEL)
        except Exception:
            data = []
        self._syncing = True
        try:
            self.clear_options()
            self._stops = []
            self._sections = []
            self._kinds = []
            self._l_rows = {}
            self._section_texts = {}
            cur_label = None
            opts = []
            for vr in data:
                stop = getattr(vr, "stop", None)
                text = vr.text if isinstance(vr.text, Text) else Text(str(vr.text))
                kind = getattr(vr, "kind", None)
                ps = getattr(vr, "pin_section", None)
                cur_label = ps[0] if ps else cur_label
                if kind == "section" and cur_label is not None:
                    self._section_texts[cur_label] = text
                idx = len(opts)
                opts.append(Option(text, disabled=stop is None))
                self._stops.append(stop)
                self._sections.append(cur_label)
                self._kinds.append(kind)
                # Map worktree rows id4 -> (option index, rec, li) so a
                # selection-only change repaints just those rows in place
                # instead of a full rebuild (#171).
                rec = getattr(vr, "data", None)
                if stop is not None and stop[0] == "L" and rec is not None:
                    rid = rec.get("id4")
                    if rid is not None:
                        self._l_rows[rid] = (idx, rec, stop[1])
            if opts:
                self.add_options(opts)
        finally:
            self._syncing = False
        self._sig = self._signature()
        self._sync_from_sel()
        self._update_sticky()

    def _index_for_stop(self, stop):
        for i, s in enumerate(self._stops):
            if s == stop:
                return i
        return None

    def _sync_from_sel(self):
        """Point the native cursor at the option owning the engine's ``sel``."""
        idx = self._index_for_stop(self._screen.sel)
        if idx is None or self.highlighted == idx:
            return
        self._syncing = True
        try:
            self.highlighted = idx
        finally:
            self._syncing = False

    def _update_sticky(self):
        """Pin the current section header above the list when its own header row
        has scrolled out of view (#88 NF5-5). Hidden at the top of the list or
        when the section header is itself visible, so the unscrolled layout is
        unchanged."""
        scr = self._screen
        try:
            sticky = scr.query_one("#nf-body-sticky", _PickerStickyHeader)
        except Exception:
            return
        y = int(getattr(self.scroll_offset, "y", 0) or 0)
        if y <= 0:
            # Unscrolled: fully hide the pin so the at-rest layout / grid parity
            # is unchanged (#88 NF5-5).
            sticky.set_line(None)
            return
        # Scrolled: keep the 1-row region present for EVERY offset (``keep_space``)
        # so its presence never toggles the body's height mid-scroll -- blank it
        # when there is nothing to pin (the top visible row is itself a section
        # header, or out of range) instead of collapsing it, which used to jump
        # the list by a row at each section boundary (the flicker, #169).
        if y >= len(self._sections) or (
            y < len(self._kinds) and self._kinds[y] == "section"
        ):
            sticky.set_line(None, keep_space=True)
            return
        label = self._sections[y] if y < len(self._sections) else None
        line = self._section_texts.get(label) if label else None
        sticky.set_line(line, keep_space=True)

    def refresh_data(self):
        """Called by the screen on a state change (in place of a plain
        ``refresh()``): rebuild the options only when the data signature changed
        -- so plain cursor moves stay smooth and native -- else just mirror
        ``sel`` onto the native highlight. Always re-pins the sticky header
        (cheap) so a mouse-wheel scroll (no highlight change) tracks too."""
        new_sig = self._signature()
        if new_sig == self._sig:
            self._sync_from_sel()
            self._update_sticky()
            return
        # Held-arrow fast path (#171): when only the focus-tracking selection
        # moved (same pivot + data, only the wt_sel field changed), repaint just
        # the rows whose checkbox glyph flipped -- O(delta), not a full O(rows)
        # clear+rebuild -- so a held up/down arrow keeps up with key-repeat.
        # Safe against the old line-wrap jitter because the native scrollbar is
        # hidden (see the CSS): content width is constant, so a replaced row can
        # never be re-measured at a narrower width and wrap.
        if self._try_selection_repaint(new_sig):
            self._sig = new_sig
            self._sync_from_sel()
            self._update_sticky()
            return
        self._rebuild()

    def _try_selection_repaint(self, new_sig) -> bool:
        """Repaint only the worktree rows whose checkbox glyph changed, in place
        (#171). Returns True if it fully handled the update; False to fall back
        to :meth:`_rebuild`.

        Applies only when the signature delta is *selection-only*: the pivot is
        Worktrees and ``new_sig`` differs from the last signature in nothing but
        the ``wt`` (selection ids) field -- i.e. plain/shift arrow navigation,
        where single-select tracks focus. The native list is built with a
        sentinel sel (focus is the native amber cursor, not baked into row text),
        so the only per-row change is the box glyph on the rows entering/leaving
        the selection; re-rendering just those via the SAME per-row renderer as
        the full rebuild keeps the output byte-identical."""
        old = self._sig
        if old is None or len(old) != len(new_sig):
            return False
        if old[0] != "worktrees" or new_sig[0] != "worktrees":
            return False
        # Differ ONLY in the wt (selection) field -- index 4 of _signature().
        if any(old[i] != new_sig[i] for i in range(len(old)) if i != 4):
            return False
        changed = set(old[4]) ^ set(new_sig[4])
        if not changed:
            return False
        scr = self._screen
        W = scr.size.width or 100
        try:
            cols, _sections = scr.current_list()
            lcols = fit(cols, W - 2, "title", 14)
        except Exception:
            return False
        view = scr.worktrees_view
        count = self.option_count
        for rid in changed:
            row = self._l_rows.get(rid)
            if row is None:
                return False   # unknown row -> safe fallback to a full rebuild
            idx, rec, li = row
            if not (0 <= idx < count):
                return False
            text = view._row_text(rec, li, self._SENTINEL_SEL, W, lcols,
                                  None, None)
            self.replace_option_prompt_at_index(idx, text)
        return True

    def on_mount(self) -> None:
        self._rebuild()

    def on_resize(self, event) -> None:
        # Rebuild at the real width once layout assigns it (the first rebuild may
        # run at the size fallback before the screen is sized) -- keeps the
        # full-width section rules in parity with the text-line body.
        self.refresh_data()

    # ---- native events -> engine model -----------------------------------
    def on_focus(self) -> None:
        scr = self._screen
        if scr._nf_syncing or not scr._nf_mounted:
            return
        if scr._widget_for_zone(scr.sel[0]) != "nf-body-data":
            # Land on the first data row (not the button default_sel), so
            # focusing the list selects a row.
            head = next((s for s in self._stops if s is not None), None)
            scr.sel = head if head is not None else scr.default_sel()
            scr.refresh()
        self._sync_from_sel()

    def on_option_list_option_highlighted(self, event) -> None:
        if self._syncing:
            return
        scr = self._screen
        # Only honor a highlight change when this list actually holds focus -- a
        # highlight re-emitted while a modal is up or focus is elsewhere (e.g.
        # right after a programmatic ``sel`` set) must not clobber ``sel``.
        if scr.app.focused is not self:
            self._update_sticky()
            return
        i = event.option_index
        stop = self._stops[i] if 0 <= i < len(self._stops) else None
        if stop is not None and scr.sel != stop:
            scr.sel = stop
            scr._wt_track_focus()
            # Defer the sel-dependent CHROME refresh to the render tick instead
            # of a synchronous per-keystroke full-screen re-composite (the
            # held-arrow freeze): the native cursor already moved, so mark the
            # chrome dirty and let ``_tick`` coalesce the refresh at ~10fps.
            scr._nav_dirty = True
        self._update_sticky()

    def on_option_list_option_selected(self, event) -> None:
        # Enter / click on a row -> activate (open its submenu etc.), the native
        # parallel to the manual Enter path -- unless the press was a checkbox
        # gutter toggle (mouse multi-select), which suppresses this one open.
        if self._suppress_activate:
            self._suppress_activate = False
            return
        self._screen._activate()

    async def _on_mouse_down(self, event) -> None:
        # Mouse multi-select (#88 NF5-5): a press in the checkbox gutter (the
        # first two cells) toggles that row's multi-select; the resulting
        # OptionList selection is then suppressed (see above) so the row does not
        # also activate. A press anywhere else is a normal click-to-activate.
        self._suppress_activate = False
        scr = self._screen
        if getattr(event, "x", 99) <= 1 and scr._kind() == "worktrees":
            y = (int(getattr(self.scroll_offset, "y", 0) or 0)
                 + int(getattr(event, "y", 0)))
            stop = self._stops[y] if 0 <= y < len(self._stops) else None
            if stop and stop[0] == "L":
                ids = scr._l_ids()
                li = stop[1]
                if 0 <= li < len(ids):
                    scr.wt_sel.toggle(ids[li])
                    scr.sel = stop
                    self._suppress_activate = True
                    scr.refresh()
        await super()._on_mouse_down(event)

    def on_key(self, event) -> None:
        scr = self._screen
        key = event.key
        # Global pivot/machine shortcuts stay owned by the picker's BINDINGS.
        if key in scr.BINDING_KEYS:
            return
        # Let OptionList's own bindings own list navigation + select.
        if key in self._NATIVE_KEYS:
            return
        # Everything else (Tab region cycle, [ ] pivots, ←/→, etc.) routes
        # through the manual model, then focus is mirrored back onto whatever
        # region sel now names -- exactly like the text-line region bridge.
        event.stop()
        event.prevent_default()
        if event.character in ("[", "]"):
            key = event.character
        scr._dispatch_key(key)
        scr._sync_focus_to_sel()
        scr.refresh()


class PickerScreen(Widget):
    can_focus = True
    #: Truly-global shortcuts owned by Textual's binding system (#88 F3). When no
    #: modal overlay is active, ``on_key`` lets these bubble to the framework,
    #: which fires the matching ``action_*`` method below -- transferring
    #: ownership of the global pivot/machine shortcuts OFF the hand-rolled
    #: dispatcher and onto native bindings. ``show=False`` because the picker
    #: draws its own footer. Region/row keys stay in the manual model until the
    #: later F4/F5 slices (overlays -> ModalScreen, regions -> focusable widgets).
    BINDINGS = [
        Binding("ctrl+shift+right", "pivot_next", "next pivot", show=False),
        Binding("ctrl+shift+left", "pivot_prev", "prev pivot", show=False),
        Binding("ctrl+right", "machine_next", "next machine", show=False),
        Binding("ctrl+left", "machine_prev", "prev machine", show=False),
    ]
    #: The keys ``BINDINGS`` owns -- ``on_key`` consults this to decide whether to
    #: pass an event through to the binding system (no overlay) or route it to
    #: the manual dispatcher (overlay active). Keep in lockstep with ``BINDINGS``.
    BINDING_KEYS = frozenset({
        "ctrl+shift+right", "ctrl+shift+left", "ctrl+right", "ctrl+left",
    })

    def __init__(self, source, live=False, mock_mode=None):
        super().__init__()
        # NF5 (#88): the native compose tree is the *sole display path* -- the
        # env toggle and the render() fallback are retired. ``render()`` survives
        # only as the deterministic capture seam (see ``compose``).
        # NF3 (#88): scroll offset for the compose tree's data body widget --
        # data-relative (indexes the scrolling data rows only, since the M/BTN
        # chrome is fixed above it), distinct from the monolith's ``top``.
        self._data_top = 0
        # Per-refresh render caches (#169): in the NF compose tree every segment
        # widget (title / pivots / chrome / machine / buttons / footer) renders
        # from this one screen's derived frame in the SAME paint pass. Without a
        # cache each independently rebuilds the whole body, so build_body /
        # build_data run ~10x per keystroke -- a ~100ms/key stall that reads as a
        # hang under key-repeat. These memoize the derived frame / split keyed by
        # ``_render_sig`` (a fingerprint of every input), so the sibling widgets
        # in one pass share a single build while any state change rebuilds once;
        # ``refresh()`` also busts them as a belt-and-suspenders for the
        # interactive path.
        self._frame_cache = None   # (render_sig, segments-dict)
        self._split_cache = None   # ((render_sig, use_sel), (chrome, data))
        self._chrome_cache = None  # ((render_sig, use_sel), chrome-only vrows)
        # Held-arrow flood guard (dotfiles#948 follow-up): a cursor move only
        # needs the native OptionList to repaint its own highlight (instant); the
        # sel-dependent CHROME (topbar/footer) is refreshed by the render tick,
        # not synchronously per keystroke. Without this, every key fired a full
        # ~100ms screen re-composite, so a held arrow queued refreshes faster
        # than they drained and the picker froze. The tick coalesces them to
        # ~10fps regardless of key-repeat rate.
        self._nav_dirty = False
        # NF3 focus bridge (#88): guards the on_focus <-> sel mirror so focusing
        # a region widget to match ``sel`` doesn't recurse back into a sel write.
        self._nf_syncing = False
        # Set once the initial region focus is placed, so the framework's own
        # mount-time auto-focus can't stomp the default ``sel`` before then.
        self._nf_mounted = False
        # Profiles configurator -- an encapsulated sub-view component that OWNS
        # the Profiles grid-editing state (grid / applied / pcol / targets /
        # host_cols / _prof_unavailable) and behaviour; PickerScreen exposes
        # thin @property + method shims onto it (#88 F5 slices 1-3). Created
        # first, before any shim can be touched during construction.
        self.profiles_view = ProfilesView(self)
        # Maintenance pivot -- a second encapsulated body sub-view (#88 F5 slice
        # 5a). Owns the Maintenance render (the select-all / group-header / data
        # rows + column header); the selection state + grouping behaviour still
        # live on PickerScreen for now, reached from the component via
        # ``self._eng`` (moved onto the component in a follow-up slice).
        self.maintenance_view = MaintenanceView(self)
        # Registered/Tasks pivot -- a third encapsulated body sub-view (#88 F5
        # slice 6). Owns the registered-pivot body render (the status/count line
        # + grouped task rows); the read-only task data + pivot-scoping context
        # stay on PickerScreen, reached from the component via ``self._eng``.
        self.tasks_view = TasksView(self)
        # Worktrees list -- the picker's primary body, and the fourth/last body
        # sub-view componentized (#88 F5 slice 7). Owns the list render; the
        # multi-select state (wt_sel / wt_anchor) + its dispatch/range behaviour
        # stay on PickerScreen (shared with the focus machinery), read from the
        # component via ``self._eng``.
        self.worktrees_view = WorktreesView(self)
        self.htab = 0                 # index into self.pivots (built-ins + registered)
        # Cross-plugin pivot registry (Worktrees/Maintenance/Profiles + any
        # pivot a sibling plugin contributed via a manifest). Built here so the
        # tab bar and dispatch are index-agnostic; _load_pivots re-scans on 'r'.
        self.pivots = []              # list of {"label","kind","pivot"} descriptors
        self.htabs = list(BUILTIN_PIVOTS)   # display labels (rebuilt in _load_pivots)
        self.registered_pivots = []   # RegisteredPivot list from the manifest scan
        self.wt_actions = []          # contributed WorktreeAction list (#B)
        self.config_sections = []     # contributed ConfigSection list (#B slice 2)
        # ⚙ Configuration menu is a native Textual ModalScreen now (#88 F4):
        # no self.cfgmenu / cfgmenu_idx state attrs -- see CfgMenuScreen and
        # _open_cfgmenu. (The overlay left the manual registry entirely.)
        self._pivot_runtimes = {}     # pivot name -> RegisteredPivotRuntime (lazy)
        self._last_pivot_poll = 0.0   # registered-pivot repoll gate (#staleness)
        self._load_pivots()
        self.machine_idx = 0          # selected machine sub-pivot (Worktrees/Maint)
        self.sel = ("N", 0)           # (zone, index) -> default New Worktree
        self.top = 0                  # scroll offset into body vrows
        # Per-worktree action menu is a native Textual ModalScreen now (#88 F4):
        # no self.submenu / submenu_idx state attrs -- see SubMenuScreen and
        # _open_submenu. (The overlay left the manual registry entirely.)
        self.msgview = None           # recent-messages viewer overlay (#session-viewer)
        self._msgview_lock = threading.Lock()
        # Clean/Sync scope + New-worktree options are native ModalScreens now
        # (#88 F4): no self.cleanup / self.optmenu state attrs -- see
        # ScopeDlgScreen and _open_cleanup / _open_sync / _open_optmenu.
        # Maintenance multi-select (#1345) lives on ``self.maintenance_view``
        # now (#88 F5 slice 5b); the engine reaches it via a @property shim.
        self.wt_sel = ListSelection()      # Worktrees list multi-select (#2228 2b)
        self.wt_anchor = None         # Worktrees range-select anchor index (#2258 P3)
        self.last_l = 0               # remembered Worktrees list focus (Tab memory, #2258 P3)
        self._wt_reconcile_after = None  # live: (m,e) targets whose reload must
                                         # settle before reconciling wt_sel (#2258 P3-7)
        # Maintenance actions menu is a native Textual ModalScreen now (#88 F4):
        # no self.maint_menu / maint_menu_idx state attrs -- see MaintMenuScreen
        # and _open_maint_menu. (The overlay left the manual registry entirely.)
        self.progress = None          # cleanup/sync progress sub-dialog
        self.executor = None          # real maintenance executor
        # Real cleanup/sync ops are the DEFAULT: the Maintenance actions
        # actually mutate worktrees (local in-process + remote over SSH), so a
        # Sync/Cleanup the operator runs takes effect (issue #1420). The mock
        # progress walker (safe in-TUI simulation, no side effects) runs ONLY in
        # explicit mock mode -- the dev sandbox for building UX/flows. It is
        # never triggered implicitly. See _resolve_mock_mode: entered via
        # `picker mock`, AGENT_WORKTREES_PICKER_MOCK=1, or the deprecated
        # AGENT_WORKTREES_PICKER_REAL_OPS=0.
        self.mock_mode = _resolve_mock_mode(mock_mode)
        self.real_ops = not self.mock_mode
        self.last_pr = 0              # remembered Profiles grid row (Tab in/out)
        self.btn_idx = 0              # active button within the current group
        self.show_hidden = False      # reveal bridge/system worktrees (#1422)
        # (Profiles grid state -- pcol / grid / applied / targets / host_cols /
        # _prof_unavailable -- AND the load/Apply plumbing -- _prof_load /
        # _prof_apply / _prof_loading / _prof_loaded -- live on
        # self.profiles_view now, reached via the @property + method shims
        # below; #88 F5 slices 3-4.)
        self.debug = "ready"
        # Busy indicator for the always-async control plane: while a background
        # action (``_run_bg``) is in flight, the footer shows the shared animated
        # spinner + this label instead of a static line (see ``footer``/``_tick``).
        self._busy_label = None
        # The cross-plugin verb map backing the OPEN worktree Actions menu; its
        # dispatch reads this so a live in-place verb refine stays consistent.
        self._wt_submenu_ext = {}
        self.data = []
        self.machines = []
        self.pulse = 0
        self.frame = 0
        self.t0 = 0.0
        self.load_delay = {}
        # Injected data source (local / SSH / fixture). ``live`` enables the
        # async per-machine loader the source supplies via ``make_loader()``.
        self.src = source
        self.live = live
        self.loader = None            # async loader (live/multi-machine only)

    # ---- Profiles grid-editing state: shims onto the ProfilesView component --
    # The state lives on ``self.profiles_view`` now (#88 F5 slice 3); these
    # ``@property`` pass-throughs keep every existing engine call site
    # (``setup``, ``_dispatch_key``, the Apply/progress plumbing) and the test
    # suite addressing ``self.grid`` / ``self.pcol`` / ... unchanged.
    @property
    def maint_sel(self):
        return self.maintenance_view.maint_sel

    @maint_sel.setter
    def maint_sel(self, value):
        self.maintenance_view.maint_sel = value

    @property
    def grid(self):
        return self.profiles_view.grid

    @grid.setter
    def grid(self, value):
        self.profiles_view.grid = value

    @property
    def applied(self):
        return self.profiles_view.applied

    @applied.setter
    def applied(self, value):
        self.profiles_view.applied = value

    @property
    def pcol(self):
        return self.profiles_view.pcol

    @pcol.setter
    def pcol(self, value):
        self.profiles_view.pcol = value

    @property
    def targets(self):
        return self.profiles_view.targets

    @targets.setter
    def targets(self, value):
        self.profiles_view.targets = value

    @property
    def host_cols(self):
        return self.profiles_view.host_cols

    @host_cols.setter
    def host_cols(self, value):
        self.profiles_view.host_cols = value

    @property
    def _prof_unavailable(self):
        return self.profiles_view._prof_unavailable

    @_prof_unavailable.setter
    def _prof_unavailable(self, value):
        self.profiles_view._prof_unavailable = value

    @property
    def _prof_load(self):
        return self.profiles_view._prof_load

    @_prof_load.setter
    def _prof_load(self, value):
        self.profiles_view._prof_load = value

    @property
    def _prof_apply(self):
        return self.profiles_view._prof_apply

    @_prof_apply.setter
    def _prof_apply(self, value):
        self.profiles_view._prof_apply = value

    @property
    def _prof_loading(self):
        return self.profiles_view._prof_loading

    @_prof_loading.setter
    def _prof_loading(self, value):
        self.profiles_view._prof_loading = value

    @property
    def _prof_loaded(self):
        return self.profiles_view._prof_loaded

    @_prof_loaded.setter
    def _prof_loaded(self, value):
        self.profiles_view._prof_loaded = value

    # ---- pivot registry (built-ins + cross-plugin registered pivots) ----
    def _load_pivots(self):
        """(Re)scan the manifest registry and rebuild the ordered pivot list.

        Defensive: any discovery failure degrades to the built-ins alone, so a
        bad manifest can never keep the picker from opening. Clamps ``htab`` in
        case a rescan shrank the list.
        """
        try:
            from . import pivots as pivots_mod

            # Self-heal contributed pivots the runtime root may have lost (#2180)
            # before scanning, so e.g. the Tasks pivot survives a reset.
            pivots_mod.ensure_pivots()
            registered = pivots_mod.discover_pivots()
            descriptors = pivots_mod.order_pivots(BUILTIN_PIVOTS, registered)
            wt_actions = pivots_mod.discover_worktree_actions()
            config_sections = pivots_mod.discover_config_sections()
        except Exception:
            registered, descriptors, wt_actions = [], [
                {"label": b, "kind": b.lower(), "pivot": None} for b in BUILTIN_PIVOTS
            ], []
            config_sections = []
        self.registered_pivots = registered
        self.pivots = descriptors
        # Cross-plugin worktree-row actions (a layer augmenting the Worktrees
        # view's Enter sub-menu, e.g. a bridge's "Send message"): discovered
        # from the same manifests, independent of any list pivot (#B).
        self.wt_actions = wt_actions
        # Cross-plugin Configuration sections (a layer augmenting the ⚙
        # Configuration menu, e.g. an SSH or MCP settings home): discovered from
        # the same manifests, independent of any list pivot (#B slice 2).
        self.config_sections = config_sections
        # Tag each pivot with its placement (left cycle / config menu / hidden
        # anchor) so nav machinery can partition them without disturbing the
        # ``order_pivots`` weave that registered ``after`` hints rely on (#1426).
        for d in self.pivots:
            d["placement"] = PIVOT_PLACEMENT.get(d["kind"], "left")
        self.htabs = [d["label"] for d in descriptors]
        if self.htab >= len(self.pivots):
            self.htab = 0

    def _left_pivots(self):
        """Indices of pivots on the left cycle (◀▶ / [ ])."""
        return [i for i, d in enumerate(self.pivots)
                if d.get("placement", "left") == "left"]

    def _config_pivots(self):
        """Indices of pivots hosted under the ⚙ Configuration menu (#1426)."""
        return [i for i, d in enumerate(self.pivots)
                if d.get("placement") == "config"]

    def _kind(self, idx=None):
        """The current pivot's kind: 'worktrees' | 'maintenance' | 'profiles' |
        'registered'. Built-in dispatch keys off this, never a magic index."""
        i = self.htab if idx is None else idx
        if 0 <= i < len(self.pivots):
            return self.pivots[i]["kind"]
        return "worktrees"

    def _reg_pivot(self):
        """The RegisteredPivot for the current pivot, or None for a built-in."""
        if 0 <= self.htab < len(self.pivots):
            return self.pivots[self.htab]["pivot"]
        return None

    def _pivot_machine(self):
        """The machine name the registered pivot's ``list``/actions run against:
        the selected machine sub-tab, or the local machine when 'All' is
        selected (a registered pivot is inherently machine-scoped).

        This returns the tab's *display* name (``machines.yaml`` ``display_name``)
        -- use it for human-facing status lines. For the value handed to a
        contributed pivot's CLI, use :meth:`_pivot_machine_id`."""
        label, m, _e, _ok = self.machines[self.machine_idx]
        if m is not None:
            return m
        loc = self.machines[self.local_index()] if self.machines else (None, None, None, None)
        return loc[1]

    def _machine_key_map(self):
        """Cached ``machines.yaml`` ``display_name -> registry key`` map.

        The registry key is a machine's canonical identity (lowercase; it doubles
        as the SSH-alias base) -- the value ``agent-worktrees get machine`` returns
        and that other multi-machine system tools (agent-dispatch, agent-bridge) match against.
        Tab labels carry the *display* name, so registered-pivot commands need
        this translation. Delegates to :func:`data_ssh.machine_key_map` and caches
        it for the session; any failure degrades to ``{}`` so the caller falls
        back to the display name."""
        cached = getattr(self, "_mkey_map", None)
        if cached is not None:
            return cached
        try:
            from . import data_ssh

            mapping = data_ssh.machine_key_map()
        except Exception:
            mapping = {}
        self._mkey_map = mapping
        return mapping

    def _pivot_machine_id(self):
        """The **canonical machine identity** (``machines.yaml`` registry key) for
        the current registered-pivot scope -- the value a contributed pivot's CLI
        should receive as ``{machine}``.

        A registered pivot's ``{machine}`` names a *machine identity*, not a tab
        label: agent-dispatch resolves the local machine and its SSH aliases by
        the registry key, so handing it the display name (``Anomalous-Potato`` vs the
        identity ``anomalous-potato``) would make it treat the local machine as a
        remote peer or miss a peer's lowercase ``Host`` block. Falls back to the
        display name when the roster can't be read (harmless: a downstream that
        casefolds still matches)."""
        display = self._pivot_machine()
        if not display:
            return display
        return self._machine_key_map().get(display, display)

    def _pivot_scope_key(self):
        """The runtime cache key + ``{machine}`` value for the current registered
        pivot. Machine-scoped pivots key off the selected machine identity; an
        **account-scoped** pivot (a cross-machine shared resource like CodeSpaces)
        keys off a single constant so its ``list`` runs once, not per machine."""
        reg = self._reg_pivot()
        if reg is not None and getattr(reg, "account_scoped", False):
            return ""
        return self._pivot_machine_id()

    def _pivot_runtime(self, reg):
        """Lazily build (and cache) the background runtime for a registered
        pivot -- it shells out to the pivot's ``list`` CLI off the render path."""
        rt = self._pivot_runtimes.get(reg.name)
        if rt is None:
            from . import tasks

            rt = tasks.RegisteredPivotRuntime(reg)
            self._pivot_runtimes[reg.name] = rt
        return rt

    def on_mount(self):
        self.setup()
        self.sel = self.default_sel()
        # NF: focus the region widget that owns the default sel (deferred until
        # the children are mounted). ``_nf_mounted`` stays False until then so the
        # framework's mount-time auto-focus can't move sel.
        self.call_after_refresh(self._nf_initial_focus)
        # Update indicator (#1430): the launcher stages the marketplace update
        # in the background; the picker polls its status file to show a
        # spinner -> checkmark (current) / refresh (update available) next to
        # the version. Poll immediately so the first paint is accurate.
        self.update_state = "idle"
        self._upd_poll_frame = -1
        self._poll_update_state()
        # ~10 fps drives the SSH spinner and the slower live-glyph pulse.
        self.set_interval(0.1, self._tick)

    def on_unmount(self):
        # Picker is tearing down (a launch decision, cancel, or quit). Kill any
        # in-flight SSH prefetch so it never orphans into a heavy git-classify
        # churning on the machine we're about to hand off into -- the picker
        # perf bug where Copilot "slows to a crawl" after launch.
        loader = getattr(self, "loader", None)
        if loader is not None:
            try:
                loader.cancel()
            except Exception:
                pass
        # D2: tear down any held streaming pivot channel (a ``subscribe`` stream
        # runs until close) so no ``list --stream`` child is orphaned on exit.
        for rt in getattr(self, "_pivot_runtimes", {}).values():
            closer = getattr(rt, "close", None)
            if callable(closer):
                try:
                    closer()
                except Exception:
                    pass

    def _poll_update_state(self):
        """Refresh the cached update-indicator state from the stage status.

        Cheap (two small files) and never fatal -- a read hiccup leaves the
        last state in place. Kept off the SSH/tmux hot path by the frame
        throttle in ``_tick``.
        """
        try:
            self.update_state = indicator_state()
        except Exception:
            pass

    def _maybe_repoll(self):
        """Fire a bounded, in-place background refresh of machine state (#1421).

        Keeps the open picker's lists live without a restart. Conservative
        (``POLL_SECS``, default 45s; env-overridable, ``<=0`` disables) and
        courteous: only on the Worktrees/Maintenance tabs (Profiles reads no
        worktree data), skips while a maintenance/apply dialog is up (its own
        reload owns the refresh), never flips a machine to its connect spinner
        (rows update in place), and polls only the machines currently in view --
        a specific-machine tab never fans out to the whole fleet. The loader's
        per-source in-flight guard keeps a slow machine from being re-hit.
        """
        if POLL_SECS <= 0 or self.loader is None:
            return
        if self._kind() not in ("worktrees", "maintenance") or self.progress is not None:
            return
        now = time.monotonic()
        if now - self._last_poll < POLL_SECS:
            return
        self._last_poll = now
        try:
            self.loader.repoll_silent(self._poll_keys())
        except Exception:
            pass
        # Reconcile remote tabs' PR state on their own owning machine, once per
        # source, in the background after first paint (#2102). The local tab's
        # PRs are reconciled separately via the #1423 path in setup().
        recon = getattr(self.loader, "reconcile_remote_prs", None)
        if callable(recon):
            try:
                recon(self._poll_keys())
            except Exception:
                pass

    def _poll_keys(self):
        """The ``(machine, env)`` keys to background-poll: every ready machine on
        the 'All' tab, else just the machine of the current tab (#1421)."""
        if self.is_all():
            return self.ready_envs()
        m, e = self.cur_machine()[:2]
        return {(m, e)}

    def _maybe_repoll_pivot(self):
        """Keep an open registered pivot (Tasks) live without a keypress.

        The registered-pivot runtime caches its ``list`` per scope with no TTL and
        is only invalidated by the pivot's *own* actions -- so a task/card created
        by **another** session (e.g. a claimer posting a steer card) never appears
        in an already-open Tasks pivot. On the same conservative cadence as the
        worktree repoll (``POLL_SECS``; ``<=0`` disables), force a background,
        swap-in-place refetch of the current pivot scope. Skips while a modal /
        progress dialog is up. Cheap: one ``list`` subprocess per interval, and
        the runtime's own in-flight guard coalesces overlapping polls."""
        if POLL_SECS <= 0 or self.progress is not None:
            return
        reg = self._reg_pivot()
        if reg is None:
            return
        now = time.monotonic()
        if now - self._last_pivot_poll < POLL_SECS:
            return
        self._last_pivot_poll = now
        try:
            self._pivot_runtime(reg).repoll(self._pivot_scope_key())
        except Exception:
            pass

    def _tick(self):
        self.frame += 1
        self.pulse = (self.frame // 5) % 2
        busy = False
        # A background action (_run_bg) drives the footer spinner: keep the tick
        # at full fps so it animates.
        if self._busy_label:
            busy = True
        # In live mode, stream in worktrees as each machine's load resolves.
        if self.live and self.loader is not None:
            self.data = self.loader.records()
            _ready, loading, _failed = self.loader.counts()
            busy = busy or loading > 0
            self._maybe_repoll()
            if self._wt_reconcile_after is not None:
                self._process_pending_wt_reconcile()
        # Keep an open registered pivot (Tasks) live too -- independent of the
        # worktree loader / live mode, so a card posted by another session shows
        # up without a manual reload (#staleness).
        self._maybe_repoll_pivot()
        # Poll the launcher's update stage ~twice a second (#1430). While a
        # stage is in flight the spinner should animate, so keep the tick busy.
        if self.frame % 5 == 0:
            self._poll_update_state()
        if self.update_state == "checking":
            busy = True
        # The cleanup/sync/profiles progress run and the recent-messages viewer
        # drive themselves now: both are native Textual ``ModalScreen``s
        # (``ProgressScreen`` / ``MsgViewScreen``, #88 F4) that tick their own
        # advancement / load-repaint on an interval, so the background tick no
        # longer nudges them (advancing progress here would double-step the mock
        # walker; the viewer repaints itself while its loader thread resolves).
        # Full 10 fps only while something is actually animating (the SSH
        # connect spinner or a running progress dialog). When idle, throttle to
        # ~2 fps: keystrokes already repaint synchronously (on_key -> refresh),
        # so this only paces the cosmetic live-glyph pulse -- and it stops the
        # picker from flooding an SSH/tmux link with continuous full-screen
        # repaints (the over-SSH sluggishness the legacy picker never had).
        # Held-arrow flood guard: a pending navigation refresh is serviced here
        # (coalesced to the tick) instead of synchronously per keystroke, so a
        # held arrow can never queue full-screen re-composites faster than they
        # drain. The native OptionList already moved its cursor; this catches
        # the sel-dependent chrome up at tick rate.
        nav = self._nav_dirty
        self._nav_dirty = False
        if busy or nav or self.frame % 5 == 0:
            self.refresh()

    def _advance_progress(self):
        """Drive the progress sub-dialog forward.

        When the run is unarmed (awaiting the extra confirm) nothing advances.
        With the real executor active, mirror its per-item states; otherwise run
        the mock walker (the safe simulation): walk the selected worktrees one
        at a time (pending -> running -> done), paced by the render tick."""
        p = self.progress
        if not p.get("armed", True):
            return
        if p.get("kind") == "action-stream":
            # Driven by the D4 reader thread, not the mock walker.
            return
        if self.executor is not None:
            self._poll_executor()
            return
        p["ticks"] += 1
        cur = p["ticks"] // p["steps"]   # index currently "running"
        items = p["items"]
        for j, it in enumerate(items):
            if it["state"] == "failed":
                continue
            if j < cur:
                it["state"] = "done"
            elif j == cur:
                it["state"] = "running"
            else:
                it["state"] = "pending"
        if cur >= len(items):
            p["done"] = True
            for it in items:
                if it["state"] != "failed":
                    it["state"] = "done"

    def setup(self):
        # Re-scan the pivot registry so a refresh ('r') picks up a newly
        # installed (or removed) contributed pivot without a picker restart.
        self._load_pivots()
        # A manual reload ('r') must also refresh the registered Tasks pivot, not
        # just the worktree lists (the pivot runtime is separate + has no TTL):
        # clear each pivot runtime's cache so the next frame's ensure() refetches,
        # so a task/card created by another session appears on demand.
        for _rt in getattr(self, "_pivot_runtimes", {}).values():
            try:
                _rt.invalidate()
            except Exception:
                pass
        # Machine tabs gain a leading "All" entry that interleaves every machine.
        self.machines = [("All", None, None, True)] + self.src.machines()
        self.machine_idx = self.local_index()
        self.maint_sel = ListSelection()  # drop any stale Maintenance selection
        # Worktrees selection persists across reload (#2258 P3-7): it is NOT
        # hard-cleared here. Survivors are kept and vanished rows dropped by
        # _reconcile_wt_sel() at the end of setup, once the reloaded records are
        # available.
        self._last_poll = time.monotonic()   # first background poll is POLL_SECS out
        self._last_pivot_poll = time.monotonic()  # registered-pivot repoll (#staleness)
        if self.live:
            # Real background SSH loads: one daemon thread per machine,
            # spinner -> ✓/✗. Every source -- local included -- streams in on a
            # thread (#1432), so the picker paints and accepts keys immediately;
            # seed self.data empty and let the render tick fill it as each
            # machine resolves.
            self.data = []
            self.loader = self.src.make_loader()
            self.loader.start()
            self.data = self.loader.records()
        else:
            self.data = self.src.load()
            # Simulate background SSH status loads: local is instant, remotes
            # stagger in, the unreachable one (book2) is permanently disabled.
            self.t0 = time.monotonic()
            self.load_delay = {}
            d = 1.4
            for i, (label, m, e, ok) in enumerate(self.machines):
                if label == "All" or (m, e) == self.src.LOCAL or not ok:
                    self.load_delay[i] = 0.0
                else:
                    self.load_delay[i] = d
                    d += 1.1
        # Profiles matrix axes are config-bound from machines.yaml (via the data
        # source); fall back to the built-in defaults for sources that don't
        # provide them (e.g. fixture sources in tests).
        hc = getattr(self.src, "host_cols", None)
        self.host_cols = (hc() if callable(hc) else None) or list(_DEFAULT_HOST_COLS)
        te = getattr(self.src, "target_envs", None)
        target_env_list = (te() if callable(te) else None) or _DEFAULT_TARGET_ENVS
        # Profiles matrix: seed a "self · agent" profile on each host.
        self.targets = target_rows(target_env_list)
        self.grid = {}
        for ti, t in enumerate(self.targets):
            for hi in range(len(self.host_cols)):
                self.grid[(ti, hi)] = self.cell_locked(ti, hi)
        self.applied = dict(self.grid)   # everything starts "applied"
        self._prof_unavailable = set()   # cleared until a load marks columns
        # Real per-host columns: when the data source exposes profile IO
        # (production data_local / data_ssh), stream each host's saved column
        # in on a background thread so SSH never blocks the UI. Sources without
        # these hooks (fixtures/tests) keep the seeded self·agent diagonal.
        self._prof_load = getattr(self.src, "load_profile_column", None)
        self._prof_apply = getattr(self.src, "apply_profile_column", None)
        self._prof_loaded = False
        if callable(self._prof_load):
            self.profiles_view.start_load()
        # Best-effort background PR-state reconcile (#1423): correct already-
        # merged-but-stale PRs in the tracking store, then re-render so the
        # Picker stops showing merged worktrees as having open PRs. Sources
        # without the hook (fixtures/tests) skip it.
        self._pr_reconciled = False
        rec_fn = getattr(self.src, "reconcile_prs", None)
        if callable(rec_fn):
            self._start_pr_reconcile(rec_fn)
        # #4057/#1416: same after-first-paint pattern for the cached bound-Copilot
        # liveness reconcile -- surfaces a bare-resumed session (cwd=home) in the
        # Active section without a live per-worktree scan on the populate path.
        self._bound_live_reconciled = False
        blr_fn = getattr(self.src, "reconcile_bound_live", None)
        if callable(blr_fn):
            self._start_bound_live_reconcile(blr_fn)
        # Reconcile the persisted Worktrees selection against the freshly loaded
        # records (#2258 P3-7): keep survivors, drop rows that vanished, re-seat
        # a now-invalid range anchor. A no-op while records are still streaming.
        self._reconcile_wt_sel()

    def _start_pr_reconcile(self, rec_fn):
        """Reconcile stale local PR states off the UI thread, then reload (#1423).

        Never blocks the first paint and never raises: a provider that is
        unconfigured/unreachable simply leaves the tracking state as-is. Only
        triggers a reload when something actually changed, so an all-current
        store costs one silent pass.
        """
        def work():
            try:
                changed = rec_fn()
            except Exception:
                changed = 0
            if changed:
                try:
                    self._reload_local_after_reconcile()
                except Exception:
                    pass
            self._pr_reconciled = True

        threading.Thread(target=work, name="pr-reconcile", daemon=True).start()

    def _start_bound_live_reconcile(self, blr_fn):
        """Reconcile cached bound-Copilot liveness off the UI thread, then reload.

        Mirrors :meth:`_start_pr_reconcile` (#4057/#1416): resolves the machine's
        live bound Copilots via the authoritative scan and stamps each worktree's
        cached ``bound_live`` so a bare-resumed session surfaces ACTIVE. Never
        blocks the first paint and never raises; only reloads when a bound-liveness
        transition actually happened (an all-current store costs one silent pass).
        """
        def work():
            try:
                changed = blr_fn()
            except Exception:
                changed = 0
            if changed:
                try:
                    self._reload_local_after_reconcile()
                except Exception:
                    pass
            self._bound_live_reconciled = True

        threading.Thread(
            target=work, name="bound-live-reconcile", daemon=True).start()

    def _reload_local_after_reconcile(self):
        """Re-fetch the local machine's rows after a PR reconcile wrote back.

        Mirrors the post-maintenance reload (#1421): in live mode the local
        source re-threads and the render tick picks up the fresh records; in the
        non-live path the data is reloaded in-place."""
        m, e = self.src.LOCAL
        if self.live and self.loader is not None:
            self.loader.reload(m, e)
        elif not self.live:
            self.data = self.src.load()

    def button_set(self):
        kind = self._kind()
        if kind == "profiles":
            return ["PA", "PReset"] if self.grid_dirty() else ["PA"]
        if kind == "worktrees":
            # New worktree always; the bulk Clean / Sync buttons (which replaced
            # the standalone Maintenance view, #1427) whenever there are
            # worktrees in scope to act on; Toggle-hidden only when there's
            # something to reveal (or it's already revealing) so it never
            # clutters (#1422).
            bset = ["N"]
            if self._scope_data():
                bset += ["K", "SY"]
            if self.show_hidden or self._hidden_count() > 0:
                bset.append("TH")
            return bset
        return BUTTON_SETS.get(kind, [])

    def active_button(self):
        bset = self.button_set()
        if not bset:
            return None
        return bset[self.btn_idx % len(bset)]

    def grid_dirty(self):
        return self.profiles_view.grid_dirty()

    def pending_count(self):
        return self.profiles_view.pending_count()

    def cell_locked(self, ti, hi):
        return self.profiles_view.cell_locked(ti, hi)

    def machine_state(self, i):
        label, m, e, ok = self.machines[i]
        if label == "All":
            return "ready"
        if not ok:
            return "disabled"
        if self.live:
            # Real per-machine load status: loading | ready | failed.
            return self.loader.state(m, e)
        if (m, e) == self.src.LOCAL:
            return "ready"
        return "ready" if (time.monotonic() - self.t0) >= self.load_delay[i] else "loading"

    def ready_envs(self):
        out = set()
        for i, (label, m, e, ok) in enumerate(self.machines):
            if label != "All" and self.machine_state(i) == "ready":
                out.add((m, e))
        return out

    def spin(self):
        return SPINNER[self.frame % len(SPINNER)]

    def local_index(self):
        for i, (label, m, e, ok) in enumerate(self.machines):
            if (m, e) == self.src.LOCAL:
                return i
        return 1 if len(self.machines) > 1 else 0

    # ---- model helpers ----
    def is_all(self):
        return self.machines[self.machine_idx][1] is None

    # ---- registered-pivot task data (read-only, background-loaded) ----
    def _task_state(self):
        """(state, rows, error) for the current registered pivot at the current
        machine. ``state`` is idle|loading|ready|error. Triggers a background
        fetch of the pivot's ``list`` CLI on first view of a machine."""
        reg = self._reg_pivot()
        if reg is None:
            return ("idle", [], "")
        machine = self._pivot_scope_key()
        rt = self._pivot_runtime(reg)
        rt.ensure(machine)
        return rt.get(machine)

    def _task_rows(self):
        """The flat, selectable list of task entries (dicts) for the current
        registered pivot -- the ('T', i) stops index into this."""
        rows = self._task_state()[1]
        return rows if isinstance(rows, list) else []

    def _task_summary(self):
        """The current registered pivot's summary dict (D1) for the current
        machine -- the substitution source for its ``summary`` header line.
        ``{}`` for a built-in pivot or a provider that emitted a bare array.
        Defensive: a runtime without ``get_summary`` (an older/fixture runtime)
        degrades to ``{}`` rather than raising."""
        reg = self._reg_pivot()
        if reg is None:
            return {}
        rt = self._pivot_runtime(reg)
        getter = getattr(rt, "get_summary", None)
        if getter is None:
            return {}
        return getter(self._pivot_scope_key())

    def _worktree_title_map(self):
        """``{short-id: title}`` from the Picker's loaded worktree records -- the
        lookup that correlates an account-scoped pivot's *claiming worktree id*
        (e.g. a CodeSpace lease's 4-hex beacon) to the owning worktree's title.
        Keyed by both the 4-hex ``id4`` and the full ``id`` (lower-cased)."""
        out: dict[str, str] = {}
        for r in (getattr(self, "data", None) or []):
            if not isinstance(r, dict):
                continue
            title = str(r.get("title") or "")
            if not title:
                continue
            for f in ("id4", "id"):
                v = r.get(f)
                if v:
                    out[str(v).strip().lower()] = title
        return out

    def _enrich_pivot_rows(self, reg, rows):
        """Fill each row's ``worktree_title`` from the claiming-worktree
        correlation (``reg.worktree_field`` value -> owning worktree title), so a
        columns pivot can show the claimant's TASK. In-place + idempotent;
        best-effort (no match -> ``""``). A no-op when the pivot declares no
        ``worktree_field`` or there are no worktree records to match against."""
        if not reg or not getattr(reg, "worktree_field", None) or not rows:
            return
        titles = self._worktree_title_map()
        for rec in rows:
            if not isinstance(rec, dict):
                continue
            wt = rec.get(reg.worktree_field)
            rec["worktree_title"] = titles.get(str(wt).strip().lower(), "") if wt else ""

    def _task_groups(self):
        """Task rows grouped for display. Groups by the pivot's ``group`` entry
        field (``group_field``) when the manifest declares one -- e.g. the
        agent-dispatch board's status group (Blocked/Proposed/Queued/Started/
        Completed/Abandoned) -- otherwise by the worktree field (the default
        pin-based grouping). Returns ``[(group_label, [(row_index, entry), ...]),
        ...]`` in first-seen order, so a ``list`` provider that already emits its
        rows in the intended section order (as ``--board`` does) controls the
        section order too."""
        reg = self._reg_pivot()
        rows = self._task_rows()
        if reg is None:
            return []
        group_key = reg.group_field or reg.worktree_field
        default_label = "· ungrouped" if reg.group_field else "· unpinned"
        groups: dict[str, list] = {}
        order: list[str] = []
        for i, r in enumerate(rows):
            gv = r.get(group_key) if group_key else None
            key = gv or default_label
            if key not in groups:
                groups[key] = []
                order.append(key)
            groups[key].append((i, r))
        return [(k, groups[k]) for k in order]

    def _selected_task(self):
        """The task entry under the ('T', i) cursor, or None."""
        if self.sel[0] != "T":
            return None
        rows = self._task_rows()
        i = self.sel[1]
        return rows[i] if 0 <= i < len(rows) else None

    def cur_machine(self):
        label, m, e, ok = self.machines[self.machine_idx]
        return m, e, ok

    def _scope_data(self):
        """Worktrees in the active machine-tab scope (All = every ready env)."""
        if self.is_all():
            ready = self.ready_envs()
            return [w for w in self.data if (w["machine"], w["env"]) in ready]
        m, e, _ = self.cur_machine()
        return [w for w in self.data if w["machine"] == m and w["env"] == e]

    def _hidden_count(self):
        """How many bridge/system worktrees are hidden in the current scope."""
        return sum(1 for w in self._scope_data() if w.get("hidden"))

    def _visible_scope_data(self):
        data = self._scope_data()
        if not self.show_hidden:
            data = [w for w in data if not w.get("hidden")]
        return data

    def current_list(self):
        """(cols, [(section_label, [records])]) for the selected machine tab.
        'All' interleaves every READY machine and shows the machine/env columns;
        a specific machine hides them (implied by the tab). Bridge/system
        worktrees are hidden unless Toggle-hidden is on (#1422). Worktrees with
        no owning Copilot session are split into a distinct 'Unowned' section so
        selecting one never silently cold-starts a blank conversation (#1026)."""
        cols = ACTIVE_SPECS if self.is_all() else LIST_SPECS
        a, r, c = self.src.bucket(self._visible_scope_data())
        unowned = [w for w in r if w.get("sessionless")]
        if unowned:
            r = [w for w in r if not w.get("sessionless")]
            return cols, [
                ("Active", a), ("Recent", r), ("Completed", c),
                ("Unowned · no prior session (Open starts fresh)", unowned),
            ]
        return cols, [("Active", a), ("Recent", r), ("Completed", c)]

    def list_records(self):
        _cols, secs = self.current_list()
        out = []
        for _label, rows in secs:
            out.extend(rows)
        return out

    def create_target(self):
        """Where '+ New Worktree' lands: the active machine, or LOCAL when on
        'All'."""
        if self.is_all():
            return self.src.LOCAL
        m, e, _ = self.cur_machine()
        return (m, e)

    def _update_actionable(self) -> bool:
        """True when the update indicator is a focusable action (#1430).

        Only when an update is *staged* (``available``) is there something to do
        (Enter = apply + restart); the spinner/✓ states are informational.
        """
        return getattr(self, "update_state", "idle") == "available"

    def _v_stops(self):
        """Top-region vertical stops, in visual (top-to-bottom) order: the update
        refresh icon ("UPD", 0) on the title line when an update is staged, then
        the View pivot row ("V", 0). The ⚙ Configuration entry is NOT a vertical
        stop -- it rides the pivot row's horizontal ◀▶ nav (#1426)."""
        out = []
        if self._update_actionable():
            out.append(("UPD", 0))
        out.append(("V", 0))
        return out

    def stops(self):
        """Vertical Up/Down flow. ("UPD",0)=update refresh icon (only when an
        update is staged), ("V",0)=View pivot row, ("M",0)=machine picker,
        ("BTN",0)=button row, then the table/grid rows."""
        if self._kind() == "worktrees":
            out = [*self._v_stops(), ("M", 0), ("BTN", 0)]
            for i in range(len(self.list_records())):
                out.append(("L", i))
        elif self._kind() == "maintenance":
            out = [*self._v_stops(), ("M", 0), ("BTN", 0)]
            groups = self.maint_groups()
            if any(rows for _st, rows in groups):
                out.append(("SA", 0))   # the "Select all" checkbox
            li = 0
            for gi, (_st, rows) in enumerate(groups):
                out.append(("GH", gi))
                for _ in rows:
                    out.append(("C", li))
                    li += 1
        elif self._kind() == "registered":
            # Registered pivot: View nav + machine sub-nav, then one stop per
            # task row (grouped rows are flattened in first-seen order).
            out = [*self._v_stops(), ("M", 0)]
            for i in range(len(self._task_rows())):
                out.append(("T", i))
        else:
            out = [*self._v_stops()]
            for i in range(len(self.targets)):
                out.append(("PR", i))
            out.append(("BTN", 0))   # Apply/Reset at the bottom
        return out

    def _pr_head(self):
        """Grid-region entry point, restoring the last-focused row (#1288).
        pcol (the host column) already persists across Tab in/out."""
        return ("PR", min(self.last_pr, max(0, len(self.targets) - 1)))

    def region_head(self, zone):
        if zone == "PR":
            return self._pr_head()
        if zone == "L":
            return self._l_head()
        return {"V": ("V", 0), "UPD": ("V", 0), "CFG": ("CFG", 0), "M": ("M", 0),
                "BTN": ("BTN", 0), "L": ("L", 0), "SA": ("SA", 0),
                "GH": ("GH", 0), "C": ("C", 0), "PR": ("PR", 0)}.get(
                    zone, ("V", 0))

    def region_heads(self):
        """Tab/Shift+Tab jump targets — the entry point of each major region.
        The View pivot row is one region; the ⚙ Configuration entry rides its
        horizontal ◀▶ nav, so Tab lands on the pivots and ◀▶ reaches Config."""
        v = [("V", 0)]
        if self._kind() == "worktrees":
            heads = [*v, ("M", 0), ("BTN", 0)]
            if self.list_records():
                heads.append(self._l_head())
        elif self._kind() == "maintenance":
            heads = [*v, ("M", 0), ("BTN", 0)]
            if self.maint_records():
                heads.append(("SA", 0))   # Tab into the selection/list region
        elif self._kind() == "registered":
            heads = [*v, ("M", 0)]
            if self._task_rows():
                heads.append(("T", 0))
        else:
            heads = [*v, self._pr_head(), ("BTN", 0)]
        return heads

    def default_sel(self):
        kind = self._kind()
        d = {"worktrees": ("BTN", 0), "maintenance": ("BTN", 0),
             "profiles": ("PR", 0), "registered": ("M", 0)}.get(kind, ("BTN", 0))
        # The Profiles default (``("PR", 0)``) is only valid when there is at
        # least one target row. With no targets (or no host columns) that stop
        # doesn't exist, so fall back to the first real stop instead of handing
        # back a phantom the caller would ``stops.index()`` on (ValueError).
        stops = self.stops()
        if d not in stops:
            return stops[0] if stops else d
        return d

    def anchors(self):
        return self.region_heads()

    def cleanup_rows(self):
        """Maintenance worktree list, scoped to the active machine sub-pivot
        (All = every machine), each tagged with its prune disposition.

        Shows every in-scope worktree -- including in-use/work-bearing ones --
        so the disposition column is honest; the Cleanup dialog only *offers*
        the cleanable buckets, and the executor re-checks safety per worktree.
        """
        rows = self._visible_scope_data()
        for w in rows:
            bucket = w.get("cleanup_bucket", "wip")
            lvl = derive.BUCKET_DISPO.get(bucket, "")
            txt = derive.BUCKET_REASON.get(bucket, "")
            # Blended disposition (verdict + reason in one colored chip).
            w["dispo_level"] = lvl
            w["dispo"] = f" {DISPO_MARK[lvl]} {txt}" if lvl else ""
        return rows

    # ---- Maintenance grouping + multi-select (#1345) ----
    # State (``maint_sel``) + grouping/multi-select behaviour live on
    # ``self.maintenance_view`` now (#88 F5 slice 5b); these thin shims keep the
    # engine call sites (``_open_maint_menu`` / ``_dispatch_key`` / ``_activate``
    # / the executor poll) and the test suite addressing ``self.maint_groups()``
    # / ``self.maint_records()`` / ``self._toggle_maint()`` unchanged.
    def maint_groups(self):
        return self.maintenance_view.maint_groups()

    def maint_records(self):
        return self.maintenance_view.maint_records()

    def _maint_ids(self):
        return self.maintenance_view._maint_ids()

    def _toggle_maint(self, i):
        self.maintenance_view._toggle_maint(i)

    def _toggle_maint_all(self):
        self.maintenance_view._toggle_maint_all()

    def _toggle_group(self, gi):
        self.maintenance_view._toggle_group(gi)

    def _open_maint_menu(self):
        """Open the Maintenance actions menu for the selected set; if nothing
        is selected, select the focused row and open it for that one (#1345).

        Migrated to a native Textual ``ModalScreen`` (#88 F4): ``push_screen``s a
        ``MaintMenuScreen`` with the available actions and returns the chosen
        action *index* via ``dismiss(int|None)``; ``_run_maint_action`` runs the
        selection (``None`` cancels)."""
        if not self.maint_sel:
            rec = self._selected_record()
            if not rec:
                return
            self.maint_sel.replace({rec["id4"]})
        ids = self.maint_sel.ids
        chosen = [r for r in self.maint_records() if r["id4"] in ids]
        acts = []
        if any(r.get("ff_eligible") for r in chosen):
            acts.append("Sync")
        if any(self._cleanable(r) for r in chosen):
            acts.append("Cleanup")
        if not acts:
            # Nothing actionable for this selection (no FF-eligible or cleanable
            # worktree) -- don't open an empty menu.
            self.debug = (f"no maintenance action for {len(chosen)} "
                          f"selected worktree(s)")
            return
        self._push_maint_menu(ids, acts, len(chosen))

    def _push_maint_menu(self, ids, acts, count):
        """Push the Maintenance actions ModalScreen for ``acts`` over the ``ids``
        set (``count`` worktrees), running the chosen action on dismiss. Shared
        by both openers (the maintenance selection and the Worktrees-list bulk
        action menu), which build ``ids``/``acts`` differently but dispatch
        identically (#88 F4)."""
        def _after(choice):
            if choice is None:
                return
            self._run_maint_action(acts[choice], ids)
        self.app.push_screen(MaintMenuScreen(acts, count), _after)

    def _run_maint_action(self, act, ids):
        """Run one Maintenance action against the ``ids`` set. Mirrors the former
        ``_key_maint_menu`` Enter branch exactly (#88 F4)."""
        if act == "Sync":
            self._open_sync(ids=ids)
        elif act == "Cleanup":
            self._open_cleanup(ids=ids)
        elif act == "Finalize":
            self._start_finalize(
                [r for r in self.list_records() if r["id4"] in ids])
        elif act == "Stop":
            self._start_stop(
                [r for r in self.list_records() if r["id4"] in ids])
        elif act == "Reclaim":
            self._start_reclaim(
                [r for r in self.list_records() if r["id4"] in ids])

    # ---- Worktrees list multi-select (#2228 Phase 2b, #2258 Phase 3) ----
    def _l_ids(self):
        """The id4 of every Worktrees row, in display order."""
        return [r["id4"] for r in self.list_records()]

    def _wt_focused_id(self):
        """The id4 of the currently focused Worktrees row, or None when focus is
        outside the list."""
        if self.sel[0] != "L":
            return None
        ids = self._l_ids()
        i = self.sel[1]
        return ids[i] if 0 <= i < len(ids) else None

    def _wt_multiselect_active(self):
        """True when the Worktrees list is in a discoverable *multi-select* state
        (#2258 follow-up): more than one row selected, or the (single) selection
        has diverged from the focused row (e.g. after Ctrl+Arrow moved focus off
        it). In the common single-select-tracks-focus case the selection is just
        the focused row, so the checkbox gutter stays hidden -- it is only shown
        once the operator is actually building/holding a set."""
        if not self.wt_sel:
            return False
        if len(self.wt_sel) > 1:
            return True
        return self._wt_focused_id() not in self.wt_sel

    def _l_head(self):
        """Worktrees list entry point for Tab, restoring the last-focused row
        (#2258 P3-6, mirrors the Profiles-grid cell memory #1288)."""
        n = len(self.list_records())
        if n == 0:
            return ("L", 0)
        return ("L", min(self.last_l, n - 1))

    def _reconcile_wt_sel(self):
        """Keep the Worktrees selection honest across a reload (#2258 P3-7).

        Intersect the selection with the ids still present and reset the range
        anchor (row indices may have shifted, so a stale index would extend the
        wrong range -- the next Shift gesture re-seeds it from the live focus).
        Guarded against the live empty-load race: while the reloaded records are
        still streaming in (``list_records`` momentarily empty) this is a no-op,
        so a transient empty frame never clobbers a built-up selection.
        """
        try:
            recs = self.list_records()
        except Exception:
            return
        if not recs:
            return
        present = {r["id4"] for r in recs}
        if self.wt_sel:
            self.wt_sel.replace(self.wt_sel.ids & present)
        self.wt_anchor = None

    def _rehome_l_focus(self):
        """Keep list focus at the equivalent index after a reload removed rows
        (#2258 P3-7): clamp ``self.sel`` into the current list, or fall back to a
        safe default when the list emptied."""
        if self.sel[0] != "L":
            return
        n = len(self.list_records())
        if n == 0:
            self.sel = self.default_sel()
        elif self.sel[1] >= n:
            self.sel = ("L", n - 1)

    def _process_pending_wt_reconcile(self):
        """Live mode: defer the post-operation selection reconcile until the
        reloaded machine(s) actually settle (#2258 P3-7).

        ``_refresh_after_maint`` kicks off asynchronous per-machine reloads, so
        reconciling immediately would race the streaming load and could drop
        survivors that simply haven't re-arrived yet. Instead we hold the touched
        targets and reconcile from ``_tick`` once every one reports ``ready``
        (or failed -- a machine that can't reload should not wedge the pending
        reconcile forever)."""
        targets = self._wt_reconcile_after
        if not targets or self.loader is None:
            self._wt_reconcile_after = None
            return
        try:
            settled = all(self.loader.state(m, e) in ("ready", "failed", "error")
                          for m, e in targets)
        except Exception:
            settled = True
        if settled:
            self._wt_reconcile_after = None
            self._reconcile_wt_sel()
            self._rehome_l_focus()

    def _wt_track_focus(self):
        """Plain-arrow rule (#2258 P3-1): the selection follows focus.

        When focus lands on a Worktrees row, collapse the multi-select to just
        that row and re-seat the range anchor there (single-select tracks
        focus); when focus leaves the list, the selection follows it to nothing.
        """
        if self.sel[0] == "L":
            ids = self._l_ids()
            i = self.sel[1]
            if 0 <= i < len(ids):
                self.wt_sel.replace({ids[i]})
                self.wt_anchor = i
                return
        if self.wt_sel:
            self.wt_sel.clear()
        self.wt_anchor = None

    def _wt_shift_move(self, stops, idx, forward):
        """Shift+arrow (#2258 P3-2): range-extend from the anchor.

        On the Worktrees list, move focus one row (clamped inside the list) and
        set the selection to the contiguous range from the anchor (seeded on the
        first shift move) to the newly focused row. Off the list it degrades to
        a plain focus move.
        """
        if self.sel[0] != "L":
            self.sel = (stops[min(idx + 1, len(stops) - 1)] if forward
                        else stops[max(idx - 1, 0)])
            self._wt_track_focus()
            return
        ids = self._l_ids()
        if not ids:
            return
        if self.wt_anchor is None or not (0 <= self.wt_anchor < len(ids)):
            self.wt_anchor = self.sel[1]
        new_i = max(0, min(self.sel[1] + (1 if forward else -1), len(ids) - 1))
        self.sel = ("L", new_i)
        lo, hi = sorted((self.wt_anchor, new_i))
        self.wt_sel.replace(ids[lo:hi + 1])

    def _wt_ctrl_move(self, stops, idx, forward):
        """Ctrl+arrow (#2258 P3-4): move focus only.

        Move the focus cursor one Worktrees row (clamped inside the list)
        without touching the selection or the range anchor, so the operator can
        navigate a built-up set without disturbing it. Off the list it degrades
        to a plain focus move (selection untouched)."""
        if self.sel[0] != "L":
            self.sel = (stops[min(idx + 1, len(stops) - 1)] if forward
                        else stops[max(idx - 1, 0)])
            return
        ids = self._l_ids()
        if not ids:
            return
        new_i = max(0, min(self.sel[1] + (1 if forward else -1), len(ids) - 1))
        self.sel = ("L", new_i)

    def _wt_collapse_selection(self):
        """Esc-collapse (#2258 P3-5): reduce a multi-selection, don't quit.

        With more than one row selected, reduce to just the focused row (or to
        nothing when focus is outside the list) and return True so Esc does NOT
        also open the quit-confirm (#1429). Returns False when there is nothing
        to collapse, letting Esc fall through to the quit prompt.
        """
        if len(self.wt_sel) <= 1:
            return False
        if self.sel[0] == "L":
            ids = self._l_ids()
            i = self.sel[1]
            if 0 <= i < len(ids):
                self.wt_sel.replace({ids[i]})
                self.wt_anchor = i
                self.debug = "collapsed selection to focused row"
                return True
        self.wt_sel.clear()
        self.wt_anchor = None
        self.debug = "collapsed selection"
        return True

    def _toggle_wt(self, i):
        """Space on a Worktrees row toggles it in the list selection (#2258
        P3-3: additive, independent of the rest) and re-seats the range anchor
        there so a following Shift+arrow extends from this row."""
        recs = self.list_records()
        if 0 <= i < len(recs):
            wid = recs[i]["id4"]
            now_on = self.wt_sel.toggle(wid)
            self.wt_anchor = i
            self.debug = (f"{'selected' if now_on else 'deselected'} {wid}"
                          f" · {len(self.wt_sel)} selected")

    def _open_wt_action_menu(self):
        """Enter on the Worktrees list with a multi-selection opens the bulk
        action menu (Sync / Cleanup) for the selected set -- the same
        ``maint_menu`` the eliminated Maintenance view used, so Sync/Cleanup run
        through the identical scoped executor (#2228 2b). A single focused row
        with no selection keeps opening its per-row sub-menu (which carries
        Open/Resume) -- see ``_activate``."""
        ids = self.wt_sel.ids
        chosen = [r for r in self.list_records() if r["id4"] in ids]
        acts = []
        if any(r.get("ff_eligible") for r in chosen):
            acts.append("Sync")
        if any(self._cleanable(r) for r in chosen):
            acts.append("Cleanup")
        if any(r.get("cleanup_bucket") in ("conversation", "unused")
               for r in chosen):
            acts.append("Finalize")
        if any(r.get("mux_live") for r in chosen):
            acts.append("Stop")
        if any(PickerScreen._reclaimable(r) for r in chosen):
            # Bulk parity with the per-row menu: reap the un-muxed bound Copilots
            # across the selection -- the ones Stop cannot reach (#4058).
            acts.append("Reclaim")
        if not acts:
            self.debug = (f"no bulk action for {len(chosen)} "
                          f"selected worktree(s)")
            return
        self._push_maint_menu(ids, acts, len(chosen))

    # ---- Profiles matrix helpers ----
    def profiles_present(self):
        return self.profiles_view.profiles_present()

    # ---- Profiles: real per-host column load + Apply (own-column model) ----
    def _column_sels(self, hi):
        return self.profiles_view._column_sels(hi)

    def _apply_profiles(self):
        return self.profiles_view.apply()

    def _btn_style(self, focus, is_active):
        """Focused active button glows; unfocused active button shows a subtle
        'last-focused' highlight; others are at rest."""
        if focus and is_active:
            return C_BTN_SEL
        if (not focus) and is_active:
            return C_BTN_LAST
        return C_BTN

    def two_button_row(self, l1, l2, focus, active_idx, suffix, width):
        t = Text("  ")
        t.append(f" {l1} ", style=self._btn_style(focus, active_idx == 0))
        t.append("   ")
        t.append(f" {l2} ", style=self._btn_style(focus, active_idx == 1))
        if suffix and t.cell_len + 4 + len(suffix) <= width:
            t.append("    " + suffix, style=C_DIM)
        t.append(" " * max(0, width - t.cell_len))
        return t

    def _action_row_caption(self, focus, active_idx, bset, tm, te, host_tag):
        """The dim caption trailing the Worktrees action buttons -- specific to
        the *focused* button (operator feedback on #1427): New shows where it
        creates; Clean/Sync show the live count of worktrees the op would touch;
        Toggle shows the reveal/hide count. Defaults to the New caption when the
        row isn't focused."""
        code = bset[active_idx] if (focus and 0 <= active_idx < len(bset)) else "N"
        ctx = Text()
        if code == "K":
            n = sum(1 for r in self.list_records() if self._cleanable(r))
            ctx.append("    cleans ", style=C_DIM)
            ctx.append(f"{n}", style=C_LABEL)
            ctx.append(f" merged / idle worktree{'' if n == 1 else 's'} in ",
                       style=C_DIM)
            ctx.append(self._scope_label(), style=C_META)
        elif code == "SY":
            n = sum(1 for r in self.list_records() if r.get("ff_eligible"))
            ctx.append("    fast-forwards ", style=C_DIM)
            ctx.append(f"{n}", style=C_LABEL)
            ctx.append(f" eligible worktree{'' if n == 1 else 's'} in ",
                       style=C_DIM)
            ctx.append(self._scope_label(), style=C_META)
        elif code == "TH":
            nh = self._hidden_count()
            ctx.append(f"    {'hides' if self.show_hidden else 'reveals'} ",
                       style=C_DIM)
            ctx.append(f"{nh}", style=C_LABEL)
            ctx.append(" bridge / system worktree(s)", style=C_DIM)
        else:                                   # New worktree (default)
            ctx.append("    creates on ", style=C_DIM)
            ctx.append(f"{tm} ", style=C_META)
            ctx.append(te, style=C_ENV.get(te, C_META))
            if host_tag:
                ctx.append(host_tag, style=C_DIM)
        return ctx

    def new_worktree_row(self, width, focus, active_idx):
        """The Worktrees action row. New worktree opens the options dialog
        (#1346); the bulk Clean / Sync buttons opened here replaced the standalone
        Maintenance view (#1427); a right-aligned Toggle-hidden chip joins when
        something is hidden (#1422). Chips render generically from ``button_set``
        so adding a button never needs a hardcoded index."""
        bset = self.button_set()
        tm, te = self.create_target()
        host_tag = "  (this host)" if (tm, te) == self.src.LOCAL else ""
        labels = {"N": " + New worktree… ", "K": " ✕ Clean ", "SY": " ⟳ Sync "}

        t = Text("  ")
        first = True
        for i, code in enumerate(bset):
            if code == "TH":
                continue                       # right-aligned, handled below
            if not first:
                t.append("   ")
            first = False
            t.append(labels.get(code, f" {code} "),
                     style=self._btn_style(focus, active_idx == i))

        toggle = None
        if "TH" in bset:
            th_i = bset.index("TH")
            nh = self._hidden_count()
            tlabel = " Hide hidden " if self.show_hidden else f" Show hidden ({nh}) "
            toggle = Text(tlabel, style=self._btn_style(focus, active_idx == th_i))

        ctx = self._action_row_caption(focus, active_idx, bset, tm, te, host_tag)

        right_w = (toggle.cell_len + 2) if toggle is not None else 0
        if t.cell_len + ctx.cell_len + 3 + right_w <= width:
            t.append_text(ctx)
        if toggle is not None:
            t.append(" " * max(1, width - t.cell_len - right_w))
            t.append_text(toggle)
            t.append("  ")
        else:
            t.append(" " * max(0, width - t.cell_len))
        return t

    def button_row(self, label, suffix, selected, width):
        """A row that reads as a button: a filled chip + dim trailing context
        (the context is dropped when it doesn't fit)."""
        t = Text("  ")
        t.append(f" {label} ", style=C_BTN_SEL if selected else C_BTN)
        if suffix and t.cell_len + 3 + len(suffix) <= width:
            t.append("   " + suffix, style=C_DIM)
        t.append(" " * max(0, width - t.cell_len))
        return t

    # ---- Maintenance row rendering (#1345) ----
    def _checkbox(self, checked):
        return ("☑", "green") if checked else ("☐", "grey50")

    # ---- build the scrollable body as VRows ----
    def build_body(self, width):
        vrows = []
        cur_band = None
        cur_section = None

        def add(text, stop=None, kind=None, data=None, new_section=None):
            # ``new_section`` lets an extracted body component (e.g.
            # MaintenanceView, #88 F5) open a section without reaching into this
            # closure's ``cur_section``/``vrows``: it pins the section to the
            # label + the vrow index this row will occupy, exactly as the inline
            # branches do via ``cur_section = (label, len(vrows))``.
            nonlocal cur_section
            if new_section is not None:
                cur_section = (new_section, len(vrows))
            vr = VRow(text, stop, kind, data)
            vr.pin_band = cur_band
            vr.pin_section = cur_section
            vrows.append(vr)
            return vr

        sel = self.sel
        if self._kind() == "worktrees":
            self.worktrees_view.build(add, width, sel)
        elif self._kind() == "maintenance":
            self.maintenance_view.build(add, width, sel)
        elif self._kind() == "registered":
            self.tasks_view.build(add, width, sel)
        else:
            self.profiles_view.build(add, width, sel)
        return vrows

    def _current_view(self):
        return {
            "worktrees": self.worktrees_view,
            "maintenance": self.maintenance_view,
            "registered": self.tasks_view,
        }.get(self._kind(), self.profiles_view)

    def _render_sig(self, W, H):
        """A cheap fingerprint of everything the derived frame / split depend on
        (#169). Two sibling segment widgets rendering in one paint pass share the
        same signature, so the memoized frame is built once and reused; any state
        change (a nav, a scroll, a reload, a machine/pivot switch, a direct
        attribute set from the capture seam) shifts the signature and forces a
        single rebuild. Mirrors the native list's own data signature, widened
        with the focus-cursor state (``sel`` / ``btn_idx`` / ``pcol``) and scroll
        offsets the chrome + body window also key on."""
        try:
            kind = self._kind()
            if kind == "registered":
                nrows = len(self._task_rows())
            elif kind == "maintenance":
                nrows = len(self.maint_records())
            else:
                nrows = len(self.list_records())
        except Exception:
            kind, nrows = None, -1
        wt = tuple(sorted(self.wt_sel.ids)) if hasattr(self, "wt_sel") else ()
        return (W, H, self.sel, self.top, self._data_top, kind, self.htab,
                self.machine_idx, self.btn_idx, getattr(self, "pcol", 0),
                nrows, wt, getattr(self, "pulse", 0),
                getattr(self, "update_state", None), getattr(self, "debug", None))

    def _build_body_split(self, width, sel=None):
        """Return ``(chrome_vrows, data_vrows)`` for the current pivot -- the
        fixed machine-scope + button chrome vs the scrolling data -- by driving
        the view's ``build_chrome`` / ``build_data`` emitters into two separate
        VRow sinks (#88 NF3). Concatenated, the rendered rows equal
        ``build_body(width)`` byte-for-byte; the split lets the compose tree
        render the chrome fixed and scroll only the data. ``sel`` defaults to the
        live ``self.sel``; the native OptionList body (#88 NF5-5) passes a
        sentinel sel so no focus-cursor highlight is baked into the row text (the
        native widget owns the cursor)."""
        use_sel = self.sel if sel is None else sel
        H = self.size.height or 30
        key = (self._render_sig(width, H), use_sel)
        cache = self._split_cache
        if cache is not None and cache[0] == key:
            return cache[1]

        def make_sink():
            vrows = []
            section = {"cur": None}

            def add(text, stop=None, kind=None, data=None, new_section=None):
                if new_section is not None:
                    section["cur"] = (new_section, len(vrows))
                vr = VRow(text, stop, kind, data)
                vr.pin_section = section["cur"]
                vrows.append(vr)
                return vr
            return vrows, add

        view = self._current_view()
        chrome, add_c = make_sink()
        view.build_chrome(add_c, width, use_sel)
        data, add_d = make_sink()
        view.build_data(add_d, width, use_sel)
        self._split_cache = (key, (chrome, data))
        return chrome, data

    def _build_data_vrows(self, width, sel=None):
        """Data-only VRows for the current pivot (no chrome) -- used by the
        native OptionList body (#88 NF5-5), which renders the chrome separately
        and must not drive ``build_chrome`` (e.g. ``tab_bar``) before the screen
        is set up. ``sel`` defaults to ``self.sel``; a sentinel suppresses the
        focus-cursor highlight so the native widget owns the cursor."""
        use_sel = self.sel if sel is None else sel
        vrows = []
        section = {"cur": None}

        def add(text, stop=None, kind=None, data=None, new_section=None):
            if new_section is not None:
                section["cur"] = (new_section, len(vrows))
            vr = VRow(text, stop, kind, data)
            vr.pin_section = section["cur"]
            vrows.append(vr)
            return vr

        self._current_view().build_data(add, width, use_sel)
        return vrows

    def _build_chrome_vrows(self, width, sel=None):
        """Chrome-only VRows (machine-scope + button rows) -- no data body.

        The interactive path's chrome segment widgets (``_PickerMachine`` /
        ``_PickerButtons``) use THIS instead of ``_build_body_split`` so a pure
        navigation (a highlight/``sel`` move) repaints only the small fixed
        chrome and NEVER rebuilds the scrolling data body. The live body is the
        native OptionList (``_PickerNativeData``), which owns its own cursor and
        diffs cheaply; rebuilding every data row here on each arrow keypress was
        a ~100ms/key stall that saturated the input queue under key-repeat and
        read as an unrecoverable freeze (dotfiles#948 follow-up). Cached by the
        same ``_render_sig`` key so the two chrome widgets in one paint pass
        share a single build; ``refresh()`` busts it alongside the other caches.
        """
        use_sel = self.sel if sel is None else sel
        H = self.size.height or 30
        key = (self._render_sig(width, H), use_sel)
        cache = self._chrome_cache
        if cache is not None and cache[0] == key:
            return cache[1]
        vrows = []
        section = {"cur": None}

        def add(text, stop=None, kind=None, data=None, new_section=None):
            if new_section is not None:
                section["cur"] = (new_section, len(vrows))
            vr = VRow(text, stop, kind, data)
            vr.pin_section = section["cur"]
            vrows.append(vr)
            return vr

        self._current_view().build_chrome(add, width, use_sel)
        self._chrome_cache = (key, vrows)
        return vrows

    def _ensure_data_visible(self, data_vrows, data_h):
        """Scroll the data-body (compose tree) so the selected data row is
        visible; a no-op for chrome selections (they live in the fixed chrome and
        aren't in ``data_vrows``, so ``_stop_line`` returns 0) (#88 NF3)."""
        line = self._stop_line(data_vrows, self.sel)
        if line < self._data_top:
            self._data_top = line
        elif line >= self._data_top + data_h:
            self._data_top = line - data_h + 1
        self._data_top = max(0, min(self._data_top,
                                    max(0, len(data_vrows) - data_h)))

    def _data_sticky(self, data_vrows, data_h):
        """Pin the current section header at the top of the scrolled data body
        (mirrors ``_sticky`` over the data-relative offset)."""
        if self._data_top <= 0 or self._data_top >= len(data_vrows):
            return []
        first = data_vrows[self._data_top]
        ps = first.pin_section
        if ps and ps[1] < self._data_top:
            return [self._pin_line(ps[0], "section")]
        return []

    def _data_lines(self, data_vrows, data_h):
        """The windowed data-body rows for the compose tree's data widget --
        scroll + sticky over just the data rows (the fixed chrome renders
        separately above), padded to ``data_h`` (#88 NF3)."""
        return [vr.text if isinstance(vr, VRow) else vr
                for vr in self._data_window(data_vrows, data_h, pad=True)]

    def _data_window(self, data_vrows, data_h, pad=False):
        """The concrete window of data VRows (with the sticky section header
        substituted at the top when scrolled) -- shared by ``_data_lines`` (render)
        and ``_data_stop_at`` (pointer hit-testing) so a click maps to exactly the
        row that was drawn (#88 NF4)."""
        self._ensure_data_visible(data_vrows, data_h)
        window = data_vrows[self._data_top: self._data_top + data_h]
        sticky = self._data_sticky(data_vrows, data_h)
        for i, s in enumerate(sticky):
            if i < len(window):
                window[i] = s
            else:
                window.append(s)
        if pad:
            window = list(window)
            while len(window) < data_h:
                window.append(Text(""))
        return window

    def _data_stop_at(self, data_vrows, data_h, y):
        """The ``sel`` stop of the data row drawn at visible offset ``y`` in the
        data body, or ``None`` (blank line, sticky/section header, out of range)
        -- for click-to-select (#88 NF4)."""
        window = self._data_window(data_vrows, data_h)
        if 0 <= y < len(window):
            vr = window[y]
            stop = getattr(vr, "stop", None)
            if stop is not None:
                return stop
        return None

    def _chrome_split(self, chrome):
        """Split the pivot's chrome vrows into ``(machine_vrows, button_vrows)``
        at the button row, so the machine-scope and button regions can be
        separate focusable widgets (#88 NF3). Pivots without a top button region
        (Tasks) return all-machine + empty buttons."""
        bi = next((i for i, vr in enumerate(chrome)
                   if vr.stop == ("BTN", 0)), None)
        if bi is None:
            return chrome, []
        return chrome[:bi], chrome[bi:]

    #: Which compose region widget owns each ``sel`` zone (#88 NF3 focus bridge).
    _ZONE_WIDGET = {
        "V": "nf-pivots", "CFG": "nf-pivots", "UPD": "nf-pivots",
        "M": "nf-machine", "BTN": "nf-buttons",
    }

    def _widget_for_zone(self, zone):
        return self._ZONE_WIDGET.get(zone, "nf-body-data")

    def _nf_initial_focus(self):
        """Place the initial region focus on the widget that owns the default
        ``sel`` and arm the focus bridge (#88 NF3). Runs after the region widgets
        mount; guarded so it sets focus without a sel round-trip."""
        self._nf_syncing = True
        try:
            wid = self._widget_for_zone(self.sel[0])
            try:
                self.query_one(f"#{wid}").focus()
            except Exception:
                pass
        finally:
            self._nf_syncing = False
        self._nf_mounted = True

    def _sync_focus_to_sel(self):
        """Mirror native focus onto the region widget that owns the current
        ``sel`` (the other half of the on_focus -> sel bridge), so Tab/arrow
        navigation through the manual model keeps the framework's focus in step
        (#88 NF3). Guarded so the resulting ``focus()`` can't recurse."""
        wid = self._widget_for_zone(self.sel[0])
        try:
            w = self.query_one(f"#{wid}")
        except Exception:
            return
        if getattr(w, "can_focus", False) and self.app.focused is not w:
            self._nf_syncing = True
            try:
                w.focus()
            finally:
                self._nf_syncing = False

    def _hl(self, base, selected, focused):
        """Augment a base style with the selection highlight: the inversion
        cursor when the machine region is focused, a subtle bg when merely the
        active tab. Applied per-span so a highlight can be non-contiguous."""
        if not selected:
            return base
        extra = "reverse bold" if focused else "on grey23"
        return f"{base} {extra}".strip()

    def _machine_group(self, group, focused):
        """Render one machine's tab block: the machine (config) name once, then
        each of its environments as 'env marker', joined by ' · '. The name and
        the *selected* env+marker carry the highlight; sibling envs do not -- so
        selecting a secondary env shows a deliberate break in the highlight.
        Machine name takes the slot color (grey when idle, white when active);
        each env keeps its assigned per-env color."""
        first = self.machines[group[0]]
        label0, m0 = first[0], first[1]
        t = Text(" ")
        if label0 == "All":
            i = group[0]
            sel = i == self.machine_idx
            base = "bold white" if sel else C_TABOFF
            t.append("All", style=self._hl(base, sel, focused))
            t.append(" ")
            return t
        group_sel = any(i == self.machine_idx for i in group)
        all_disabled = all(self.machine_state(i) == "disabled" for i in group)
        name_base = (C_DISABLED if all_disabled
                     else "bold white" if group_sel else C_TABOFF)
        t.append(m0, style=self._hl(name_base, group_sel, focused))
        for n, i in enumerate(group):
            e = self.machines[i][2]
            state = self.machine_state(i)
            sel = i == self.machine_idx
            t.append(" ") if n == 0 else t.append(" · ", style=C_DIM)
            env_base = C_DISABLED if state == "disabled" else C_ENV.get(e, C_TABOFF)
            t.append(e, style=self._hl(env_base, sel, focused))
            t.append(" ", style=self._hl("", sel, focused))
            if state == "disabled":
                # #1289: a reliably single-width ASCII glyph (the old empty-set
                # marker U+2205 rendered ~1.5 cells on some terminals, shifting
                # the tab bar).
                mk, mkb = "-", C_DISABLED
            elif state == "loading":
                mk, mkb = self.spin(), C_LOAD
            elif state == "failed":
                mk, mkb = "✗", C_WARN
            else:
                mk, mkb = "✓", C_READY
            t.append(mk, style=self._hl(mkb, sel, focused))
        t.append(" ")
        return t

    def tab_bar(self, width, focused):
        # Group consecutive flat entries by machine (the 'All' entry stands
        # alone) so a multi-env machine renders its name once.
        groups = []
        prev = None
        for i, (label, m, e, ok) in enumerate(self.machines):
            if label != "All" and m == prev:
                groups[-1].append(i)
            else:
                groups.append([i])
            prev = m if label != "All" else None
        blocks = [self._machine_group(g, focused) for g in groups]
        blen = [b.cell_len for b in blocks]
        ng = len(groups)
        selg = next((gi for gi, g in enumerate(groups) if self.machine_idx in g), 0)
        gap = 3
        budget = width - 6   # reserve for ‹ / › overflow markers
        lo = hi = selg
        used = blen[selg]
        while True:
            grew = False
            if hi + 1 < ng and used + gap + blen[hi + 1] <= budget:
                hi += 1
                used += gap + blen[hi]
                grew = True
            if lo - 1 >= 0 and used + gap + blen[lo - 1] <= budget:
                lo -= 1
                used += gap + blen[lo]
                grew = True
            if not grew:
                break
        t = Text(" ")
        t.append("‹ " if lo > 0 else "  ", style=C_HINT)
        for k in range(lo, hi + 1):
            if k > lo:
                t.append(" " * gap)
            t.append_text(blocks[k])
        t.append(" ›" if hi < ng - 1 else "  ", style=C_HINT)
        t.append(" " * max(0, width - t.cell_len))
        return t

    def status_text(self, compact=False):
        t = Text()
        if self._kind() == "worktrees":
            secs = dict((lbl, len(rows)) for lbl, rows in self.current_list()[1])
            a = secs.get("Active", 0)
            r = secs.get("Recent", 0)
            c = secs.get("Completed", 0)
            u = sum(n for lbl, n in secs.items() if lbl.startswith("Unowned"))
            t.append("●", style=C_PULSE[self.pulse])
            if compact:
                t.append(f"{a} ", style=C_LABEL)
                t.append(f"◷{r} ✓{c}", style=C_FAINT)
                if u:
                    t.append(f" ?{u}", style=C_FAINT)
            else:
                t.append(f" {a} active", style=C_LABEL)
                t.append(" · ", style=C_DIM)
                t.append(f"{r} recent", style=C_META)
                t.append(" · ", style=C_DIM)
                t.append(f"{c} done", style=C_META)
                if u:
                    t.append(" · ", style=C_DIM)
                    t.append(f"{u} unowned", style=C_META)
        elif self._kind() == "maintenance":
            rows = self.cleanup_rows()
            mib = sum(_size_mb(w) for w in rows)
            if compact:
                t.append(f"⌫ {len(rows)}", style=C_META)
            else:
                t.append(f"{len(rows)} candidates · ~{mib} MiB", style=C_META)
        elif self._kind() == "registered":
            reg = self._reg_pivot()
            state, rows, _err = self._task_state()
            glyph = self.spin() if state == "loading" else "◆"
            t.append(f"{glyph} ", style=C_LOAD if state == "loading" else C_FAINT)
            label = reg.label if reg else "tasks"
            t.append(f"{len(rows)}{'' if compact else ' ' + label.lower()}", style=C_LABEL)
        else:
            n = self.profiles_present()
            t.append("⚙ ", style=C_FAINT)
            t.append(f"{n}{' set' if not compact else ''}", style=C_LABEL)
        # Live mode: surface how many machines are still loading / failed so the
        # All view's streaming fill-in is legible.
        if self.live and self.loader is not None and self._kind() == "worktrees":
            # Only the loading-spinner count is surfaced. A machine-load (SSH)
            # failure is NOT a failed worktree -- the per-machine tab already
            # shows its ✗ -- so totalling them here only confused (test-chamber
            # #1347).
            _ready, loading, _failed = self.loader.counts()
            if loading:
                t.append(f"  {self.spin()}{loading}", style=C_LOAD)
                if not compact:
                    t.append(" loading", style=C_LOAD)
        return t

    def _top_pad(self, W, more_above, scrolled):
        left = f"▲ {scrolled} more above" if more_above else "▲"
        lstyle = C_HINT_ON if more_above else C_HINT
        use = self.status_text(False)
        if 1 + len(left) + 3 + use.cell_len + 1 > W:
            use = self.status_text(True)
        t = Text(" ")
        t.append(left, style=lstyle)
        gap = W - t.cell_len - use.cell_len - 1
        t.append(" " * max(1, gap))
        t.append_text(use)
        t.append(" " * max(0, W - t.cell_len))
        return t

    # ---- assemble full screen ----
    def _frame_segments(self):
        """Compute the four screen segments -- header / chrome / body / footer --
        as lists of ``Text`` line-rows, plus the working width ``W`` (#88 NF2).

        This is the single source of the picker's screen content. The monolithic
        ``render()`` flattens the four segments in order (byte-identical to the
        pre-NF2 output); the NF2 compose skeleton (behind
        ``AGENT_WORKTREES_PICKER_NF``) has each child leaf widget render its own
        segment from this same dict, so the two paths are guaranteed identical.
        """
        W = self.size.width or 100
        H = self.size.height or 30
        key = self._render_sig(W, H)
        cache = self._frame_cache
        if cache is not None and cache[0] == key:
            return cache[1]
        top = self.topbar(W)              # [title, htabs]  (2 rows)
        foot = self.footer(W)
        # chrome rows: title, htabs, header-border, stats, bottom-border, footer
        body_h = max(1, H - len(top) - 4)
        vrows = self.build_body(W)
        self._ensure_visible(vrows, body_h)
        window = vrows[self.top: self.top + body_h]
        sticky = self._sticky(vrows, body_h)
        for i, s in enumerate(sticky):
            if i < len(window):
                window[i] = s
            else:
                window.append(s)
        body_lines = [vr.text if isinstance(vr, VRow) else vr for vr in window]
        while len(body_lines) < body_h:
            body_lines.append(Text(""))
        more_above = self.top > 0
        below = len(vrows) - (self.top + body_h)
        header_border = self._border_row(W, "▲", more_above)
        bottom_border = self._border_row(W, "▼", below > 0)
        stats = self._stats_row(W)
        seg = {
            "W": W,
            "header": list(top),
            "chrome": [header_border, stats],
            "body": body_lines,
            "footer": [bottom_border, foot],
        }
        self._frame_cache = (key, seg)
        return seg

    @staticmethod
    def _join_lines(lines, W):
        """Join screen rows into a single ``Text``, cropping each to ``W`` so a
        line never wraps (shared by ``render()`` and the NF2 segment widgets)."""
        out = Text()
        for i, ln in enumerate(lines):
            if i:
                out.append("\n")
            lt = ln if isinstance(ln, Text) else Text(str(ln))
            lt.truncate(W, overflow="crop")   # never let a line wrap
            out.append_text(lt)
        return out

    def compose(self) -> ComposeResult:
        # NF5 (#88): the native compose tree is the *sole display path*. The
        # screen is a container of segment/region widgets -- a passive title +
        # chrome + footer view, and the focusable pivots / machine-scope / button
        # / data regions (native Tab moves between them; on_focus mirrors ``sel``;
        # the machine + button chrome renders fixed above the scrolling data).
        # ``render()`` is retained NOT as a display path but as the deterministic
        # *capture* seam (capture.py, the golden, the picker-snapshot A/B tool,
        # the picker vision's auditable-rendering); it and these widgets both
        # derive from ``_frame_segments`` / ``_build_body_split``, so they cannot
        # drift.
        yield _PickerSegment(self, "header", slice(0, 1), id="nf-title")
        yield _PickerPivots(self, id="nf-pivots")
        yield _PickerSegment(self, "chrome", id="nf-chrome")
        yield _PickerMachine(self, id="nf-machine")
        yield _PickerButtons(self, id="nf-buttons")
        if _native_list_enabled():
            # NF5-5 (#88): swappable native OptionList data body (opt-in), with a
            # pinned section header above it (hidden until scrolled).
            yield _PickerStickyHeader(id="nf-body-sticky")
            yield _PickerNativeData(self, id="nf-body-data")
        else:
            yield _PickerBodyData(self, id="nf-body-data")
        yield _PickerSegment(self, "footer", id="nf-footer")

    def _refresh_nf_segments(self) -> None:
        """Propagate a screen state change to the child segment/region widgets
        (their ``render()`` reads back off this screen). The native OptionList
        data body (#88 NF5-5) rebuilds its options on demand instead."""
        for seg_id in ("nf-title", "nf-pivots", "nf-chrome", "nf-machine",
                       "nf-buttons", "nf-body-data", "nf-footer"):
            try:
                w = self.query_one(f"#{seg_id}")
                if isinstance(w, _PickerNativeData):
                    w.refresh_data()
                else:
                    w.refresh()
            except Exception:
                pass

    def refresh(self, *args, **kwargs):
        # Keep the NF2 segment widgets in step with the screen: any state change
        # that refreshes the screen must re-render the child segments too (they
        # read off this screen). A no-op when the skeleton is disabled.
        # Bust the per-refresh render caches (#169) first: a refresh means the
        # screen state may have changed, so the memoized frame/split must be
        # recomputed once and then shared by every segment widget in this pass.
        self._frame_cache = None
        self._split_cache = None
        self._chrome_cache = None
        result = super().refresh(*args, **kwargs)
        self._refresh_nf_segments()
        return result

    def _border_row(self, W, arrow, active):
        """A separator line carrying a centered scroll arrow with a blank space
        either side: ────── ▲ ──────. Arrow glows when there's more that way."""
        left = (W - 3) // 2
        rightn = W - 3 - left
        t = Text("─" * max(0, left), style=C_DIM)
        t.append(" ")
        t.append(arrow, style=C_HINT_ON if active else C_HINT)
        t.append(" ")
        t.append("─" * max(0, rightn), style=C_DIM)
        return t

    def _stats_row(self, W):
        """Left: the region's sub-pivot hint (◀ machine ▶ etc). Right: the
        section counts (with a glyph-compact fallback when narrow)."""
        hint = "Host  ◀▶" if self._kind() == "profiles" else "Machine  Ctrl ◀▶"
        use = self.status_text(False)
        if 1 + len(hint) + 3 + use.cell_len + 1 > W:
            use = self.status_text(True)
        t = Text(" ")
        t.append(hint, style=C_DIM)
        gap = W - t.cell_len - use.cell_len - 1
        t.append(" " * max(1, gap))
        t.append_text(use)
        t.append(" " * max(0, W - t.cell_len))
        return t

    def _hint_row(self, W, direction, active, count):
        arrow = "▲" if direction == "up" else "▼"
        t = Text()
        if active:
            label = f"{arrow}  {count} more above" if direction == "up" \
                else f"{arrow}  {count} more below"
            pad = (W - len(label)) // 2
            t.append(" " * max(0, pad))
            t.append(label, style=C_HINT_ON)
        else:
            pad = (W - 1) // 2
            t.append(" " * max(0, pad))
            t.append(arrow, style=C_HINT)
        t.append(" " * max(0, W - t.cell_len))
        return t

    def _update_seg(self, focused: bool):
        """Version-indicator glyph for the launcher's update stage (#1430).

        checking -> animated spinner; current -> ✓; available -> ↻ (focusable,
        Enter applies + restarts). Returns a Text segment, or None when idle.
        """
        st = getattr(self, "update_state", "idle")
        if st == "idle":
            return None
        t = Text()
        if st == "checking":
            t.append(" " + self.spin(), style=C_SPIN)
        elif st == "current":
            t.append(" ✓", style=C_READY)
        elif st == "available":
            t.append(" ↻", style=(C_BTN_SEL if focused else C_HINT_ON))
        return t

    def topbar(self, W):
        # Right-side segments, dropped in this order as width shrinks:
        # version, branch, env, repo. Always kept: "Worktree Manager" + machine.
        ver = f" · v{VERSION}"
        m, e = self.src.LOCAL
        host = f"{m.lower()}"
        # Repo name + default branch are project config, surfaced by the data
        # source (data_local/data_ssh expose REPO/BRANCH from the resolved
        # config); never hardcoded. Empty when a source omits them (e.g. a
        # fixture source) so the segment is dropped rather than showing a
        # fabricated name.
        repo = getattr(self.src, "REPO", "") or ""
        branch = getattr(self.src, "BRANCH", "") or ""
        present = {"update_text": True, "version": True, "repo": bool(repo),
                   "env": True, "branch": bool(branch)}
        upd_focused = self.sel[0] == "UPD"

        def build():
            left = Text(" Worktree Manager", style="bold")
            if present["version"]:
                left.append(ver, style=C_DIM)
            # Update indicator (#1430): spinner while the launcher stages the
            # marketplace update, ✓ when current, ↻ when an update is staged.
            seg = self._update_seg(upd_focused)
            if seg is not None:
                left.append_text(seg)
                if present["update_text"] and self.update_state == "available":
                    left.append(" Update available…",
                                style=(C_BTN_SEL if upd_focused else C_HINT_ON))
            right = Text("host ", style=C_DIM)
            right.append(host, style=C_META)
            if present["env"]:
                right.append(" · ", style=C_DIM)
                right.append(e, style=C_ENV.get(e, C_META))
            if present["repo"]:
                right.append(f"  ·  {repo}", style=C_DIM)
            if present["branch"]:
                right.append(f" · {branch}", style=C_DIM)
            return left, right

        for drop in ("update_text", "version", "branch", "env", "repo"):
            left, right = build()
            if left.cell_len + 1 + right.cell_len + 1 <= W:
                break
            present[drop] = False
        left, right = build()
        l1 = left
        gap = W - left.cell_len - right.cell_len - 1
        l1.append(" " * max(1, gap))
        l1.append_text(right)
        l1.append(" " * max(0, W - l1.cell_len))
        l2 = Text("  ")
        v_focus = self.sel[0] == "V"
        for n, i in enumerate(self._left_pivots()):
            label = self.htabs[i]
            if n:
                l2.append("     ")
            if i == self.htab:
                l2.append(label.upper(),
                          style=C_TAB_FOCUS_ON if v_focus else C_BAND)
            else:
                l2.append(label, style="white" if v_focus else C_TABOFF)
        # Right-aligned ⚙ Configuration entry hosting Profiles etc. (#1426). It
        # is active when the current pivot lives under it, focused when the
        # ("CFG", 0) stop holds the cursor.
        cfg = self._config_pivots()
        if cfg:
            cfg_focus = self.sel[0] == "CFG"
            cfg_active = self.htab in cfg
            cstyle = (C_TAB_FOCUS_ON if cfg_focus
                      else C_TAB_ACTIVE if cfg_active else C_TABOFF)
            chip = Text("⚙ Configuration", style=cstyle)
            l2.append(" " * max(2, W - l2.cell_len - chip.cell_len - 1))
            l2.append_text(chip)
            l2.append(" ")
        else:
            # Tab never switches the view -- it moves focus between regions. The
            # view pivot moves with ◀▶ (while focused here) or [ ]/^⇧◀▶ (#1344).
            hint = ("◀▶ switch view · ↓ body · Tab region "
                    if v_focus else "[ ] switch view ")
            l2.append(hint.rjust(max(1, W - l2.cell_len)), style=C_DIM)
        return [l1, l2]

    def _focus_hint(self):
        """Focus-specific footer hint: exactly what Enter/Space do for the
        current focus, naming the concrete target (#1344)."""
        zone = self.sel[0]
        if zone == "UPD":
            return ("Enter: apply staged update + restart the picker"
                    " · ↑↓ move · Tab region")
        if zone == "V":
            return (f"◀▶ view / ⚙ Config (on {self.htabs[self.htab]})"
                    f" · Enter: focus body · Tab region · [ ] view")
        if zone == "CFG":
            return ("◀▶ back to pivots · Enter: open Configuration"
                    " · ↑↓ move · Tab region")
        if zone == "M":
            m, e, _ = self.cur_machine()
            scope = "All machines" if self.is_all() else f"{m} {e}"
            return (f"◀▶ switch machine (on {scope}) · Enter: focus actions"
                    f" · Tab region · ^◀▶ machine")
        if zone == "BTN":
            btn = self.active_button()
            if btn == "N":
                tm, te = self.create_target()
                return (f"Enter: new worktree on {tm} {te}"
                        f" · Tab region · ^◀▶ machine")
            if btn == "K":
                return "Enter: open Cleanup dialog · ◀▶ Cleanup/Sync · Tab region"
            if btn == "SY":
                return "Enter: open Sync dialog · ◀▶ Cleanup/Sync · Tab region"
            if btn == "PA":
                n = self.pending_count()
                return (f"Enter: apply {n} profile change(s) · ◀▶ Apply/Reset"
                        f" · ↑ grid · Tab region")
            if btn == "PReset":
                return ("Enter: reset grid to applied · ◀▶ Apply/Reset"
                        " · ↑ grid · Tab region")
            return ""
        if zone == "L":
            rec = self._selected_record()
            wid = rec.get("id4") if rec else "?"
            nsel = len(self.wt_sel)
            if nsel:
                return (f"Space: select/deselect · Enter: actions for "
                        f"{nsel} selected · Tab region · ^◀▶ machine")
            return (f"Space: select · Enter: sub-menu for worktree {wid}"
                    f" · Tab region · ^◀▶ machine")
        if zone == "C":
            rec = self._selected_record()
            wid = rec.get("id4") if rec else "?"
            nsel = self.maint_sel.count(self._maint_ids())
            tgt = f"{nsel} selected" if nsel else f"row {wid}"
            return (f"Space: select {wid} · Enter: actions for {tgt}"
                    f" · Tab region · ^◀▶ machine")
        if zone == "SA":
            ids = self._maint_ids()
            all_on = self.maint_sel.all_selected(ids)
            verb = "clear all" if all_on else "select all"
            return f"Space / Enter: {verb} ({len(ids)}) · ↓ rows · Tab region"
        if zone == "GH":
            groups = self.maint_groups()
            gi = self.sel[1]
            st = groups[gi][0] if 0 <= gi < len(groups) else "?"
            return f"Space / Enter: select all {st} · ↓ rows · Tab region"
        if zone == "PR":
            ti = self.sel[1]
            if not self.host_cols:
                return "No profile hosts configured · Tab region"
            host = "{1} {2}".format(*self.host_cols[self.pcol])
            tlabel = (self.targets[ti]["label"]
                      if 0 <= ti < len(self.targets) else "?")
            return (f"Space: toggle {host} → {tlabel} · ◀▶ host · ↑↓ target"
                    f" · Enter: to Apply · Tab region")
        return ""

    def footer(self, W):
        if self.progress:
            hints = ("Esc cancel" if not self.progress["done"]
                     else "Enter/Esc close")
        else:
            hints = self._focus_hint()
        f = Text(" " + hints, style=C_META)
        if self._busy_label:
            # Always-async: while a background action runs, show the shared
            # animated spinner + its label (not a static line), so no control ever
            # looks like it did nothing. The tick keeps this at ~10 fps.
            dbg = f"· {self.spin()} {self._busy_label}… "
        else:
            dbg = f"· {self.debug} "
        f.append(dbg.rjust(max(1, W - f.cell_len)), style=C_DIM)
        if f.cell_len > W:
            f = Text(f.plain[:W])
        return f

    # ---- scroll + sticky ----
    def _stop_line(self, vrows, stop):
        for i, vr in enumerate(vrows):
            if vr.stop == stop or (isinstance(vr.stop, list) and stop in vr.stop):
                return i
        return 0

    def _ensure_visible(self, vrows, body_h):
        line = self._stop_line(vrows, self.sel)
        if line < self.top:
            self.top = line
        elif line >= self.top + body_h:
            self.top = line - body_h + 1
        self.top = max(0, min(self.top, max(0, len(vrows) - body_h)))

    def _sticky(self, vrows, body_h):
        if self.top <= 0 or self.top >= len(vrows):
            return []
        first = vrows[self.top]
        pins = []
        pb = first.pin_band
        ps = first.pin_section
        if pb and pb[1] < self.top:
            pins.append(self._pin_line(pb[0], "band"))
        if ps and ps[1] < self.top:
            pins.append(self._pin_line(ps[0], "section"))
        return pins

    def _pin_line(self, label, kind):
        W = self.size.width or 100
        if kind == "band":
            t = Text(f" {label}", style=C_BAND)
        else:
            t = Text(f"  ── {label} ", style=C_SECTION)
        t.append(" " * max(0, W - t.cell_len))
        t.stylize("on grey15")  # subtle pinned background
        return t

    @staticmethod
    def _wrap_text(text: str, width: int) -> list[str]:
        """Word-wrap ``text`` to ``width`` columns; collapse blank lines.

        Preserves the transcript's own line breaks, then greedily wraps each
        line on whitespace. A single word longer than ``width`` is hard-split.
        """
        width = max(8, width)
        out: list[str] = []
        for raw in text.replace("\r", "").split("\n"):
            line = raw.rstrip()
            if not line:
                if out and out[-1] != "":
                    out.append("")
                continue
            cur = ""
            for word in line.split(" "):
                while len(word) > width:
                    if cur:
                        out.append(cur)
                        cur = ""
                    out.append(word[:width])
                    word = word[width:]
                if not cur:
                    cur = word
                elif len(cur) + 1 + len(word) <= width:
                    cur += " " + word
                else:
                    out.append(cur)
                    cur = word
            if cur:
                out.append(cur)
        return out or [""]

    def _dispatch_key(self, key):
        # NOTE: this MUST NOT be named ``handle_key`` -- Textual's
        # ``Widget.handle_key`` is an ``async`` coroutine its ``_on_key``
        # awaits to run the BINDINGS system. Shadowing it with this synchronous
        # dispatcher makes Textual ``await`` a ``None`` return and crash
        # ("object NoneType can't be used in 'await' expression") whenever a
        # global BINDING key (Ctrl+←/→, F3/F4/F5) bubbles to the framework.
        # Keeping a distinct name lets Textual's native binding dispatch run.
        # Fold framework key-name aliases to canonical tokens once, up front, so
        # every downstream match is declarative and alias-free (#88 F2).
        key = canonical_key(key)
        # Remember the grid row before any navigation, so Tab out/in restores it.
        if self.sel and self.sel[0] == "PR":
            self.last_pr = self.sel[1]
        # Same for the Worktrees list: remember focus so Tab out/in restores it
        # (#2258 P3-6).
        if self.sel and self.sel[0] == "L":
            self.last_l = self.sel[1]
        # (Every modal overlay is a native ModalScreen now (#88 F4): while one is
        # up it sits above this widget on Textual's screen stack and owns the
        # keyboard, so _dispatch_key only ever runs for the top-level views --
        # there is no manual overlay to route to first.)

        # Global pivot/machine shortcuts. The Ctrl+Shift+←/→ (pivot) and Ctrl+←/→
        # (machine) combos are owned by Textual BINDINGS now (#88 F3) -- on_key
        # passes them to the framework, so they never reach here in the real
        # path; the action_* methods do the work. Only the printable [ ] pivot
        # shortcut stays in the manual dispatcher (on_key remaps its character,
        # and a bare letter is an awkward binding).
        if key == "[":
            return self._switch_pivot(-1)
        if key == "]":
            return self._switch_pivot(1)

        zone = self.sel[0]

        # Tab / Shift+Tab jump between major regions (View / Machine / Buttons /
        # the table or grid).
        if key in ("tab", "shift+tab"):
            heads = self.region_heads()
            cur = self.region_head(zone)
            i = heads.index(cur) if cur in heads else 0
            d = 1 if key == "tab" else -1
            self.sel = heads[(i + d) % len(heads)]
            return

        # Bare ←/→ move to the next item *within* the focused region.
        if key in ("left", "right"):
            d = 1 if key == "right" else -1
            if zone in ("V", "CFG"):
                self._nav_view_row(d)      # traverse pivots + ⚙ Configuration
            elif zone == "M":
                self._rotate_machine(d)
            elif zone == "BTN":
                bset = self.button_set()
                if bset:
                    self.btn_idx = (self.btn_idx + d) % len(bset)
            elif zone == "PR":
                if self.host_cols:
                    self.pcol = (self.pcol + d) % len(self.host_cols)
            # L / C rows: bare ←/→ is a no-op (machine = Ctrl+←/→)
            return

        stops = self.stops()
        # ⚙ Configuration rides the View pivot row: for vertical up/down treat it
        # as the ("V",0) row stop, so ↑/↓ leave it for the row's neighbours.
        ref = ("V", 0) if self.sel[0] == "CFG" else self.sel
        if ref not in stops:
            self.sel = self.default_sel()
            ref = self.sel
        idx = stops.index(ref)
        zone = self.sel[0]

        if key in ("shift+up", "shift+down"):
            self._wt_shift_move(stops, idx, key == "shift+down")
        elif key in ("ctrl+up", "ctrl+down"):
            self._wt_ctrl_move(stops, idx, key == "ctrl+down")
        elif key == "down":
            self.sel = stops[min(idx + 1, len(stops) - 1)]
            self._wt_track_focus()
        elif key == "up":
            self.sel = stops[max(idx - 1, 0)]
            self._wt_track_focus()
        elif key in ("pagedown", "pageup"):
            self._page(stops, idx, forward=(key == "pagedown"))
            self._wt_track_focus()
        elif key == "enter":
            self._activate()
        elif key in ("space", "ctrl+space"):
            # Ctrl+Space toggles too (operator request): Textual delivers it as
            # "ctrl+at" (Ctrl+Space == NUL), canonicalized to "ctrl+space" up
            # front. It behaves identically to Space so the toggle works even
            # while the operator is holding Ctrl to move focus (#2258 follow-up).
            if zone == "L":
                self._toggle_wt(self.sel[1])
            elif zone == "C":
                self._toggle_maint(self.sel[1])
            elif zone == "SA":
                self._toggle_maint_all()
            elif zone == "GH":
                self._toggle_group(self.sel[1])
            elif zone == "PR":
                self._toggle_cell()
            elif zone == "T":
                self._open_task_menu()
            elif zone == "BTN":
                self._activate()
        elif key == "r":
            # Real reload: rebuild the data source (live mode re-fetches every
            # machine on its loader threads; fixture mode re-reads src.load()).
            self.setup()
            self.sel = self.default_sel()
            self.debug = "refreshed · reloaded worktrees"
        elif key in ("q", "escape"):
            # Esc composes with selection collapse (#2258 P3-5) before the
            # quit-confirm (#1429): a multi-selection collapses first; only a
            # second Esc (nothing left to collapse) reaches the quit prompt.
            if key == "escape" and self._wt_collapse_selection():
                return
            self._open_quit_confirm()

    def _open_quit_confirm(self):
        """Esc/q on a main pivot view asks before quitting (#1429).

        Migrated to a native Textual ``ModalScreen`` (#88 F4): the first overlay
        moved off the manual render/dispatch. Textual owns the screen stack,
        focus, and key routing; the dialog dismisses ``True`` to quit / ``False``
        to stay. Only reached when no manual overlay is open (those still consume
        Esc first). Defaults focus to *Stay* so a reflexive Enter never quits.
        """
        def _after(quit_it):
            if quit_it:
                self.app.exit()
        self.app.push_screen(QuitConfirmScreen(), _after)

    def _rotate_machine(self, d):
        was_in_table = self.sel[0] == "L"
        self.machine_idx = (self.machine_idx + d) % len(self.machines)
        if self.sel not in self.stops():
            self.sel = self.default_sel()
        # A machine switch lands on a different list, so drop the whole
        # selection state (operator request) -- keeping ids from the old tab
        # would leak invisible selections. If focus was in the table, reset to a
        # clean single-row selection on the top row (single-select tracks focus);
        # otherwise just clear.
        self.wt_sel.clear()
        self.wt_anchor = None
        if was_in_table and self._kind() == "worktrees" and self.list_records():
            self.sel = ("L", 0)
            self._wt_track_focus()   # wt_sel = {top row}, anchor = 0

    def _switch_pivot(self, d):
        was_v = self.sel[0] == "V"
        # Cycle only pivots on the left rail; Configuration-hosted pivots (e.g.
        # Profiles) are reached via the ⚙ menu, not this cycle (#1426).
        left = self._left_pivots()
        if not left:
            return
        if self.htab in left:
            cur = left.index(self.htab)
            self.htab = left[(cur + d) % len(left)]
        else:
            # Currently on a Configuration-hosted pivot: step onto the left rail.
            self.htab = left[0] if d > 0 else left[-1]
        self.btn_idx = 0
        self.top = 0
        # Stay in the View nav if that's where focus was; otherwise land on the
        # new pivot's default body stop.
        self.sel = ("V", 0) if was_v else self.default_sel()

    def _nav_view_row(self, d):
        """Move focus across the top tab-row -- the left-rail pivots plus the
        ⚙ Configuration entry -- with bare ◀▶. Landing on a pivot switches the
        view (as a tab implies); landing on Configuration just focuses it (Enter
        opens its menu). Configuration is thus part of the same row as the
        pivots, not a separate stop (#1426)."""
        left = self._left_pivots()
        if not left:
            return
        row: list = list(left)
        if self._config_pivots():
            row.append("cfg")
        if self.sel[0] == "CFG":
            cur = len(row) - 1
        elif self.htab in left:
            cur = left.index(self.htab)
        else:
            cur = 0
        target = row[(cur + d) % len(row)]
        if target == "cfg":
            self.sel = ("CFG", 0)
        else:
            self.htab = target
            self.btn_idx = 0
            self.top = 0
            self.sel = ("V", 0)

    def _toggle_cell(self):
        self.profiles_view.toggle_cell()

    def _page(self, stops, idx, forward):
        anchors = [a for a in self.anchors() if a in stops]
        positions = sorted(stops.index(a) for a in anchors)
        if forward:
            nxt = next((p for p in positions if p > idx), positions[-1] if positions else idx)
        else:
            nxt = next((p for p in reversed(positions) if p < idx),
                       positions[0] if positions else idx)
        self.sel = stops[nxt]

    def _key_progress(self, key):
        p = self.progress
        # D4 progress-reporting action: Esc/q cancels a running action (kills the
        # child via the recorded cancel callback); Enter/Esc closes a finished
        # one. Its own reader thread invalidated the pivot cache on completion.
        if p.get("kind") == "action-stream":
            if key in ("escape", "q") or (p["done"] and key in ("enter", "space")):
                if not p["done"]:
                    cancel = p.get("cancel")
                    if callable(cancel):
                        cancel()
                verb = p["verb"]
                if p["done"] and not p.get("error"):
                    state, tail = "done", p.get("msg") or ""
                elif p.get("error"):
                    state, tail = "failed", p.get("error") or ""
                else:
                    state, tail = "cancelled", ""
                self.progress = None
                if self.sel not in self.stops():
                    self.sel = self.default_sel()
                self.debug = f"{verb} {state}" + (f" · {tail[:80]}" if tail else "")
            return
        # Unarmed: the extra confirm gate (beyond-clean cleanup). Enter proceeds,
        # Esc cancels without touching anything.
        if not p.get("armed", True):
            if key in ("enter", "space"):
                p["armed"] = True
                self._start_progress()
            elif key in ("escape", "q"):
                self.progress = None
                self.executor = None
                self.debug = f"{p['verb'].lower()} cancelled · 0 worktrees"
            return
        if key in ("escape", "q") or (p["done"] and key in ("enter", "space")):
            verb = p["verb"].lower()
            n = len(p["items"])
            failed = sum(1 for it in p["items"] if it["state"] == "failed")
            state = "complete" if p["done"] else "cancelled"
            sim = " (sim)" if self.mock_mode else ""
            # Profiles Apply: bank the succeeded host columns before clearing.
            if p.get("op") == "profiles":
                self.profiles_view.commit_applied()
                self.progress = None
                self.executor = None
                tail = f" · {failed} failed" if failed else ""
                self.debug = (f"{verb} {state} · {n} host column(s){tail}"
                              " · restart the terminal app to see changes")
                return
            was_real = self.executor is not None and p["done"]
            self.progress = None
            self.executor = None
            if was_real:
                # A real Cleanup/Sync changed worktree state -- reload the
                # machines it touched so the list re-renders without a Picker
                # restart (#1421, live re-render half).
                self._refresh_after_maint(p)
            tail = f" · {failed} failed" if failed else ""
            self.debug = f"{verb} {state} · {n} worktrees{tail}{sim}"

    def _refresh_after_maint(self, p):
        """Reload the machines a real Cleanup/Sync just touched.

        Every touched source re-fetches on a thread (local included) and streams
        back in via the render tick -- the list stays honest after maintenance
        without a full Picker relaunch, and the refresh never blocks the UI
        (#1421).
        """
        targets = {(r.get("machine"), r.get("env"))
                   for r in p.get("recs", []) if r.get("machine")}
        if self.live and self.loader is not None:
            for m, e in targets:
                self.loader.reload(m, e)
            self.data = self.loader.records()
            # The reloads are asynchronous, so the touched machine's fresh
            # records haven't arrived yet -- defer the selection reconcile until
            # they settle (processed in _tick) so we don't drop survivors that
            # are still streaming back in (#2258 P3-7).
            self._wt_reconcile_after = targets or None
        elif not self.live:
            self.data = self.src.load()
            # Fixture reload is synchronous: reconcile now. Survivors stay
            # selected, cleaned rows drop out, and focus stays at the equivalent
            # list index (clamped) so it never lands on a phantom stop.
            self._reconcile_wt_sel()
            self._rehome_l_focus()
        # Reconcile the local machine's bound/mux liveness cache as part of the
        # automatic post-action refresh (dotfiles: "Reclaim ran but the row
        # stayed ACTIVE"). The reload above only READS the cached bound_live/
        # mux_live hints, so an action that killed a process or mux
        # (Reclaim/Stop/Repair) would re-render from the pre-action cache until
        # the periodic reconcile or the freshness TTL. Kicking the authoritative
        # tri-state sweep here makes every completed action re-render the TRUE
        # liveness. Local-only (it resolves local processes); best-effort,
        # off-thread, reloads only on a real change (an already-correct cache --
        # e.g. one the executor self-stamped -- is a silent no-op).
        local = getattr(self.src, "LOCAL", None)
        if (not self.live) or (local is not None and local in targets):
            blr_fn = getattr(self.src, "reconcile_bound_live", None)
            if callable(blr_fn):
                self._start_bound_live_reconcile(blr_fn)

    def _confirm_new_worktree(self, dlg):
        """Confirmed New-worktree options -> the launch decision (#88 F4)."""
        on = {o["label"] for o in dlg["opts"] if o["on"]}
        tm, te = dlg["target"]
        self._decide({
            "action": "new", "machine": tm, "env": te,
            "is_local": (tm, te) == self.src.LOCAL,
            "options": {
                "anchor": "Anchor repo" in on,
                "bare": "Bare" in on,
                "no_mux": "No Mux" in on,
                "local_model": "Local model" in on,
            },
        })

    def _confirm_cleanup(self, dlg):
        """Confirmed Clean/Sync scope -> build (and, when armed, start) the
        per-worktree maintenance progress run (#88 F4)."""
        picked = [o["label"] for o in dlg["opts"] if o["on"]]
        verb = dlg.get("verb", "Clean up")
        op = "sync" if verb.lower().startswith("sync") else "cleanup"
        ids = self._scope_union(dlg)
        recs = [w for w in self.data if w["id4"] in ids]
        if not recs:
            self.debug = (f"{verb.lower()} {dlg['scope']}: "
                          f"{', '.join(picked) or 'nothing'} → 0 worktrees")
            return
        # Extra confirm when a cleanup scope reaches past 'clean'
        # (Unused / Conversation-only / All) -- removing idle/empty trees
        # or trees that held conversation is a bigger commitment.
        include_unused = any(
            p in ("Unused", "All eligible") for p in picked)
        include_conversations = any(
            p in ("Conversation-only", "All eligible") for p in picked)
        beyond_clean = op == "cleanup" and (
            include_unused or include_conversations)
        items = [{"id4": w["id4"], "title": w["title"],
                  "machine_env": w["machine_env"], "state": "pending"}
                 for w in recs]
        self.progress = {
            "verb": verb, "op": op, "scope": dlg["scope"], "items": items,
            "recs": recs, "picked": picked,
            "ticks": 0, "steps": 3, "done": False,
            "armed": not beyond_clean,
            "include_unused": include_unused,
            "include_conversations": include_conversations,
        }
        if self.progress["armed"]:
            self._start_progress()
        self._open_progress()

    def _open_progress(self):
        """Show the live maintenance/profiles progress run as a native Textual
        ``ModalScreen`` (#88 F4).

        The entry points (``_confirm_cleanup``, ``_run_op_progress``,
        ``_start_profiles_run``) build ``self.progress`` first; this pushes the
        ``ProgressScreen`` that renders it, ticks it forward (mock walker or
        real-executor poll) on its own interval, and mirrors the old
        ``_key_progress`` confirm gate. The screen mutates engine state directly
        (``self.progress`` / ``self.executor`` / ``self.debug``) and needs no
        callback."""
        self.app.push_screen(ProgressScreen(self))

    def _start_stop(self, recs):
        """Stop the Mux/Copilot wrapper of one or more worktrees (the 'Stop'
        action -- solo from the row sub-menu, or in aggregate from the bulk
        action menu, #2258 follow-up).

        Drives the same maintenance progress + executor path as Cleanup/Sync so
        the up-to-6 s graceful double-Ctrl-C quit never blocks the render loop
        and a remote worktree's kill goes over SSH (``restart <id>`` on the
        project binstub -- the CLI verb stays ``restart``; only the picker label
        is "Stop"). Only worktrees with a live mux are stopped. When it finishes
        the touched machines reload (``_refresh_after_maint``), so the rows
        re-render as stopped sessions -- ready to Resume with a fresh Mux +
        Copilot.
        """
        recs = [recs] if isinstance(recs, dict) else list(recs)
        live = [r for r in recs if r.get("mux_live")]
        if not live:
            self.debug = "no live session to stop"
            return
        self._run_op_progress("Stop", "restart", live, armed=True)

    def _start_reclaim(self, recs):
        """Reclaim the bound Copilot process(es) of one or more worktrees (the
        two-step-restore 'Reclaim' action).

        Runs the same maintenance progress path as Stop, but drives the
        ``reclaim`` op (kill the exact Copilot process holding the session's
        ``inuse.<pid>.lock``, **only bindings Stop cannot reach**) instead of a
        mux quit. Offered -- and here filtered -- on :meth:`_reclaimable`: a
        bound Copilot with no mux for Stop to reach (a bare orphan, a live lock
        whose homing could not be classified ``bare``, or one homed in a mux
        whose ``wt-<id>`` session is unreachable -- a detached psmux server,
        dotfiles #1447). Filtering on the same predicate the executor acts on
        keeps the verb honest -- a live, Stop-able muxed session is left to Stop,
        a bare orphan the cwd-keyed lock-scan never registered (#662/#1416) still
        reaps, and a bound-but-unclassifiable-or-detached Copilot is no longer
        stranded. After it finishes the touched machines reload, so the row
        re-renders without the stale bound process -- ready for a fresh Open /
        Bare resume.
        """
        recs = [recs] if isinstance(recs, dict) else list(recs)
        live = [r for r in recs if PickerScreen._reclaimable(r)]
        if not live:
            self.debug = "no Stop-unreachable bound process to reclaim"
            return
        self._run_op_progress("Reclaim", "reclaim", live, armed=True)

    def _start_repair(self, recs):
        """Repair the inconsistent mux+stray-orphan double-binding (the 'Repair'
        action, offered only in the WARNING state -- see :meth:`_warning`).

        Drives the SAME ``reclaim`` op as :meth:`_start_reclaim` (bare-only reap
        via ``reclaim_one``), which reaps only the bindings Stop cannot reach --
        here the **un-muxed** (bare/unknown-homing) stray orphan -- and leaves the
        live, **Stop-able mux-homed** session untouched (its ``wt-<id>`` mux is
        reachable, so ``filter_stop_unreachable`` preserves it). So the healthy
        ``wt-<id>`` mux is PRESERVED while the stray orphan and its lock residue
        are cleared. Filtered on the same ``_warning`` predicate the verb is gated
        on, so it acts if and only if the double-binding is real. After it
        finishes the touched machines reload and the row re-renders as a clean,
        singly-bound mux -- ready to Open/Stop.
        """
        recs = [recs] if isinstance(recs, dict) else list(recs)
        live = [r for r in recs if PickerScreen._warning(r)]
        if not live:
            self.debug = "no stray orphan to repair"
            return
        self._run_op_progress("Repair", "reclaim", live, armed=True)

    def _start_refresh(self, rec):
        """Per-row Refresh (picker-cache-first-paint, dotfiles#948).

        On-demand live gather + session-render-cache write-back for ONE worktree,
        run off the UI thread, then swap its row in place -- the only way to
        populate an **Unknown** row (the first paint reads cache only) and a cheap
        way to re-sync a stale one without a full-fleet reload. A LOCAL worktree
        is gathered + stamped via :func:`data_local.refresh_one`; a remote row
        (not resolvable in the local tracking store) falls back to reloading its
        owning machine through the live loader. Best-effort; never raises on the
        UI thread."""
        raw = rec.get("raw") or {}
        wt_id = raw.get("id")
        if not (getattr(self, "real_ops", False) and wt_id):
            self.debug = "refresh unavailable (no record)"
            return
        id4 = rec.get("id4")
        m, e = rec.get("machine"), rec.get("env")
        self.debug = f"refreshing {id4}…"

        def work():
            row = None
            try:
                from . import data_local
                row = data_local.refresh_one(wt_id, m, e)
            except Exception:
                row = None
            if row is not None:
                self._replace_row(wt_id, row)
                self.debug = f"refreshed {id4}"
                return
            # Remote (or gone locally): fall back to a machine-level reload.
            try:
                if self.live and self.loader is not None and m and e:
                    self.loader.reload(m, e)
                    self.debug = f"refreshing {m} · {e}…"
                elif not self.live:
                    self._reload_local_after_reconcile()
            except Exception:
                pass

        threading.Thread(target=work, name="wt-refresh", daemon=True).start()

    def _replace_row(self, wt_id, row):
        """Swap a single freshly-normalized row into ``self.data`` by worktree id
        (in place), appending if it is not already present. Used by the per-row
        Refresh so one row updates without rebuilding the whole data source."""
        for i, r in enumerate(self.data):
            if (r.get("raw") or {}).get("id") == wt_id:
                self.data[i] = row
                return
        self.data.append(row)

    def _start_finalize(self, recs):
        """Finalize one or more conversation-only / unused worktrees (the
        'Finalize' action -- solo or aggregate, #2258 follow-up).

        Finalize validates that nothing is unpushed (a no-commit worktree has
        nothing) and removes it -- the sanctioned lifecycle completion. Because
        it removes the worktree (and any conversation history), it runs behind a
        confirm gate (``armed=False``): the progress dialog asks before it
        executes. Only conversation-only / unused worktrees are targeted.
        """
        recs = [recs] if isinstance(recs, dict) else list(recs)
        targets = [r for r in recs
                   if r.get("cleanup_bucket") in ("conversation", "unused")]
        if not targets:
            self.debug = "no conversation-only / unused worktree to finalize"
            return
        self._run_op_progress("Finalize", "finalize", targets, armed=False)

    def _run_op_progress(self, verb, op, recs, *, armed):
        """Build (and, when ``armed``, start) a maintenance progress run over
        ``recs`` for a single ``op`` (restart / finalize). An unarmed run shows
        the confirm gate first (see ``_key_progress`` / ``ProgressScreen``)."""
        items = [{"id4": r.get("id4"), "title": r.get("title", ""),
                  "machine_env": r.get("machine_env", ""), "state": "pending"}
                 for r in recs]
        scope = (recs[0].get("id4", "") if len(recs) == 1
                 else f"{len(recs)} selected")
        self.progress = {
            "verb": verb, "op": op, "scope": scope,
            "items": items, "recs": recs, "picked": [],
            "ticks": 0, "steps": 3, "done": False, "armed": armed,
            "include_unused": False, "include_conversations": False,
        }
        if armed:
            self._start_progress()
        self._open_progress()

    def _start_progress(self):
        """Begin executing the armed progress run (real executor or mock walk)."""
        p = self.progress
        if not self.real_ops:
            return  # mock walker advances via _advance_progress
        from . import maintenance
        tasks = maintenance.build_tasks(
            p["op"], p["recs"], self.src,
            include_unused=p["include_unused"],
            include_conversations=p["include_conversations"],
        )
        self.executor = maintenance.MaintenanceExecutor(p["op"], tasks)
        self.executor.start()

    def _poll_executor(self):
        """Pull real per-item states from the maintenance executor."""
        p = self.progress
        ex = self.executor
        for it in p["items"]:
            it["state"] = ex.state(it["id4"])
        if ex.is_done():
            p["done"] = True

    def _scope_union(self, dlg):
        """The net acted-on set for a Clean/Sync scope dialog: the union of the
        enabled buckets. (Per-row exclusion was retired with the live-filter
        model in #88 F4 -- scope now comes from the main-list selection before
        the dialog opens, and the modal's impact list shows this exact set.)"""
        s = set()
        for o in dlg["opts"]:
            if o["on"]:
                s |= set(o.get("ids", ()))
        return s

    def _selected_record(self):
        zone, i = self.sel
        if zone == "L":
            arr = self.list_records()
        elif zone == "C":
            arr = self.maint_records()
        else:
            return None
        return arr[i] if 0 <= i < len(arr) else None

    def _decide(self, decision):
        """Record a launch decision and exit the TUI so __main__ can act on it.

        ``PickerApp.result`` stays ``None`` on cancel (q/Esc); a dict here is a
        concrete instruction the caller maps onto resume/create/remote paths.
        """
        self.app.result = decision
        self.app.exit()

    def _resume_decision(self, rec, no_mux=False, bare_resume=False):
        """Build the resume decision for a worktree row/submenu selection.

        ``no_mux`` (the Open sub-menu toggle, #1343) launches directly without
        the PSMux/TMux wrapper. ``bare_resume`` (two-step restore) creates the
        worktree's mux but launches Copilot in HOME with no --resume, so a CLI
        bug that fails to start in a repo/worktree cwd is dodged; the operator
        finishes with a manual ``/resume <id>``.
        """
        raw = rec.get("raw") or {}
        m, e = rec.get("machine"), rec.get("env")
        decision = {
            "action": "resume",
            "worktree_id": raw.get("id"),
            "id4": rec.get("id4"),
            "machine": m,
            "env": e,
            "title": rec.get("title"),
            "is_local": (m, e) == self.src.LOCAL,
        }
        opts = {}
        if no_mux:
            opts["no_mux"] = True
        if bare_resume:
            opts["bare_resume"] = True
        if opts:
            decision["options"] = opts
        return decision

    def _activate(self):
        zone = self.sel[0]
        if zone == "CFG":
            self._open_cfgmenu()
            return
        if zone == "UPD":
            # Refresh icon: apply the staged update and restart the picker on the
            # new version. The picker can't swap its own runtime venv, so the
            # launcher does it (action=refresh). #1430.
            self._decide({"action": "refresh"})
            return
        if zone == "V":
            self.sel = ("PR", 0) if self._kind() == "profiles" else ("M", 0)
        elif zone == "M":
            self.sel = ("BTN", 0)
        elif zone == "PR":
            self.btn_idx = 0            # progress to the Apply button
            self.sel = ("BTN", 0)
        elif zone == "BTN":
            btn = self.active_button()
            if btn == "N":
                # New worktree… opens the options dialog directly (#1346).
                self._open_optmenu()
            elif btn == "TH":
                self.show_hidden = not self.show_hidden
                n = self._hidden_count()
                self.debug = (f"{'showing' if self.show_hidden else 'hiding'} "
                              f"{n} bridge/system worktree(s)")
                if self.sel not in self.stops():
                    self.sel = self.default_sel()
            elif btn == "K":
                self._open_cleanup()
            elif btn == "SY":
                self._open_sync()
            elif btn == "PReset":
                self.grid = dict(self.applied)
                self.debug = "reset · reverted to applied profiles"
            elif btn == "PA":
                self._apply_profiles()
        elif zone == "L":
            # Enter routing (#2258 follow-up): a real *multi*-selection (>1)
            # opens the bulk action menu; a single selection (or none) opens the
            # focused/selected row's sub-menu, which carries Open/Resume/Stop/…
            # A single selected row must still reach Open/Resume -- the operator
            # should not have to deselect it first (#1343 unified model).
            if len(self.wt_sel) > 1:
                self._open_wt_action_menu()
            else:
                self._open_submenu()
        elif zone == "C":
            # Maintenance: Enter opens the maintenance actions menu for the
            # selected set (#1345) -- it never opens/resumes a worktree.
            self._open_maint_menu()
        elif zone == "SA":
            self._toggle_maint_all()
        elif zone == "GH":
            self._toggle_group(self.sel[1])
        elif zone == "T":
            # Registered pivot: Enter opens the task action sub-menu.
            self._open_task_menu()

    def _local_model_hosts(self):
        """Machines that can host a local model (the agent runs on their GPU).

        Convention-driven from local-machine config -- intentionally NOT
        hardcoded. The data source may advertise the capability via
        ``src.local_model_hosts`` (a set of machine display names); until that
        convention is wired, this is empty, so the 'Local model' create option
        does not appear.
        """
        return set(getattr(self.src, "local_model_hosts", None) or ())

    def _open_optmenu(self):
        tm, te = self.create_target()
        opts = [
            {"label": "Anchor repo", "on": False,
             "hint": "launch in the main checkout, not a worktree"},
            {"label": "Bare", "on": False,
             "hint": "new worktree, no Copilot bootstrap"},
            {"label": "No Mux", "on": False, "hint": "skip PSMux/TMux wrapper"},
        ]
        if tm in self._local_model_hosts():
            opts.append({"label": "Local model", "on": False,
                         "hint": f"run the agent on {tm}'s GPU"})
        # Open straight onto the Create button (section 1) with no options
        # checked, and confirm the target machine in the prompt (#1346).
        dlg = {"target": (tm, te), "section": 1, "bidx": 0,
               "verb": "New worktree", "confirm": "Create",
               "prompt": f"Creates on {tm} {te} · options (none required):",
               "opts": opts}

        def _after(confirmed):
            if confirmed:
                self._confirm_new_worktree(dlg)
        self.app.push_screen(ScopeDlgScreen(dlg), _after)

    @staticmethod
    def _cleanable(rec):
        """Whether a worktree's cleanup bucket is one the Cleanup flow offers."""
        return rec.get("cleanup_bucket") in (
            "clean", "unused", "conversation", "gone")

    @staticmethod
    def _warning(rec) -> bool:
        """Inconsistent state: a healthy ``wt-<id>`` mux session AND a *separate*
        bare (un-muxed) bound Copilot on the same worktree (the #662
        double-binding). Stop reaches the mux but not the stray orphan; Reclaim
        would kill the orphan but is unsafe to auto-offer beside a live mux (it
        reaps un-muxed bindings machine-wide for the id). So the row is flagged
        WARNING and offered **Stop + Repair** -- Repair reaps the stray orphan
        while preserving the healthy mux, then re-derives state.
        """
        return bool(rec.get("mux_live") and rec.get("session_bare_orphan"))

    @staticmethod
    def _reclaimable(rec) -> bool:
        """Whether a bound Copilot or lock residue that **Stop cannot reach**
        (i.e. no live mux) is present, so the Reclaim verb applies. The
        load-bearing invariant: a worktree holding a bound lock or lock residue
        must always expose *some* lifecycle verb (Stop when muxed, else Reclaim)
        -- never strand the row with no way to act on it.

        True when there is **no live mux** AND any of:

        * ``session_bare_orphan`` -- the machine-wide scan flagged a **bare**
          (un-muxed) bound Copilot (#662/#1416).
        * a live bound lock -- ``session_lock_live`` (authoritative menu-open
          verdict) or ``session_bound_live`` (cached off-hot-path hint) -- whose
          homing could not be positively classified ``bare``.
        * ``session_bridge_live`` -- a live **bridge-owned** Copilot (#4272),
          read file-first from ``bridge.lock`` (cwd=home, so invisible to the
          mux + cwd-keyed lock scans -- #1416). Without this, an
          ACTIVE-via-bridge worktree with no mux and no row-visible inuse lock
          would fall through to Resume/Bare-resume -- which then FAIL because the
          bridge Copilot already holds the session -- stranding the row.
          ``reclaim_one`` resolves the bridge.lock's owner pid (via
          :func:`reclaim.resolve_bridge_bound`) so this verb actually reaps it.
        * ``session_lock_stale`` -- stale ``inuse.<pid>.lock`` residue from a
          crashed/killed session (file present, pid dead). Reclaim clears it to
          zero ("to the point where the pid lock file is removed").

        The **no-mux guard** keeps Reclaim mutually exclusive with the muxed
        ``{Open, Stop}`` group and routes the mux+orphan double-binding to
        WARNING/Repair instead (see :meth:`_warning`).
        """
        if rec.get("mux_live"):
            return False
        return bool(
            rec.get("session_bare_orphan")
            or rec.get("session_lock_live")
            or rec.get("session_bound_live")
            or rec.get("session_bridge_live")
            or rec.get("session_lock_stale")
        )

    @staticmethod
    def _session_action_verbs(rec) -> list[str]:
        """The session-lifecycle verbs a worktree's Actions menu offers, from its
        (freshly menu-verified) liveness signals -- a pure, record-driven helper
        so the gating is unit-testable and each verb lights up *when and only
        when* it applies. The caller appends bridge/system navigation +
        cross-plugin verbs, which need engine state.

        Mutually-exclusive lifecycle groups, in precedence order (the operator's
        state map). The five axes: **M**=live ``wt-<id>`` mux, **Lf/Pa**=lock
        file / live bound process, **stale**=lock residue, **H**=identifiable
        head session, **D**=worktree dir exists.

        1. **WARNING** (M ∧ stray bare orphan) -> ``Stop`` + ``Repair``.
        2. **healthy mux** (M) -> ``Open`` (only when D -- a leaked mux on a gone
           dir offers ``Stop`` alone) + ``Stop``.
        3. **bound / residue, no mux** (¬M ∧ (Pa ∨ Lf ∨ stale)) -> ``Reclaim``
           (kills bound proc(es) AND deletes residual ``inuse.*.lock``). Resume/
           Bare-resume are suppressed here -- Reclaim first, then resume.
        4. **resumable** (¬M ∧ ¬bound ∧ H ∧ D) -> ``Resume`` + ``Bare resume``.
        5. **sessionless** (¬M ∧ ¬bound ∧ ¬H ∧ D) -> ``Open`` (cold start).
           Refresh (always) also attempts to recover a *lost* head session so a
           falsely-sessionless worktree becomes resumable on the next paint.
        6. **gone** (¬D, no live mux/lock) -> cleanup verbs only.

        Group exclusivity ({Open,Stop} ⊻ {Resume,Bare resume} ⊻ {Reclaim}) holds
        because M, (¬M ∧ bound), and (¬M ∧ ¬bound) partition every state.

        ``Refresh`` is ALWAYS appended -- the on-demand live gather + cache
        write-back (the only way to populate an **Unknown** row and re-derive a
        stale one), which also runs the head-session recovery repair.
        """
        gone = rec.get("cleanup_bucket") == "gone"
        warning = PickerScreen._warning(rec)
        reclaimable = PickerScreen._reclaimable(rec)
        if warning:
            acts = ["Stop", "Repair"]
        elif rec.get("mux_live"):
            # Open attaches the live mux (needs the dir); a leaked mux on a gone
            # worktree offers Stop alone to clear it.
            acts = ["Open", "Stop"] if not gone else ["Stop"]
        elif reclaimable:
            acts = ["Reclaim"]
        elif gone:
            acts = []
        elif not rec.get("sessionless"):
            # A stopped worktree with prior history (not positively sessionless)
            # -> Resume (relaunch + resume its last conversation). "Bare resume"
            # (create the mux but launch Copilot in HOME with no --resume, then
            # a manual ``/resume <id>``) is offered only when we have a concrete
            # head-session id to hand the operator.
            acts = ["Resume"]
            if rec.get("last_session_id"):
                acts.append("Bare resume")
        else:
            # Sessionless: cold-start Open (resuming nothing would silently
            # blank-start, #1026). A worktree that only *looks* sessionless
            # because tracking lost its head session is repaired by Refresh.
            acts = ["Open"]
        # Read-only "Messages" peek -- an auxiliary, non-lifecycle verb offered
        # for any worktree that could have a session to peek (not positively
        # sessionless) and is not in the inconsistent WARNING state. Independent
        # of the lifecycle group above (live, resumable, or residual all peek).
        if not warning and not rec.get("sessionless"):
            acts.append("Messages")
        # FF-sync / cleanup / finalize -- offered only in the non-broken,
        # non-residue lifecycle states (never beside Reclaim/Repair, where a
        # Cleanup/Sync would race the residue). A gone worktree still offers
        # Cleanup to prune the leftover record.
        if acts and not warning and not reclaimable and not gone:
            if rec.get("ff_eligible"):
                acts.append("Sync")
            if PickerScreen._cleanable(rec):
                acts.append("Cleanup")
            if rec.get("cleanup_bucket") in ("conversation", "unused"):
                # A conversation-only / unused worktree (no commits) can be
                # wrapped up directly -- finalize validates nothing is unpushed
                # and removes it (#2258 follow-up).
                acts.append("Finalize")
        elif gone and PickerScreen._cleanable(rec):
            acts.append("Cleanup")
        acts.append("Refresh")
        return acts

    def _submenu_target(self):
        """The record the per-row sub-menu acts on: the single selected row when
        exactly one is selected (so Enter opens/resumes *it* even if the cursor
        has drifted, #2258 follow-up), otherwise the focused row."""
        if len(self.wt_sel) == 1:
            wid = next(iter(self.wt_sel.ids))
            for r in self.list_records():
                if r.get("id4") == wid:
                    return r
        return self._selected_record()

    def _open_submenu(self):
        rec = self._submenu_target()
        if not rec:
            return
        # Always-async UX: OPEN the Actions menu IMMEDIATELY from the record's
        # current (bulk-derived) liveness -- transition to the next component at
        # once, show cached content, never freeze while probing. #4057: opening the
        # menu is one of the two moments we want the TRUTH for THIS worktree's mux +
        # bound-Copilot liveness, but that re-verify touches the mux + session locks
        # (cross-process). So when it's warranted (a real worktree with a record) we
        # run it OFF the render flow and REFINE the verb set in place when it lands;
        # the modal carries a footer spinner meanwhile. A cheap record-existence
        # stat decides whether to probe -- a mock/fixture row (no record) just opens
        # with its hand-set liveness, no spinner, no refine.
        _wt_id = (rec.get("raw") or {}).get("id")
        _need_verify = False
        if self.real_ops and _wt_id:
            try:
                from .. import config as _config
                _need_verify = (_config.tracking_dir() / f"{_wt_id}.yaml").exists()
            except Exception:
                _need_verify = False
        self._push_wt_submenu(rec, loading=_need_verify)
        if not _need_verify:
            return

        def _verify():
            try:
                import types as _types

                from .. import sessions as _sessions
                from .. import tracking as _tracking
                verdict = _sessions.verify_worktree_active(
                    _types.SimpleNamespace(worktree_id=_wt_id))
                try:
                    # #4057: warm the ground-layer cache from this authoritative
                    # read so the next populate can prefer the hint (throttled).
                    _tracking.stamp_mux_live(_wt_id, verdict.mux_live, refresh=True)
                except Exception:
                    pass
                return verdict
            except Exception:
                return None

        def _done(verdict):
            if verdict is not None:
                rec["mux_live"] = verdict.mux_live
                rec["attached"] = verdict.mux_clients > 0
                rec["session_lock_live"] = bool(verdict.live_session_ids)
                rec["session_bare_orphan"] = verdict.bare
            # Refine the OPEN menu's verbs in place + drop its footer spinner. The
            # main footer stays quiet -- the modal owns the load indicator.
            self._refresh_wt_submenu(rec)

        self._run_bg("Actions", _verify, _done, quiet=True)

    def _wt_submenu_verbs(self, rec):
        """Compute the worktree Actions verb list + the cross-plugin ``ext`` map
        from the record's CURRENT liveness. Pure -- engine state only, no IO -- so
        it is safe on the render flow and is recomputed cheaply on an in-place
        refine."""
        # Primary verb + Stop/Reclaim gating is the pure, record-driven
        # ``_session_action_verbs`` (unit-tested #4058); the bridge/system nav +
        # cross-plugin verbs below need engine state, so they are appended here.
        acts = self._session_action_verbs(rec)
        # #1424/#2178: a bridge/system worktree is host-owned. Prefer jumping to
        # the *caller* worktree that requested it (the "caller-id"), when that
        # worktree is loaded; otherwise fall back to jumping to its own host tab.
        # Only offer an action that actually resolves, so it's never dead.
        if rec.get("kind") in ("bridge", "system"):
            caller = (rec.get("raw") or {}).get("caller_worktree")
            if caller and any(
                    (w.get("raw") or {}).get("id") == caller for w in self.data):
                acts.append("Jump to caller")
            elif self._machine_index_for(
                    rec.get("machine"), rec.get("env")) is not None:
                acts.append("Jump to host")
        # Cross-plugin worktree actions (#B): any installed layer can add a verb
        # to this menu. Only actions whose `when` matches the worktree appear,
        # and a contributed label never shadows a built-in verb.
        from . import pivots as _pivots

        ext: dict = {}
        for act in getattr(self, "wt_actions", []) or []:
            if act.label in acts or act.label in ext:
                continue
            try:
                if _pivots.worktree_action_matches(act, rec):
                    acts.append(act.label)
                    ext[act.label] = act
            except Exception:
                continue

        return acts, ext

    def _push_wt_submenu(self, rec, *, loading=False):
        """Open the native ``SubMenuScreen`` for ``rec`` IMMEDIATELY from its
        current (cached) liveness -- never blocking the render flow. When an
        authoritative re-verify is in flight (``loading=True``), the modal shows the
        footer spinner and the verb set is refined in place by
        :meth:`_refresh_wt_submenu` when the probe lands."""
        acts, ext = self._wt_submenu_verbs(rec)
        self._wt_submenu_ext = ext
        # Migrated to a native Textual ``ModalScreen`` (#88 F4): the modal returns
        # the chosen ``(action_label, no_mux)`` via ``dismiss`` (or ``None`` on
        # cancel); ``_wt_submenu_dispatch`` runs the selected verb.
        self.app.push_screen(
            SubMenuScreen(rec, acts, loading=loading, engine=self),
            lambda result: self._wt_submenu_dispatch(rec, result),
        )

    def _refresh_wt_submenu(self, rec):
        """Refine the OPEN Actions menu's verbs in place after the async liveness
        verify lands (and drop its footer spinner). A no-op if the operator already
        closed the menu."""
        acts, ext = self._wt_submenu_verbs(rec)
        self._wt_submenu_ext = ext
        scr = getattr(self.app, "screen", None)
        if isinstance(scr, SubMenuScreen):
            scr.refresh_actions(acts)

    def _wt_submenu_dispatch(self, rec, result):
        """Run the chosen worktree Actions verb (the ``SubMenuScreen`` dismiss
        callback). Reads the CURRENT cross-plugin map (``_wt_submenu_ext``) so a
        live in-place verb refine stays consistent."""
        if result is None:
            return
        cur, no_mux = result
        ext = getattr(self, "_wt_submenu_ext", {}) or {}
        if cur in ext:
            # A cross-plugin contributed action (#B): run it and rescan.
            self._run_wt_action(ext[cur], rec)
            return
        if cur == "Open":
            self._decide(self._resume_decision(rec, no_mux=no_mux))
        elif cur == "Resume":
            # #4043: No-Mux now rides Resume too (a stopped worktree can be
            # resumed without the mux wrapper for troubleshooting), not just
            # Open. no_mux is inert unless the toggle was flipped.
            self._decide(self._resume_decision(rec, no_mux=no_mux))
        elif cur == "Bare resume":
            # Two-step restore: mux + Copilot in HOME, no --resume (#outage).
            self._decide(self._resume_decision(rec, bare_resume=True))
        elif cur == "Messages":
            # Read-only peek at the worktree's latest session messages.
            self._open_msgview(rec)
        elif cur == "Jump to host":
            # Internal navigation -- stay in the picker (#1424).
            self._jump_to_worktree((rec.get("raw") or {}).get("id"))
        elif cur == "Jump to caller":
            # Navigate to the worktree that requested this bridge (#2178).
            self._jump_to_worktree(
                (rec.get("raw") or {}).get("caller_worktree"))
        elif cur == "Sync":
            # Real per-worktree FF-sync via the shared dialog (#1427).
            self._open_sync(ids={rec.get("id4")})
        elif cur == "Cleanup":
            self._open_cleanup(ids={rec.get("id4")})
        elif cur == "Finalize":
            # Wrap up a conversation-only / unused worktree (#2258 follow-up).
            self._start_finalize([rec])
        elif cur == "Stop":
            # Stop the worktree's Mux/Copilot wrapper on demand (#1343),
            # freeing it to be re-Opened/Resumed with a fresh Mux + Copilot.
            self._start_stop(rec)
        elif cur == "Reclaim":
            # Kill the exact Copilot process holding the session's lock
            # (bare orphans Stop cannot reach); then re-Open / Bare resume.
            self._start_reclaim(rec)
        elif cur == "Repair":
            # Reconcile the mux+stray-orphan double-binding: reap the bare
            # orphan while preserving the healthy mux, clear stale locks.
            self._start_repair(rec)
        elif cur == "Refresh":
            # picker-cache-first-paint (dotfiles#948): on-demand live gather
            # + cache write-back for THIS worktree (populates an Unknown row
            # / re-syncs a stale one) without a full-fleet reload.
            self._start_refresh(rec)

    def _wt_action_ctx(self, rec: dict) -> dict:
        """Placeholder context for a contributed worktree action's argv template:
        the worktree's id/machine/env/repo plus its (scalar) raw fields."""
        raw = rec.get("raw") or {}
        ctx = {k: v for k, v in raw.items()
               if isinstance(v, (str, int, float, bool))}
        ctx.update({
            "worktree": raw.get("id") or rec.get("id4"),
            "id": raw.get("id") or rec.get("id4"),
            "id4": rec.get("id4"),
            "machine": str(rec.get("machine") or raw.get("machine") or ""),
            "env": str(rec.get("env") or ""),
            "repo": getattr(self.src, "REPO", "") or "",
            "title": rec.get("title", ""),
            "state": rec.get("state", ""),
        })
        return ctx

    def _run_wt_action(self, action, rec: dict) -> None:
        """Run a contributed worktree action (subprocess), report the outcome,
        and rescan (the action may have changed worktree/session state). The
        subprocess runs OFF the render flow via :meth:`_run_bg`."""
        from . import tasks

        label, source = action.label, action.source
        ctx = self._wt_action_ctx(rec)

        def _work():
            return tasks.run_worktree_action(action, ctx)

        def _done(result):
            ok, msg = result
            self.debug = (f"{label} ({source}): {msg or 'done'}" if ok
                          else f"{label} ({source}) failed: {msg}")
            try:
                self.setup()
                self.sel = self.default_sel()
            except Exception:
                pass

        self._run_bg(label, _work, _done)

    # ---- Recent-messages viewer (read-only session peek) ----
    def _open_msgview(self, rec, *, limit=3):
        """Open the recent-messages overlay for a worktree and start loading.

        Read-only companion to the disposition summary: shows the last few
        conversation turns of the worktree's latest session so the operator can
        tell what it was doing (and whether it still needs follow-up) without
        opening it. The load runs off the render thread -- local worktrees call
        the summary layer in-process; remote worktrees run ``recent-messages``
        over SSH. Never blocks or crashes the UI: a failure resolves to an error
        line in the overlay.

        Migrated to a native Textual ``ModalScreen`` (#88 F4): this builds the
        engine-owned ``self.msgview`` dict, starts the daemon loader thread
        (which populates it under ``_msgview_lock``), then pushes the
        ``MsgViewScreen`` that renders it, repaints while it loads, and mirrors
        the old ``_key_msgview`` (scroll + close). The screen holds no state of
        its own and needs no callback.
        """
        self.msgview = {
            "rec": rec, "limit": limit, "loading": True,
            "messages": [], "error": None, "session_id": None, "scroll": 0,
            "sessions": [],
        }
        threading.Thread(
            target=self._msgview_worker, args=(rec, limit),
            name="msgview-load", daemon=True,
        ).start()
        self.app.push_screen(MsgViewScreen(self))

    def _load_worktree_sessions(self, rec, wt_id, m, e):
        """Fetch the worktree's Copilot session registry (id + title + head).

        Best-effort, off the render thread: local worktrees read the registry
        in-process; remote worktrees run ``list-sessions`` over SSH. Returns a
        list of session dicts (each carries ``id``, ``name``, ``is_head``,
        ``state``) or ``[]`` on any error -- the session list is a diagnostic
        aid, never worth failing the overlay over.
        """
        try:
            if (m, e) == getattr(self.src, "LOCAL", None):
                from .. import config as _cfg
                from .. import sessions as _sessions
                from .. import tracking as _tracking
                records = _tracking.list_records(_cfg.tracking_dir())
                record = next(
                    (r for r in records if r.worktree_id == wt_id), None)
                if record is None:
                    return []
                return _sessions.list_worktree_sessions(record)
            from . import data_ssh, maintenance
            argv = data_ssh.list_sessions_argv(m, e, wt_id)
            if argv is None:
                return []
            payload = maintenance._ssh_json(argv)
            sessions = payload.get("sessions", []) if isinstance(payload, dict) else []
            return sessions if isinstance(sessions, list) else []
        except Exception:
            return []

    def _msgview_worker(self, rec, limit):
        """Daemon-thread body: fetch recent messages + the session list."""
        wt_id = (rec.get("raw") or {}).get("id")
        m, e = rec.get("machine"), rec.get("env")
        sessions_list: list = []
        try:
            if not wt_id:
                payload = {"error": "no worktree id"}
            elif (m, e) == getattr(self.src, "LOCAL", None):
                from .. import config as _cfg
                from .. import sessions as _sessions
                from .. import tracking as _tracking
                records = _tracking.list_records(_cfg.tracking_dir())
                record = next(
                    (r for r in records if r.worktree_id == wt_id), None)
                if record is None:
                    payload = {"error": f"worktree {wt_id} not found locally"}
                else:
                    payload = _sessions.recent_worktree_messages(
                        record, limit=limit)
            else:
                from . import data_ssh, maintenance
                argv = data_ssh.recent_messages_argv(m, e, wt_id, limit=limit)
                if argv is None:
                    payload = {"error": f"no remote route to {m} {e}"}
                else:
                    payload = maintenance._ssh_json(argv)
        except Exception as exc:  # never let the loader thread crash the UI
            payload = {"error": str(exc) or type(exc).__name__}

        # The session list is a separate, best-effort fetch (diagnostic aid);
        # a failure here never turns the overlay into an error.
        if wt_id:
            sessions_list = self._load_worktree_sessions(rec, wt_id, m, e)

        with self._msgview_lock:
            # A late result for a viewer the operator already closed / reopened
            # is dropped (identity check on the live overlay's rec).
            mv = self.msgview
            if mv is None or mv.get("rec") is not rec:
                return
            mv["loading"] = False
            mv["sessions"] = sessions_list
            if payload.get("error"):
                mv["error"] = payload["error"]
            else:
                mv["messages"] = payload.get("messages", [])
                mv["session_id"] = payload.get("session_id")

    def _key_msgview(self, key):
        """Keys for the recent-messages overlay: scroll + close."""
        mv = self.msgview
        if key in ("escape", "q", "tab", "enter"):
            self.msgview = None
            return
        if key == "down":
            mv["scroll"] = mv.get("scroll", 0) + 1
        elif key == "up":
            mv["scroll"] = max(0, mv.get("scroll", 0) - 1)

    def _machine_index_for(self, machine, env):
        """Index of the (machine, env) tab in ``self.machines``, or None."""
        for i, (label, m, e, _ok) in enumerate(self.machines):
            if label != "All" and m == machine and e == env:
                return i
        return None

    def _jump_to_worktree(self, wid):
        """#1424/#1425: navigate to the Worktrees view, the host machine tab of
        the worktree with id ``wid``, and highlight that row.

        Resolves the row by **stable worktree id** (never a live list index,
        which shifts under machine-switch / reveal-hidden / background refresh),
        reveals hidden so a bridge/system row is focusable, and switches off any
        registered pivot. Internal navigation only -- never exits the picker.
        Returns ``(ok, message)``.
        """
        if not wid:
            return False, "no worktree id"
        row = next(
            (w for w in self.data if (w.get("raw") or {}).get("id") == wid),
            None,
        )
        if row is None:
            return False, "worktree not found on any loaded machine"
        machine, env = row.get("machine"), row.get("env")
        idx = self._machine_index_for(machine, env)
        if idx is None:
            self.debug = f"jump: host {machine} {env} not available"
            return False, f"host {machine} {env} not available"
        # Land on the Worktrees pivot (the jump can originate from a registered
        # pivot's internal action).
        for i, p in enumerate(self.pivots):
            if p["kind"] == "worktrees":
                self.htab = i
                break
        self.machine_idx = idx
        # Reveal the hidden set only if the jump target is itself hidden
        # (origin-based, #2668): a User-origin bridge/ACP worktree is already
        # visible, so jumping to it must not force the whole automation set open.
        if row.get("hidden") if "hidden" in row else (
                (row.get("kind") or "session") in ("system", "bridge")):
            self.show_hidden = True
        records = self.list_records()
        target_i = next(
            (i for i, r in enumerate(records)
             if (r.get("raw") or {}).get("id") == wid),
            None,
        )
        if target_i is None:
            # The tab may still be loading, or the row is filtered out; land on a
            # safe default so focus is never left on a phantom stop.
            self.sel = self.default_sel()
            self.debug = f"jumped to {machine} {env} (row not yet loaded)"
            return True, f"switched to {machine} {env}"
        self.sel = ("L", target_i)
        self.btn_idx = 0
        self.debug = f"jumped to {machine} {env} · …{str(wid)[-4:]}"
        return True, f"jumped to {machine} {env}"

    def _internal_pivot_action(self, verb, ctx):
        """Dispatch a registered pivot's INTERNAL (picker-navigation) action
        (#1425). Tiny and defensive: an unknown verb is a reported failure, never
        an exception. ``jump-host`` navigates to the entry's worktree by id;
        ``open-cli`` opens that worktree into a CLI session (exits the picker with
        a resume decision -- the shared launch-plumbing, #2253)."""
        if verb == "jump-host":
            return self._jump_to_worktree(ctx.get("worktree") or ctx.get("id"))
        if verb == "open-cli":
            return self._open_worktree_cli(ctx.get("worktree") or ctx.get("id"))
        return False, f"unknown internal action: {verb}"

    def _open_worktree_cli(self, wid):
        """#2253: open the worktree ``wid`` into a CLI session, the same way
        selecting its Worktrees row + Open does.

        Resolves the row by **stable worktree id** across loaded machines, builds
        the standard resume decision, and exits the picker so ``__main__`` maps it
        onto the resume/launch path (which, for a task pinned to that worktree,
        surfaces the handoff via ``/resume-handoff`` in the opened session). The
        launch-decision plumbing -- not a subprocess -- so a remote worktree still
        routes through the normal SSH handoff. Returns ``(ok, message)``; on
        success the caller's post-action re-anchor is a harmless no-op since the
        app is already exiting."""
        if not wid:
            return False, "no worktree id"
        row = next(
            (w for w in self.data if (w.get("raw") or {}).get("id") == wid),
            None,
        )
        if row is None:
            return False, "worktree not found on any loaded machine"
        decision = self._resume_decision(row)
        self._decide(decision)
        return True, f"opening …{str(wid)[-4:]} into a CLI session"

    # ---- ⚙ Configuration menu (hosts Profiles etc.) (#1426) ----
    def _cfgmenu_items(self):
        """The ⚙ Configuration menu entries, in display order: built-in
        config-placed pivots (Profiles) first, then cross-plugin contributed
        Configuration sections (#B slice 2). Each is a typed descriptor --
        ``{"kind": "pivot", "idx", "label"}`` (switches to that pivot) or
        ``{"kind": "section", "section", "label"}`` (runs a contributed command
        on Enter)."""
        items: list[dict] = [
            {"kind": "pivot", "idx": i, "label": self.htabs[i]}
            for i in self._config_pivots()
        ]
        for cs in getattr(self, "config_sections", []) or []:
            items.append({"kind": "section", "section": cs, "label": cs.label})
        return items

    def _open_cfgmenu(self):
        """Open the Configuration menu: the pivots placed under ⚙ Configuration
        (Profiles) plus any contributed Configuration sections. Selecting a
        pivot switches to it and focuses its body; selecting a section runs its
        command. User-local config only -- never repo-managed settings.

        Migrated to a native Textual ``ModalScreen`` (#88 F4): ``push_screen``s a
        ``CfgMenuScreen`` that owns the stack, focus, and key routing and returns
        the chosen item index via ``dismiss(int|None)``; the callback acts on the
        selection (``None`` cancels)."""
        items = self._cfgmenu_items()
        if not items:
            return
        # If the current pivot is already config-hosted, pre-select it.
        cur = next(
            (n for n, it in enumerate(items)
             if it["kind"] == "pivot" and it["idx"] == self.htab),
            0,
        )

        def _after(choice):
            if choice is None:
                return
            target = items[choice]
            if target["kind"] == "section":
                # A cross-plugin contributed Configuration section (#B slice 2):
                # run it and rescan (it may have changed config/session state).
                self._run_config_section(target["section"])
                return
            self.htab = target["idx"]
            self.btn_idx = 0
            self.top = 0
            self.sel = self.default_sel()      # focus the hosted pivot's body
        self.app.push_screen(CfgMenuScreen(items, cur), _after)

    def _config_section_ctx(self) -> dict:
        """Placeholder context for a contributed config section's argv template:
        the current machine identity and the picker's repo (config sections are
        global -- there is no per-worktree context)."""
        return {
            "machine": self._pivot_machine_id() or "",
            "repo": getattr(self.src, "REPO", "") or "",
        }

    def _run_config_section(self, section) -> None:
        """Run a contributed Configuration section (subprocess), report the
        outcome, and rescan (it may have changed config/session state). The
        subprocess runs OFF the render flow via :meth:`_run_bg`."""
        from . import tasks

        label, source = section.label, section.source
        ctx = self._config_section_ctx()

        def _work():
            return tasks.run_config_section(section, ctx)

        def _done(result):
            ok, msg = result
            self.debug = (f"{label} ({source}): {msg or 'done'}" if ok
                          else f"{label} ({source}) failed: {msg}")
            try:
                self.setup()
                self.sel = self.default_sel()
            except Exception:
                pass

        self._run_bg(label, _work, _done)

    # ---- registered-pivot (Tasks) action sub-menu ----
    def _open_task_menu(self):
        """Open the Enter action sub-menu for the focused task, built from the
        registered pivot's declared ``actions``.

        Migrated to a native Textual ``ModalScreen`` (#88 F4): ``push_screen``s a
        ``TaskMenuScreen`` that owns the stack, focus, and key routing and returns
        the chosen action index via ``dismiss(int|None)``; the callback runs the
        selected action (``None`` cancels)."""
        reg = self._reg_pivot()
        rec = self._selected_task()
        if reg is None or not rec or not reg.actions:
            if reg is not None and not reg.actions:
                self.debug = f"{reg.label}: no actions declared"
            return
        # D3: a pivot action may carry a `when` gate, so a verb only appears for
        # a row whose entry matches (e.g. Release only for an in-use CodeSpace).
        # Reuse the same matcher the contributed worktree actions use.
        from . import pivots as _pivots

        actions = [
            a for a in reg.actions
            if _pivots.entry_matches(getattr(a, "when", None), rec)
        ]
        if not actions:
            self.debug = f"{reg.label}: no actions for this row"
            return

        def _after(choice):
            if choice is not None:
                self._run_task_action(reg, actions[choice], rec)
        self.app.push_screen(TaskMenuScreen(reg, rec, actions), _after)

    def _task_action_ctx(self, reg, rec):
        """Placeholder context for an action's argv template: the entry's own
        fields plus picker context ({machine}, {worktree}, {id}, {title})."""
        ctx = {k: v for k, v in rec.items() if isinstance(k, str)}
        ctx.setdefault("id", rec.get(reg.id_field))
        ctx["task_id"] = rec.get(reg.id_field)
        ctx["title"] = rec.get(reg.title_field)
        wt = rec.get(reg.worktree_field) if reg.worktree_field else None
        ctx["worktree"] = wt or ""
        ctx["machine"] = self._pivot_machine_id() or ""
        return ctx

    def _run_bg(self, label, work, done=None, *, quiet=False):
        """Run a blocking cross-process / IO callable OFF the Textual render flow.

        Every pivot / worktree / config action shells out (agent-dispatch, git,
        ssh, ...); running that subprocess *inline* in the key or modal-dismiss
        handler blocked the whole event loop for up to the action timeout (30s),
        which froze the TUI and read as a crash. Here ``work()`` (the blocking
        call) runs on a daemon thread, and ``done(result)`` (the UI updates) is
        marshalled back onto the event loop via Textual's ``call_from_thread`` --
        so the render flow is never blocked and no widget is mutated off-thread.
        A worker exception surfaces on the status line instead of killing the
        thread. Returns immediately.

        While it runs, the footer shows the shared **animated spinner** + ``label``
        (via ``_busy_label``) so the action never looks inert. Pass ``quiet=True``
        when a *different* surface already shows the load state (e.g. the Actions
        menu's own footer spinner while it refines in place) -- then the main
        footer is left alone and ``done`` is still invoked (with ``None`` on
        error) so the caller can always finalize (drop its spinner)."""
        if not quiet:
            self._busy_label = label

        def _worker():
            try:
                result, err = work(), None
            except Exception as exc:  # a worker thread must never die silently
                result, err = None, exc

            def _apply():
                if not quiet:
                    self._busy_label = None
                if err is not None:
                    if quiet:
                        if done is not None:
                            try:
                                done(None)
                            except Exception:
                                pass
                    else:
                        detail = str(err).strip()
                        detail = detail.splitlines()[0] if detail else type(err).__name__
                        self.debug = f"{label} failed · {detail[:80]}"
                elif done is not None:
                    try:
                        done(result)
                    except Exception as exc:
                        self.debug = f"{label} · applied with error: {str(exc)[:60]}"

            app = getattr(self, "app", None)
            if app is not None:
                try:
                    app.call_from_thread(_apply)
                except Exception:
                    pass

        threading.Thread(
            target=_worker, name=f"pivot-action:{label}", daemon=True
        ).start()

    def _run_task_action(self, reg, action, rec):
        """Execute one task action, then invalidate the cached list so the row
        reflects the new state on the next fetch. An INTERNAL (navigation) action
        is dispatched in-process and does NOT invalidate the cache (#1425). A
        ``progress`` action (D4) streams into the modal ProgressScreen instead of
        the sync status-line path."""
        ctx = self._task_action_ctx(reg, rec)
        title = rec.get(reg.title_field) or rec.get(reg.id_field) or "task"
        if action.internal:
            ok, msg = self._internal_pivot_action(action.internal, ctx)
            # A navigation action re-anchors selection itself; only guard against
            # a now-invalid stop.
            if self.sel not in self.stops():
                self.sel = self.default_sel()
            if not ok:
                self.debug = f"{action.label} failed · {msg or 'see logs'}"
            return
        if getattr(action, "card", None) is not None:
            # A5: read-only scrollable card-detail modal; no subprocess, no cache
            # invalidation (nothing mutated).
            self._open_pivot_card(reg, action, rec)
            return
        if getattr(action, "form", None) is not None:
            # A5: native elicitation modal -> on submit, {field.<name>} tokens in
            # the action's `run` are substituted and the command is run (the steer
            # transport). Cache invalidation happens after the submitted run.
            self._open_pivot_form(reg, action, rec, ctx, title)
            return
        if getattr(action, "progress", False):
            self._run_task_action_progress(reg, action, ctx, title)
            return
        rt = self._pivot_runtime(reg)

        def _work():
            ok, msg = rt.run_action(action, ctx)
            rt.invalidate()   # off-thread: the next fetch reflects the new state
            return ok, msg

        def _done(result):
            ok, msg = result
            # The focused row may vanish after the action; re-anchor selection.
            if self.sel not in self.stops():
                self.sel = self.default_sel()
            short = (msg or "").splitlines()[0][:80] if msg else ""
            if ok:
                # Kick an immediate re-fetch + repaint of the current scope so the
                # row reflects the mutation at once (see _run_pivot_form_submit).
                try:
                    rt.ensure(self._pivot_scope_key())
                except Exception:
                    pass
                self.refresh()
                self.debug = f"{action.label} · {title}" + (f" — {short}" if short else "")
            else:
                self.debug = f"{action.label} failed · {short or 'see command output'}"

        self._run_bg(action.label, _work, _done)

    def _run_task_action_progress(self, reg, action, ctx, title):
        """Run a D4 progress-reporting pivot action: stream its NDJSON progress
        into the modal :class:`ProgressScreen`.

        Builds an ``action-stream`` progress dict the screen renders live (verb +
        message + optional pct bar), spawns a daemon reader that drives the
        pivot runtime's :meth:`RegisteredPivotRuntime.run_action_stream`, and
        updates the dict in place per frame. A late reader (the run the operator
        already closed) is dropped by identity. Esc cancels via the recorded
        ``cancel`` callback; the cache is invalidated on completion so the row
        reflects the mutation."""
        import threading as _threading

        rt = self._pivot_runtime(reg)
        cancel_ev = _threading.Event()
        prog = {
            "kind": "action-stream",
            "verb": action.label,
            "title": str(title),
            "msg": "starting…",
            "pct": None,
            "done": False,
            "error": "",
            "armed": True,
            "items": [],
            "cancel": cancel_ev.set,
        }
        self.progress = prog

        def _on_frame(pct, msg):
            if self.progress is prog:
                if pct is not None:
                    prog["pct"] = max(0.0, min(100.0, pct))
                if msg:
                    prog["msg"] = msg

        def _worker():
            ok, msg = rt.run_action_stream(
                action, ctx, _on_frame, should_cancel=cancel_ev.is_set)
            rt.invalidate()
            if self.progress is prog:
                prog["done"] = True
                if not ok:
                    prog["error"] = msg or "failed"
                elif msg:
                    prog["msg"] = msg

        _threading.Thread(target=_worker, daemon=True).start()
        self._open_progress()

    # ---- A5: steering-seam card + form modals (DISPATCH pivot) --------------
    def _open_pivot_card(self, reg, action, rec):
        """Open a read-only scrollable card-detail modal for the focused task
        (A5). The card's title/status/link/body are pulled from the action's
        declared dotted paths (defaults ``card.*``); nothing is mutated, so no
        subprocess runs and the list cache is untouched."""
        from . import pivots as _pivots

        spec = action.card or {}
        card = {
            "title": _pivots.resolve_path(rec, spec.get("title_from")),
            "status": _pivots.resolve_path(rec, spec.get("status_from")),
            "link": _pivots.resolve_path(rec, spec.get("link_from")),
            "body": _pivots.resolve_path(rec, spec.get("body_from")),
        }
        row_title = rec.get(reg.title_field) or rec.get(reg.id_field) or ""
        self.app.push_screen(PivotCardScreen(str(row_title), card))

    def _open_pivot_form(self, reg, action, rec, ctx, title):
        """Open the docked card + tabbed-elicitation modal for a ``kind:"form"``
        action. Reads the request-input field spec from the action's
        ``fields_from`` dotted path (e.g. ``card.request_input``) and the card
        prose (title/status/link/body) from the standard ``card.*`` paths (the
        action's ``title_from`` overrides the header). On Confirm it substitutes
        ``{field.<name>}`` / ``{fields}`` (+ entry tokens like ``{task_id}``)
        into ``run`` and executes it via the pivot runtime. Save/Cancel/Escape
        submit nothing (Save/Esc persist a resumable draft)."""
        from . import pivots as _pivots

        spec = action.form or {}
        raw_fields = _pivots.resolve_path(rec, spec.get("fields_from"))
        fields = _normalize_form_fields(raw_fields)
        card = {
            "title": _pivots.resolve_path(rec, spec.get("title_from")) or title,
            "status": _pivots.resolve_path(rec, "card.status"),
            "link": _pivots.resolve_path(rec, "card.link"),
            "body": (_pivots.resolve_path(rec, spec.get("body_from"))
                     or _pivots.resolve_path(rec, "card.body")),
        }
        task_id = ctx.get("task_id") or rec.get(reg.id_field) or ""

        def _after(values):
            if values is None:
                self.debug = f"{action.label} · saved/cancelled (no submit)"
                return
            self._run_pivot_form_submit(reg, action, ctx, title, values)

        self.app.push_screen(
            PivotFormScreen(card, fields, action.label, task_id=str(task_id)), _after
        )

    def _run_pivot_form_submit(self, reg, action, ctx, title, values):
        """Run a submitted form action (A5): resolve ``{field.<name>}`` + entry
        tokens in one safe pass, run the command via the pivot runtime, then
        invalidate the cached list so the row reflects the new state. The command
        (e.g. ``agent-dispatch steer submit``) is a subprocess, so it runs OFF the
        render flow via :meth:`_run_bg` -- Confirm returns instantly and the UI
        stays live while the coordinator round-trip completes."""
        from . import pivots as _pivots

        rt = self._pivot_runtime(reg)
        argv = _pivots.format_form_template(action.run, ctx, values)

        def _work():
            ok, msg = rt.run_resolved(argv)
            rt.invalidate()
            return ok, msg

        def _done(result):
            ok, msg = result
            if self.sel not in self.stops():
                self.sel = self.default_sel()
            short = (msg or "").splitlines()[0][:80] if msg else ""
            if ok:
                # ``_work`` already invalidated the cached list; kick an immediate
                # re-fetch of the current scope and repaint so the row reflects
                # the new state at once, instead of waiting on the idle ~2fps tick
                # (the Tasks pivot has no poll loop of its own). Combined with the
                # runtime's generation guard, a Confirmed card's status updates in
                # the pivot the moment the coordinator round-trip lands.
                try:
                    rt.ensure(self._pivot_scope_key())
                except Exception:
                    pass
                self.refresh()
                self.debug = f"{action.label} · {title}" + (f" — {short}" if short else "")
            else:
                self.debug = f"{action.label} failed · {short or 'see command output'}"

        self._run_bg(action.label, _work, _done)

    def _scope_label(self):
        return "All machines" if self.is_all() else \
            "{} {}".format(*self.cur_machine()[:2])

    def _impact_rows(self, ids):
        """Display rows ``(id4, machine_env, title)`` for the worktrees in
        ``ids`` -- the read-only impact list the Clean/Sync modal shows so the
        operator sees exactly what Confirm will act on."""
        return [(w["id4"], w.get("machine_env", ""), w.get("title", ""))
                for w in self.data if w["id4"] in ids]

    def _open_cleanup(self, ids=None):
        # With no explicit selection (the bulk "Clean" button), default the
        # checkboxes to the full *safe* cleanable set -- Merged & finalized +
        # Unused + Conversation-only -- so one Confirm sweeps every worktree the
        # safety model already deems prunable. Unsafe work never reaches a
        # cleanable bucket (dirty / ahead / follow-up / active are classified
        # UNSAFE and are not offered here), and the reap re-checks each worktree,
        # so the broader default stays behind the beyond-clean confirm gate. An
        # explicit selection stays conservative -- only the already-merged bucket
        # is pre-checked -- since the operator already hand-picked the scope.
        bulk = ids is None
        scope = self._scope_label() if bulk else f"{len(ids)} selected"
        rows = self.cleanup_rows()
        if not bulk:
            rows = [w for w in rows if w["id4"] in ids]
        clean = {w["id4"] for w in rows if w["cleanup_bucket"] == "clean"}
        unused = {w["id4"] for w in rows if w["cleanup_bucket"] == "unused"}
        convo = {w["id4"] for w in rows if w["cleanup_bucket"] == "conversation"}
        gone = {w["id4"] for w in rows if w["cleanup_bucket"] == "gone"}
        all_eligible = clean | unused | convo | gone
        dlg = {
            "verb": "Clean up", "prompt": "Select what to prune:",
            "confirm": "Confirm", "scope": scope, "section": 0, "bidx": 0,
            "opts": [
                {"label": "Merged & finalized", "on": True, "ids": clean,
                 "hint": f"work is on the default branch · {len(clean)}"},
                {"label": "Unused", "on": bulk, "ids": unused,
                 "hint": f"no commits, no conversation · {len(unused)}"},
                {"label": "Conversation-only", "on": bulk, "ids": convo,
                 "hint": f"no commits, but the session has chat history "
                         f"· {len(convo)}"},
                {"label": "All eligible", "on": False, "ids": all_eligible,
                 "hint": f"every prunable worktree · {len(all_eligible)}"},
            ],
        }

        def _after(confirmed):
            if confirmed:
                self._confirm_cleanup(dlg)
        self.app.push_screen(ScopeDlgScreen(dlg, self._impact_rows), _after)

    def _open_sync(self, ids=None):
        scope = self._scope_label() if ids is None else f"{len(ids)} selected"
        if ids is not None:
            rows = [w for w in self.data if w["id4"] in ids]
        elif self.is_all():
            rows = list(self.data)
        else:
            m, e, _ = self.cur_machine()
            rows = [w for w in self.data if w["machine"] == m and w["env"] == e]
        eligible = {w["id4"] for w in rows if w.get("ff_eligible")}
        skipped = len(rows) - len(eligible)
        dlg = {
            "verb": "Sync", "prompt": "Fast-forward worktrees onto the default "
            "branch (FF-only):",
            "confirm": "Confirm", "scope": scope, "section": 0, "bidx": 0,
            "opts": [
                {"label": "Eligible", "on": True, "ids": eligible,
                 "hint": f"clean · behind · no local commits · {len(eligible)}"
                         + (f"  ({skipped} skipped: ahead/dirty/active)"
                            if skipped else "")},
            ],
        }

        def _after(confirmed):
            if confirmed:
                self._confirm_cleanup(dlg)
        self.app.push_screen(ScopeDlgScreen(dlg, self._impact_rows), _after)

    # ---- Textual BINDINGS actions (truly-global shortcuts, #88 F3) ----
    # These fire only when on_key passed the event through to the framework,
    # which it does exclusively when no modal overlay is active -- so they need
    # no overlay guard of their own. Each mutates state then refreshes, since the
    # pass-through path skips on_key's own self.refresh().
    def action_pivot_next(self):
        self._switch_pivot(1)
        self.refresh()

    def action_pivot_prev(self):
        self._switch_pivot(-1)
        self.refresh()

    def action_machine_next(self):
        self._rotate_machine(1)
        self.refresh()

    def action_machine_prev(self):
        self._rotate_machine(-1)
        self.refresh()

    # Textual entry point
    def on_key(self, event):
        key = event.key
        # Truly-global shortcuts are owned by Textual BINDINGS (#88 F3): let them
        # bubble to the framework's binding system (do NOT stop the event) so the
        # matching action_* method fires. This ``on_key`` only ever runs for the
        # top-level views -- every modal is a native ModalScreen (#88 F4) that
        # sits above this widget on the screen stack and consumes keys itself --
        # so there is no overlay-active case to guard against. Everything else
        # goes to the manual dispatcher.
        if key in self.BINDING_KEYS:
            return
        event.stop()
        event.prevent_default()
        if event.character in ("[", "]"):
            key = event.character
        self._dispatch_key(key)
        self.refresh()


def _size_mb(w):
    # deterministic pseudo-size from id for the cleanup demo. id4 is normally a
    # 4-hex-char worktree-id suffix; fall back to a char-sum for any non-hex id
    # (e.g. test fixtures) so this pseudo-size never raises -- the compose/NF
    # path renders the maintenance size counter eagerly, on any id.
    id4 = w.get("id4", "") if hasattr(w, "get") else w["id4"]
    try:
        n = int(id4, 16)
    except (ValueError, TypeError):
        n = sum(ord(c) for c in str(id4))
    return 120 + (n % 300)


CLEAN_SPECS = [
    ("id4", "id", 4, "l", 2), ("state", "state", 6, "l", 6),
    ("machine_env", "machine env", 19, "l", 7),
    ("dispo", "disposition", 18, "l", 3), ("pr", "pr", 8, "l", 5),
    ("age", "age", 4, "l", 9), ("mib", "size", 6, "r", 9),
    ("title", "title", 10, "l", 1),
]
PROF_SPECS = [
    ("name", "name", 22, "l", 1), ("app", "host app", 12, "l", 3),
    ("scope", "scope (machine · env)", 20, "l", 2), ("status", "status", 13, "l", 4),
]


class QuitConfirmScreen(ModalScreen[bool]):
    """Native modal confirm for Esc/q on a top-level picker view (#88 F4;
    native-focus internals NF1).

    Migrated off the manual render/dispatch model onto a Textual ``ModalScreen``:
    Textual owns the screen stack, the dim backdrop, and key routing, and the
    screen returns its verdict via ``dismiss(bool)`` -- ``True`` quits, ``False``
    stays.

    **Native-focus internals (#88 NF1):** the ``[Quit] [Stay]`` row is a
    :class:`FocusGroup` (one tab-stop; ◀▶ to choose, Enter/Space to activate),
    replacing the former hand-rolled ``idx`` + ``on_key`` over a static ``Panel``.
    *Stay* is the group's initial choice, so a reflexive Enter never quits. The
    prompt and key-hint are ``Static``s in the same orange-framed ``Vertical`` as
    the menus. The y / n / Esc / q shortcuts stay as screen ``BINDINGS`` so they
    fire regardless of child focus.
    """

    CSS = """
    QuitConfirmScreen { align: center middle; background: $background 55%; }
    QuitConfirmScreen > #quit-frame {
        width: 48; height: auto; border: round #ffaf00;
        background: $surface; padding: 1 2;
    }
    QuitConfirmScreen #quit-prompt { height: auto; padding: 0 0 1 0; }
    QuitConfirmScreen FocusGroup { height: auto; }
    QuitConfirmScreen #quit-hint { color: grey; height: auto; padding: 1 0 0 0; }
    """
    BINDINGS = [
        Binding("y", "quit", show=False),
        Binding("n", "stay", show=False),
        Binding("escape", "stay", show=False),
        Binding("q", "stay", show=False),
    ]

    def compose(self) -> ComposeResult:
        with Vertical(id="quit-frame"):
            yield Static(Text(" Leave the worktree picker?", style=C_HEADER),
                         id="quit-prompt")
            yield FocusGroup([("quit", "Quit"), ("stay", "Stay")], initial=1,
                             id="quit-buttons")
            yield Static("y quit · n/Esc stay · ←/→ choose", id="quit-hint")

    def on_mount(self) -> None:
        self.query_one("#quit-frame", Vertical).border_title = "Quit the Picker?"
        # The FocusGroup composes its own child, so it may not be mounted yet at
        # screen on_mount; defer the focus until the layout settles.
        self.call_after_refresh(
            lambda: self.query_one("#quit-buttons", FocusGroup).focus())

    def on_focus_group_activated(self, event: "FocusGroup.Activated") -> None:
        self.dismiss(event.value == "quit")

    def action_quit(self) -> None:
        self.dismiss(True)

    def action_stay(self) -> None:
        self.dismiss(False)


class ProfConfirmScreen(ModalScreen[bool]):
    """Native modal confirm for a Profiles *Apply* (#88 F4; native-focus
    internals NF1).

    Migrated off the manual render/dispatch model onto a Textual ``ModalScreen``.
    It lists the exact terminal profiles each changed host column will gain (``+``)
    or lose (``-``) before anything is written, and returns its verdict via
    ``dismiss(True|False)`` -- ``True`` runs the per-host Apply, ``False`` cancels.
    The regeneration is destructive to the terminal app's profile list, so the
    explicit add/remove diff is always shown first.

    **Native-focus internals (#88 NF1):** the ``[Apply] [Cancel]`` row is a
    :class:`FocusGroup` (one tab-stop; ◀▶ to choose, Enter/Space to activate),
    replacing the former hand-rolled ``on_key`` over a static ``Panel``. The diff,
    the destructive-change warning, and the key-hint are ``Static``s in the same
    orange-framed ``Vertical`` as the menus. Esc/q cancel via ``BINDINGS``.
    """

    CSS = """
    ProfConfirmScreen { align: center middle; background: $background 55%; }
    ProfConfirmScreen > #prof-frame {
        width: 72; height: auto; max-height: 90%;
        border: round #ffaf00; background: $surface; padding: 1 2;
    }
    ProfConfirmScreen #prof-diff { height: auto; }
    ProfConfirmScreen #prof-warn { height: auto; padding: 1 0 0 0; }
    ProfConfirmScreen FocusGroup { height: auto; padding: 1 0 0 0; }
    ProfConfirmScreen #prof-hint { color: grey; height: auto; padding: 1 0 0 0; }
    """
    BINDINGS = [
        Binding("escape", "cancel", show=False),
        Binding("q", "cancel", show=False),
    ]

    def __init__(self, cf, host_cols) -> None:
        super().__init__()
        self._cf = cf
        self._host_cols = host_cols

    def compose(self) -> ComposeResult:
        with Vertical(id="prof-frame"):
            yield Static(self._diff_body(), id="prof-diff")
            yield Static(Text(" ⚠ Regenerates terminal profiles · fully restart "
                              "the terminal to see changes.", style=C_CAUTION),
                         id="prof-warn")
            yield FocusGroup([("apply", "Apply"), ("cancel", "Cancel")],
                             initial=0, id="prof-buttons")
            yield Static("Enter apply · Esc cancel", id="prof-hint")

    def _diff_body(self) -> Text:
        cf = self._cf
        changed = cf["changed"]
        n_add = sum(len(cf["diffs"][hi][0]) for hi in changed)
        n_rem = sum(len(cf["diffs"][hi][1]) for hi in changed)

        def _t(s):
            return f"{s.machine} {s.env} · {s.kind}"

        # Cap the visible diff rows so a very large change set never overruns the
        # terminal (mirrors the former overlay's ``maxr`` guard); Textual sizes
        # the rest via ``max-height`` + auto.
        try:
            maxr = max(4, self.app.size.height - 12)
        except Exception:
            maxr = 24

        body = Text()
        body.append(f" Review: +{n_add} added, -{n_rem} removed\n\n",
                    style=C_HEADER)
        shown = 0
        truncated = False
        for hi in changed:
            if shown >= maxr:
                truncated = True
                break
            _lbl, hm, he = self._host_cols[hi]
            added, removed = cf["diffs"][hi]
            body.append(f" {hm} {he}\n", style="bold grey85")
            shown += 1
            for s in added:
                if shown >= maxr:
                    truncated = True
                    break
                body.append(f"   + {_t(s)}\n", style=C_READY)
                shown += 1
            for s in removed:
                if shown >= maxr:
                    truncated = True
                    break
                body.append(f"   - {_t(s)}\n", style=C_WARN)
                shown += 1
        if truncated:
            body.append("   …", style=C_MUTED)
        return body

    def on_mount(self) -> None:
        changed = self._cf["changed"]
        self.query_one("#prof-frame", Vertical).border_title = (
            f"Apply profiles · {len(changed)} host column(s)")
        # The FocusGroup composes its own child, so it may not be mounted yet at
        # screen on_mount; defer the focus until the layout settles.
        self.call_after_refresh(
            lambda: self.query_one("#prof-buttons", FocusGroup).focus())

    def on_focus_group_activated(self, event: "FocusGroup.Activated") -> None:
        self.dismiss(event.value == "apply")

    def action_cancel(self) -> None:
        self.dismiss(False)


class TaskMenuScreen(ModalScreen[int]):
    """Native modal action sub-menu for a registered-pivot task (#88 F4;
    native-focus internals NF1).

    Lists the focused task's declared actions and returns the chosen action
    *index* via ``dismiss(int)``, or ``dismiss(None)`` on cancel; the caller runs
    the selected action.

    **Native-focus internals (#88 NF1):** the action list is a native Textual
    ``OptionList`` -- the framework owns focus, up/down, and Enter-to-select --
    below a header (task title + subtitle) and above a description pane that
    tracks the highlighted action (via ``OptionHighlighted``). Esc/q cancel via
    ``BINDINGS`` actions. Replaces the former hand-rolled ``idx`` + ``on_key``
    over a static ``Panel``.
    """

    CSS = """
    TaskMenuScreen { align: center middle; background: $background 55%; }
    TaskMenuScreen > #task-frame {
        width: 72; height: auto; border: round #ffaf00;
        background: $surface; padding: 0 1;
    }
    TaskMenuScreen OptionList {
        height: auto; border: none; background: $surface; padding: 0;
    }
    TaskMenuScreen OptionList:focus { background-tint: $surface 0%; }
    TaskMenuScreen OptionList > .option-list--option-highlighted,
    TaskMenuScreen OptionList:focus > .option-list--option-highlighted {
        background: #ffaf00; color: black; text-style: bold;
    }
    TaskMenuScreen #task-head { height: auto; padding: 0 0 1 0; }
    TaskMenuScreen #task-desc { color: grey; height: auto; padding: 1 0 0 0; }
    """
    BINDINGS = [
        Binding("escape", "cancel", show=False),
        Binding("q", "cancel", show=False),
    ]

    def __init__(self, reg, rec, actions) -> None:
        super().__init__()
        self._reg = reg
        self._rec = rec
        self._actions = actions

    def compose(self) -> ComposeResult:
        with Vertical(id="task-frame"):
            yield Static(self._header(), id="task-head")
            yield OptionList(*[a.label for a in self._actions], id="task-list")
            yield Static("", id="task-desc")

    def _header(self) -> Text:
        reg, rec = self._reg, self._rec
        title = rec.get(reg.title_field) or rec.get(reg.id_field) or ""
        sub_bits = []
        if reg.worktree_field and rec.get(reg.worktree_field):
            sub_bits.append(str(rec.get(reg.worktree_field)))
        if reg.subtitle_field and rec.get(reg.subtitle_field):
            sub_bits.append(str(rec.get(reg.subtitle_field)))
        t = Text()
        t.append(str(title), style=C_HEADER)
        if sub_bits:
            t.append("\n" + " · ".join(sub_bits), style=C_DIM)
        return t

    def on_mount(self) -> None:
        ol = self.query_one("#task-list", OptionList)
        self.query_one("#task-frame", Vertical).border_title = self._reg.label
        self._set_desc(0)
        ol.focus()

    def _set_desc(self, i) -> None:
        if self._actions and 0 <= i < len(self._actions):
            self.query_one("#task-desc", Static).update(
                self._actions[i].description or "")

    def on_option_list_option_highlighted(
            self, event: "OptionList.OptionHighlighted") -> None:
        self._set_desc(event.option_index)

    def on_option_list_option_selected(
            self, event: "OptionList.OptionSelected") -> None:
        self.dismiss(event.option_index)

    def action_cancel(self) -> None:
        self.dismiss(None)


class SubMenuScreen(ModalScreen[tuple]):
    """Native modal per-worktree action menu (#88 F4; native-focus internals NF1).

    A picker overlay migrated off the manual render/dispatch model onto a Textual
    ``ModalScreen``. It renders the focused worktree's header (title + meta) and
    its available verbs (Open/Resume, Messages, Sync, Cleanup, Finalize, Stop,
    Jump to host/caller, plus any contributed actions), and returns the chosen
    ``(action_label, no_mux)`` via ``dismiss(tuple)`` -- or ``dismiss(None)`` on
    cancel; the caller dispatches the verb.

    **Native-focus internals (#88 NF1):** the verbs are a native Textual
    ``OptionList`` -- the framework owns focus, up/down, and Enter-to-select --
    below a header (title + meta + session id) and above a description pane that
    tracks the highlight (via ``OptionHighlighted``). **No-mux** is an
    arrow-reachable **toggle row** at the bottom of that same list (shown when a
    primary launch verb -- *Open* or *Resume* -- is offered, since it modifies
    the launch, #4043): the operator's "no
    special keyboarding" steer, made reachable purely by the arrow keys -- ↓ onto
    the ``☐ No Mux`` row, Enter/Space flips it to ``☑`` and stays open; Enter on a
    verb dismisses. (An earlier take used a separate ``Checkbox`` only reachable
    by Tab, which the operator couldn't reach with the arrows -- folding it into
    the list fixes that.) ``no_mux`` is plain screen state. Esc/q cancel via
    ``BINDINGS``. Replaces the former hand-rolled ``idx`` + ``on_key`` over a
    static ``Panel``.
    """

    CSS = """
    SubMenuScreen { align: center middle; background: $background 55%; }
    SubMenuScreen > #sub-frame {
        width: 72; height: auto; max-height: 90%;
        border: round #ffaf00; background: $surface; padding: 1 2;
    }
    SubMenuScreen #sub-head { height: auto; padding: 0 0 1 0; }
    SubMenuScreen OptionList {
        height: auto; border: none; background: $surface; padding: 0;
    }
    SubMenuScreen OptionList:focus { background-tint: $surface 0%; }
    SubMenuScreen OptionList > .option-list--option-highlighted,
    SubMenuScreen OptionList:focus > .option-list--option-highlighted {
        background: #ffaf00; color: black; text-style: bold;
    }
    SubMenuScreen #sub-desc { color: grey; height: auto; padding: 1 0 0 0; }
    SubMenuScreen #sub-foot { color: grey; height: 1; padding: 1 0 0 0; }
    """
    BINDINGS = [
        Binding("escape", "cancel", show=False),
        Binding("q", "cancel", show=False),
        Binding("space", "toggle_nomux", show=False),
    ]

    _NOMUX_DESC = ("Launch (Open/Resume) WITHOUT the PSMux/TMux wrapper (for "
                   "troubleshooting). Enter/Space toggles this row.")

    def __init__(self, rec, actions, *, loading=False, engine=None) -> None:
        super().__init__()
        self._rec = rec
        self._actions = actions
        self._no_mux = False
        # Always-async: the menu opens IMMEDIATELY from cached liveness; when an
        # authoritative re-verify is in flight, ``loading`` shows the shared
        # animated spinner in the footer and the caller calls ``refresh_actions``
        # to refine the verbs in place when it lands. ``engine`` supplies the
        # shared ``spin()`` frame so the spinner is consistent across the app.
        self._loading = loading
        self._engine = engine
        self._foot_frame = 0
        self._spin_timer = None
        # The No-mux modifier rides the primary launch verb -- Open (live mux /
        # sessionless) OR Resume (stopped session) -- so the toggle row is offered
        # whenever either is available (#4043). It sits at the end of the
        # OptionList. Bare resume is deliberately excluded (it already implies a
        # mux-in-HOME, which no-mux would contradict).
        self._has_nomux = ("Open" in actions) or ("Resume" in actions)
        self._nomux_index = len(actions) if self._has_nomux else None

    @property
    def no_mux(self) -> bool:
        """The live No-mux toggle -- plain screen state, flipped from the
        arrow-reachable ``No Mux`` row."""
        return self._no_mux

    def _nomux_prompt(self) -> Text:
        glyph, gstyle = ("☑", "green") if self._no_mux else ("☐", "#5f5f5f")
        t = Text()
        t.append(glyph + " ", style=gstyle)
        t.append("No Mux")
        return t

    def _prompts(self):
        prompts = [Text(a) for a in self._actions]
        if self._has_nomux:
            prompts.append(self._nomux_prompt())
        return prompts

    def compose(self) -> ComposeResult:
        with Vertical(id="sub-frame"):
            yield Static(self._header(), id="sub-head")
            yield OptionList(*self._prompts(), id="sub-list")
            yield Static("", id="sub-desc")
            yield Static("", id="sub-foot")

    def _header(self) -> Text:
        rec = self._rec
        meta1 = (f" {rec.get('id4')} · {rec.get('machine')} · {rec.get('env')}"
                 f" · {rec.get('state')}")
        meta2 = (f" age {rec.get('age')} · sess {rec.get('sess')}"
                 f" · turns {rec.get('turns')} · PR {rec.get('pr')}")
        t = Text()
        t.append(f" {rec.get('title', '')}\n", style="bold")
        t.append(meta1 + "\n", style=C_DIM)
        t.append(meta2, style=C_DIM)
        # two-step-restore: show the full session id so the operator can type
        # ``/resume <id>`` after a Bare resume; flag a live bound lock / residue.
        sid = rec.get("last_session_id")
        if sid:
            if rec.get("mux_live") and rec.get("session_bare_orphan"):
                lock = " · ⚠ inconsistent (mux + stray orphan — Repair fixes it)"
            elif rec.get("session_bare_orphan"):
                lock = " · bound (⚠ bare orphan — Reclaim frees it)"
            elif rec.get("session_lock_live") and not rec.get("mux_live"):
                lock = " · bound (lock live — Reclaim frees it)"
            elif rec.get("session_lock_live"):
                lock = " · bound (lock live)"
            elif rec.get("session_lock_stale") and not rec.get("mux_live"):
                lock = " · stale lock (residue — Reclaim clears it)"
            else:
                lock = ""
            t.append(f"\n session {sid}{lock}", style=C_DIM)
        return t

    def on_mount(self) -> None:
        ol = self.query_one("#sub-list", OptionList)
        self.query_one("#sub-frame", Vertical).border_title = "Worktree actions"
        if self._actions:
            ol.highlighted = 0
        self._set_desc(0)
        ol.focus()
        if self._loading:
            # Show the shared animated spinner while the liveness re-verify runs;
            # the verbs above are already actionable from cached state.
            self._paint_foot()
            self._spin_timer = self.set_interval(0.1, self._paint_foot)

    def _spin_char(self) -> str:
        """The current spinner glyph -- the engine's shared frame when available
        (so it animates in lockstep with the rest of the app), else a local one."""
        eng = self._engine
        if eng is not None and hasattr(eng, "spin"):
            try:
                return eng.spin()
            except Exception:
                pass
        self._foot_frame += 1
        return SPINNER[self._foot_frame % len(SPINNER)]

    def _paint_foot(self) -> None:
        if not self._loading:
            return
        t = Text()
        t.append(f" {self._spin_char()} ", style="#ffaf00")
        t.append("refreshing worktree liveness…", style=C_DIM)
        self.query_one("#sub-foot", Static).update(t)

    def refresh_actions(self, new_actions) -> None:
        """Refine the verb list IN PLACE after the async liveness verify lands and
        drop the footer spinner (always-async: the menu opened immediately from
        cached state; this corrects the verbs without a re-open). Preserves the
        No-mux toggle and re-anchors the highlight."""
        self._loading = False
        if self._spin_timer is not None:
            try:
                self._spin_timer.stop()
            except Exception:
                pass
            self._spin_timer = None
        try:
            self.query_one("#sub-foot", Static).update("")
        except Exception:
            pass
        self._actions = list(new_actions)
        self._has_nomux = ("Open" in self._actions) or ("Resume" in self._actions)
        self._nomux_index = len(self._actions) if self._has_nomux else None
        try:
            ol = self.query_one("#sub-list", OptionList)
        except Exception:
            return
        prev = ol.highlighted or 0
        ol.clear_options()
        ol.add_options(self._prompts())
        count = ol.option_count
        if count:
            ol.highlighted = min(prev, count - 1)
        self._set_desc(ol.highlighted or 0)
        ol.focus()

    def _set_desc(self, i) -> None:
        if i == self._nomux_index:
            self.query_one("#sub-desc", Static).update(self._NOMUX_DESC)
        elif self._actions and 0 <= i < len(self._actions):
            self.query_one("#sub-desc", Static).update(
                ACTION_DESC.get(self._actions[i], ""))

    def _toggle_nomux(self) -> None:
        self._no_mux = not self._no_mux
        ol = self.query_one("#sub-list", OptionList)
        ol.replace_option_prompt_at_index(self._nomux_index, self._nomux_prompt())
        self._set_desc(self._nomux_index)

    def on_option_list_option_highlighted(
            self, event: "OptionList.OptionHighlighted") -> None:
        self._set_desc(event.option_index)

    def on_option_list_option_selected(
            self, event: "OptionList.OptionSelected") -> None:
        # Enter on the No-mux row toggles it and stays open; Enter on a verb
        # dismisses with the chosen action + the current No-mux state.
        if event.option_index == self._nomux_index:
            self._toggle_nomux()
            return
        self.dismiss((self._actions[event.option_index], self._no_mux))

    def action_toggle_nomux(self) -> None:
        # Space also toggles, but only while the No-mux row is highlighted (so a
        # stray Space on a verb is an inert no-op, never a launch).
        if self._nomux_index is None:
            return
        ol = self.query_one("#sub-list", OptionList)
        if ol.highlighted == self._nomux_index:
            self._toggle_nomux()

    def action_cancel(self) -> None:
        self.dismiss(None)



class FocusGroup(Widget):
    """A single focusable tab-stop containing several button-like choices; the
    arrow keys move an internal highlight and Enter/Space activate the
    highlighted one (#88 NF).

    The native answer to the tab-group requirement -- "one entry in a group
    receives tab-focus, you arrow to the rest" -- for the *heterogeneous* rows
    Textual's list widgets (`OptionList` / `SelectionList` / `RadioSet`) don't
    cover, e.g. a `Confirm` / `Cancel` button pair. The framework owns focus
    (this is one tab-stop); the widget owns only the intra-group highlight, and
    posts a :class:`FocusGroup.Activated` message on Enter/Space.
    """

    can_focus = True
    BINDINGS = [
        Binding("left", "move(-1)", show=False),
        Binding("up", "move(-1)", show=False),
        Binding("right", "move(1)", show=False),
        Binding("down", "move(1)", show=False),
        Binding("enter", "activate", show=False),
        Binding("space", "activate", show=False),
    ]

    class Activated(Message):
        """Posted when a choice is activated (Enter/Space on the highlight)."""

        def __init__(self, group: "FocusGroup", index: int, value: str) -> None:
            super().__init__()
            self.group = group
            self.index = index
            self.value = value

    def __init__(self, options, *, initial: int = 0, **kw) -> None:
        # options: list of (value, label)
        super().__init__(**kw)
        self._options = list(options)
        self._idx = max(0, min(initial, max(0, len(self._options) - 1)))
        self._focused = False

    @property
    def value(self) -> str:
        return self._options[self._idx][0]

    def compose(self) -> ComposeResult:
        # A child Static measures its own content width (a bare Widget.render()
        # does not, and Textual then clips the row) -- so the button row renders
        # in full.
        yield Static(self._row(), id="fg-row")

    def _row(self) -> Text:
        t = Text()
        for i, (_v, label) in enumerate(self._options):
            if i:
                t.append("   ")
            focused = self._focused and i == self._idx
            t.append(f" {label} ", style=C_BTN_SEL if focused else C_BTN)
        return t

    def _refresh_row(self) -> None:
        self.query_one("#fg-row", Static).update(self._row())

    def action_move(self, delta: int) -> None:
        if self._options:
            self._idx = (self._idx + delta) % len(self._options)
            self._refresh_row()

    def action_activate(self) -> None:
        if self._options:
            v, _label = self._options[self._idx]
            self.post_message(self.Activated(self, self._idx, v))

    def on_focus(self) -> None:
        self._focused = True
        self._refresh_row()

    def on_blur(self) -> None:
        self._focused = False
        self._refresh_row()


class _ScopeSelectionList(SelectionList):
    """SelectionList that toggles the highlighted option directly."""

    def action_select(self) -> None:
        highlighted = self.highlighted
        if highlighted is not None:
            self.toggle(self.get_option_at_index(highlighted))


class ScopeDlgScreen(ModalScreen[bool]):
    """Native modal scope dialog for Clean/Sync and New-worktree options (#88 F4;
    native-focus internals #88 NF1).

    Shared by ``cleanup`` (Clean/Sync) and ``optmenu`` (New-worktree options): a
    multi-select list of option toggles, a ``[Confirm] [Cancel]`` row, and -- for
    the Clean/Sync variant -- a **read-only impact list** naming exactly which
    worktrees the current toggle selection will act on. Returns ``dismiss(True)``
    on Confirm / ``dismiss(False)`` on Cancel or Esc; the option toggles are
    mirrored back onto the passed ``dlg`` dict (``opts[i]["on"]``) so the caller
    reads the confirmed selection straight off it, and ``_union()`` /
    ``_impact_fn`` stay valid live.

    **Native-focus internals (#88 NF1):** the toggles are a native Textual
    ``SelectionList`` (one tab-stop; arrow to move, Space to toggle -- the
    framework owns focus + checkbox state) and the button row is a
    :class:`FocusGroup` (one tab-stop; ◀▶ to choose, Enter to activate). Tab
    moves between the two -- the two-section model, now framework-native --
    replacing the former hand-rolled ``section``/``idx``/``bidx`` + ``on_key``
    over a static ``Panel``. Esc/q cancel via ``BINDINGS`` actions.
    """

    CSS = """
    ScopeDlgScreen { align: center middle; background: $background 55%; }
    ScopeDlgScreen > #scope-frame {
        width: 68; height: auto; max-height: 90%;
        border: round #ffaf00; background: $surface; padding: 1 2;
    }
    ScopeDlgScreen SelectionList {
        height: auto; border: none; background: $surface; padding: 0;
    }
    /* Cursor highlight (row + checkbox) paints only while the list actually
       holds focus. An unfocused options list must not highlight its "current
       target" at all, or a mere cursor position reads as a selection -- the
       root of #121 (operator mistakes the highlighted Anchor-repo row for a
       checked one). :blur explicitly neutralizes the framework's dimmed
       block-cursor so nothing lingers. */
    ScopeDlgScreen SelectionList:focus > .option-list--option-highlighted {
        background: #ffaf00; color: black; text-style: bold;
    }
    ScopeDlgScreen SelectionList:blur > .option-list--option-highlighted {
        background: $surface; color: $foreground; text-style: none;
    }
    ScopeDlgScreen SelectionList > .selection-list--button {
        background: $surface; color: #5f5f5f;
    }
    ScopeDlgScreen SelectionList:focus > .selection-list--button-highlighted {
        background: #ffaf00; color: black;
    }
    ScopeDlgScreen SelectionList:blur > .selection-list--button-highlighted {
        background: $surface; color: #5f5f5f;
    }
    /* Checked state stays visible regardless of focus -- it is real selection,
       not cursor position, so it must survive blur. */
    ScopeDlgScreen SelectionList > .selection-list--button-selected {
        background: green; color: white; text-style: bold;
    }
    ScopeDlgScreen SelectionList > .selection-list--button-selected-highlighted {
        background: green; color: white; text-style: bold;
    }
    ScopeDlgScreen #scope-prompt { height: auto; padding: 0 0 1 0; }
    ScopeDlgScreen #scope-impact { height: auto; padding: 1 0 0 0; }
    ScopeDlgScreen #scope-buttons { width: 1fr; height: auto; padding: 1 0 0 0; }
    """
    BINDINGS = [
        Binding("escape", "cancel", show=False),
        Binding("q", "cancel", show=False),
    ]

    def __init__(self, dlg, impact_fn=None) -> None:
        super().__init__()
        self._dlg = dlg
        self._impact_fn = impact_fn      # (ids:set) -> list[(id4, machine_env, title)]

    def _union(self) -> set:
        s: set = set()
        for o in self._dlg["opts"]:
            if o["on"]:
                s |= set(o.get("ids", ()))
        return s

    def _opt_prompt(self, o) -> Text:
        t = Text(f"{o['label']:<14}", style=C_LABEL)
        if o.get("hint"):
            t.append("  " + o["hint"], style=C_META)
        return t

    def compose(self) -> ComposeResult:
        dlg = self._dlg
        opts = dlg["opts"]
        with Vertical(id="scope-frame"):
            yield Static(Text(dlg.get("prompt", "Select:"), style=C_HEADER),
                         id="scope-prompt")
            yield _ScopeSelectionList(
                *[(self._opt_prompt(o), i, o["on"]) for i, o in enumerate(opts)],
                id="scope-opts")
            if self._impact_fn is not None:
                yield Static("", id="scope-impact")
            yield FocusGroup(
                [("confirm", dlg.get("confirm", "Confirm")), ("cancel", "Cancel")],
                id="scope-buttons")

    def on_mount(self) -> None:
        dlg = self._dlg
        verb = dlg.get("verb", "Clean up")
        scope = ("{} {}".format(*dlg["target"]) if "target" in dlg
                 else dlg.get("scope", ""))
        self.query_one("#scope-frame", Vertical).border_title = f"{verb} · {scope}"
        self._sync_from_selection()
        # optmenu opens straight on the Create button (section 1); Clean/Sync
        # opens on the toggle list.
        if dlg.get("section", 0) == 1:
            self.query_one("#scope-buttons", FocusGroup).focus()
        else:
            self.query_one("#scope-opts", SelectionList).focus()

    def _sync_from_selection(self) -> None:
        """Mirror the SelectionList's checked state back onto ``dlg['opts']`` so
        the caller (and ``_union`` / the impact list) reads the live selection."""
        chosen = set(self.query_one("#scope-opts", SelectionList).selected)
        for i, o in enumerate(self._dlg["opts"]):
            o["on"] = i in chosen
        if "target" in self._dlg:
            selected = [o["label"] for o in self._dlg["opts"] if o["on"]]
            prompt = Text(self._dlg.get("prompt", "Select:"), style=C_HEADER)
            prompt.append(
                "\nSelected: " + (", ".join(selected) if selected else "none"),
                style=C_READY if selected else C_MUTED,
            )
            self.query_one("#scope-prompt", Static).update(prompt)
        if self._impact_fn is not None:
            self._update_impact()

    def _update_impact(self) -> None:
        verb = self._dlg.get("verb", "Clean up")
        rows = self._impact_fn(self._union())
        body = Text()
        body.append(f"{verb}s {len(rows)} worktree(s):\n", style=C_HEADER)
        maxr = 10
        for id4, machine_env, title in rows[:maxr]:
            body.append(f"  {id4} · {machine_env} · {title}\n", style=C_FAINT)
        if len(rows) > maxr:
            body.append(f"  … +{len(rows) - maxr} more\n", style=C_MUTED)
        if not rows:
            body.append("  (nothing selected)\n", style=C_MUTED)
        self.query_one("#scope-impact", Static).update(body)

    def on_selection_list_selected_changed(
            self, event: "SelectionList.SelectedChanged") -> None:
        self._sync_from_selection()

    def on_focus_group_activated(self, event: "FocusGroup.Activated") -> None:
        self.dismiss(event.value == "confirm")

    def action_cancel(self) -> None:
        self.dismiss(False)


class CfgMenuScreen(ModalScreen[int]):
    """Native modal ⚙ Configuration menu (#88 F4; native-focus internals #88 NF1).

    A picker overlay migrated off the manual render/dispatch model onto a Textual
    ``ModalScreen``. It lists the config-hosted pivots (Profiles) plus any
    contributed Configuration sections and returns the chosen item *index* via
    ``dismiss(int)``, or ``dismiss(None)`` on cancel; the caller acts on the
    selection (switch to that pivot / run that section).

    **Native-focus internals (#88 NF1):** the menu list is now a native Textual
    ``OptionList`` -- the framework owns focus, up/down movement, and
    Enter-to-select -- replacing the former hand-rolled ``idx`` + ``on_key`` over
    a static ``Panel``. The title rides the frame border; a muted hint line sits
    inside (matching Maint/Task); Esc/q cancel via ``BINDINGS`` actions.
    ``dismiss(event.option_index)`` returns the choice.
    """

    CSS = """
    CfgMenuScreen { align: center middle; background: $background 55%; }
    CfgMenuScreen > #cfg-frame {
        width: 56; height: auto; max-height: 80%;
        border: round #ffaf00; background: $surface; padding: 1 2;
    }
    CfgMenuScreen OptionList {
        height: auto; border: none; background: $surface; padding: 0;
    }
    CfgMenuScreen OptionList:focus { background-tint: $surface 0%; }
    CfgMenuScreen OptionList > .option-list--option-highlighted,
    CfgMenuScreen OptionList:focus > .option-list--option-highlighted {
        background: #ffaf00; color: black; text-style: bold;
    }
    CfgMenuScreen #cfg-hint { color: grey; height: auto; padding: 1 0 0 0; }
    """
    BINDINGS = [
        Binding("escape", "cancel", show=False),
        Binding("q", "cancel", show=False),
    ]

    def __init__(self, items, idx=0) -> None:
        super().__init__()
        self._items = items
        self.idx = idx

    def compose(self) -> ComposeResult:
        with Vertical(id="cfg-frame"):
            yield OptionList(*[it["label"] for it in self._items], id="cfg-list")
            yield Static("↑↓ choose · Enter open · Esc back", id="cfg-hint")

    def on_mount(self) -> None:
        ol = self.query_one("#cfg-list", OptionList)
        self.query_one("#cfg-frame", Vertical).border_title = (
            "⚙ Configuration · user-local settings")
        if 0 <= self.idx < len(self._items):
            ol.highlighted = self.idx
        ol.focus()

    def on_option_list_option_selected(
            self, event: "OptionList.OptionSelected") -> None:
        self.dismiss(event.option_index)

    def action_cancel(self) -> None:
        self.dismiss(None)


class MaintMenuScreen(ModalScreen[int]):
    """Native modal Maintenance actions menu (#88 F4; native-focus internals NF1).

    A picker overlay migrated off the manual render/dispatch model onto a Textual
    ``ModalScreen``. It lists the maintenance actions available for the selected
    worktree set (Sync / Cleanup / Finalize / Stop) and returns the chosen action
    *index* via ``dismiss(int)``, or ``dismiss(None)`` on cancel; the caller runs
    the selection.

    **Native-focus internals (#88 NF1):** the action list is now a native Textual
    ``OptionList`` -- the framework owns focus, up/down movement, and
    Enter-to-select -- replacing the former hand-rolled ``idx`` + ``on_key`` over
    a static ``Panel``. A description pane below the list tracks the highlighted
    action (via ``OptionHighlighted``); Esc/q cancel via ``BINDINGS`` actions.
    """

    CSS = """
    MaintMenuScreen { align: center middle; background: $background 55%; }
    MaintMenuScreen > #maint-frame {
        width: 64; height: auto; border: round #ffaf00;
        background: $surface; padding: 1 2;
    }
    MaintMenuScreen OptionList {
        height: auto; border: none; background: $surface; padding: 0;
    }
    MaintMenuScreen OptionList:focus { background-tint: $surface 0%; }
    MaintMenuScreen OptionList > .option-list--option-highlighted,
    MaintMenuScreen OptionList:focus > .option-list--option-highlighted {
        background: #ffaf00; color: black; text-style: bold;
    }
    MaintMenuScreen #maint-desc { color: grey; height: auto; padding: 1 0 0 0; }
    """
    BINDINGS = [
        Binding("escape", "cancel", show=False),
        Binding("q", "cancel", show=False),
    ]

    def __init__(self, actions, count) -> None:
        super().__init__()
        self._actions = actions
        self._count = count

    def compose(self) -> ComposeResult:
        with Vertical(id="maint-frame"):
            yield OptionList(*self._actions, id="maint-list")
            yield Static("", id="maint-desc")

    def on_mount(self) -> None:
        ol = self.query_one("#maint-list", OptionList)
        self.query_one("#maint-frame", Vertical).border_title = (
            f"Maintenance · {self._count} selected")
        self._set_desc(0)
        ol.focus()

    def _set_desc(self, i) -> None:
        if self._actions and 0 <= i < len(self._actions):
            self.query_one("#maint-desc", Static).update(
                MAINT_ACTION_DESC.get(self._actions[i], ""))

    def on_option_list_option_highlighted(
            self, event: "OptionList.OptionHighlighted") -> None:
        self._set_desc(event.option_index)

    def on_option_list_option_selected(
            self, event: "OptionList.OptionSelected") -> None:
        self.dismiss(event.option_index)

    def action_cancel(self) -> None:
        self.dismiss(None)


class ProgressScreen(ModalScreen[None]):
    """Native modal maintenance/profiles progress run (#88 F4).

    The last live overlay migrated off the manual render/dispatch model onto a
    Textual ``ModalScreen``. It renders the engine's ``progress`` sub-dialog --
    each selected worktree (or profiles host column) as a row that advances
    pending(·) -> running(spinner) -> done(✓)/failed(✗) -- and, unlike the other
    (static) migrated overlays, it is **live**: an ``on_mount`` interval ticks
    the run forward (the mock walker, or a real ``MaintenanceExecutor`` poll) and
    repaints. It mirrors the former ``_key_progress`` exactly: an unarmed run
    shows the beyond-clean confirm gate (Enter proceeds/arms, Esc cancels), a
    done run closes on Enter/Esc.

    The run's state lives on the engine (``eng.progress`` / ``eng.executor``),
    because several entry points build it (``_confirm_cleanup``,
    ``_run_op_progress``, ``_start_profiles_run``) and the state-transition core
    (``_advance_progress`` / ``_key_progress``) stays unit-tested there. This
    screen is the native shell that drives and renders that state, dismissing
    itself once the engine clears ``progress``.
    """

    CSS = """
    ProgressScreen { align: center middle; background: $background 55%; }
    ProgressScreen > #progress { width: auto; height: auto; max-height: 90%; }
    """

    def __init__(self, eng) -> None:
        super().__init__()
        self._eng = eng

    def compose(self) -> ComposeResult:
        yield Static(self._panel(), id="progress")

    def on_mount(self) -> None:
        # Drive the run forward on our own interval (~10 fps), matching the pace
        # the background tick used to advance the mock walker.
        self.set_interval(0.1, self._on_tick)

    def _on_tick(self) -> None:
        eng = self._eng
        if eng.progress is None:
            # A direct engine poke (e.g. a unit test) cleared the run out from
            # under us -- close if we're still the top screen.
            if self.app.screen is self:
                self.dismiss(None)
            return
        if not eng.progress["done"]:
            eng._advance_progress()
        self._refresh()

    def _panel(self) -> Panel:
        eng = self._eng
        p = eng.progress
        if p is None:
            # The run was cleared before this screen finished mounting (e.g. a
            # direct engine poke in a unit test). Render empty; the interval
            # dismisses us on its next tick.
            return Panel(Text(""), border_style=C_DIM, width=68)
        if p.get("kind") == "action-stream":
            return self._action_stream_panel(p)
        items = p["items"]
        done = sum(1 for it in items if it["state"] in ("done", "failed"))
        failed = sum(1 for it in items if it["state"] == "failed")
        verb = p["verb"]
        body = Text()
        # Status sub-line: confirm gate / done / working.
        if not p.get("armed", True):
            n = len(items)
            extra = []
            if p.get("include_unused"):
                extra.append("unused")
            if p.get("include_conversations"):
                extra.append("conversation")
            tail = f" incl. {'/'.join(extra)}" if extra else ""
            sub = (f" ⚠ {verb.lower()} {n} worktree(s){tail}? "
                   "Enter=proceed Esc=cancel")
            substyle = "bold yellow"
        elif p["done"]:
            sub = f" done · {done}/{len(items)}" + (
                f" · {failed} failed" if failed else "")
            substyle = C_HEADER
        else:
            sub = f" {eng.spin()} working… {done}/{len(items)}"
            substyle = C_HEADER
        body.append(sub + "\n\n", style=substyle)
        # Item rows, windowed around the running item when the list is long.
        maxr = 12
        run = next((j for j, it in enumerate(items)
                    if it["state"] == "running"), len(items) - 1)
        lo = max(0, min(run - maxr // 2, max(0, len(items) - maxr)))
        for it in items[lo:lo + maxr]:
            st = it["state"]
            if st == "done":
                g, gc = "✓", C_READY
            elif st == "failed":
                g, gc = "✗", C_WARN
            elif st == "running":
                g, gc = eng.spin(), C_LOAD
            else:
                g, gc = "·", C_DIM
            row = Text("  ")
            row.append(g, style=gc)
            row.append(f" {it['id4']} ", style=C_META)
            title = it["title"]
            if len(title) > 46:
                title = title[:45] + "…"
            row.append(title, style="white" if st != "pending" else C_MUTED)
            body.append_text(row)
            body.append("\n")
        if len(items) > maxr:
            body.append(f" … {len(items)} total\n", style=C_MUTED)
        if p.get("op") == "profiles" and p["done"]:
            # #1368: after Apply the fragment is regenerated, but the terminal
            # app only re-reads it on a FULL restart -- spell out what changed
            # and that a restart is required so a "no visible change" reads as
            # expected, not as a silent failure.
            na, nr = p.get("n_add", 0), p.get("n_rem", 0)
            body.append(f"\n +{na} added · -{nr} removed\n", style=C_LABEL)
            body.append(
                " ⚠ Fully restart the terminal app (close all its windows) to "
                "see the changes.\n", style=C_CAUTION)
        # Button row.
        body.append("\n")
        btns = Text(" ")
        if not p.get("armed", True):
            btns.append(" Confirm ", style=C_BTN_SEL)
            btns.append("  ")
            btns.append(" Cancel ", style=C_BTN)
        elif p["done"]:
            btns.append(" Close ", style=C_BTN_SEL)
        else:
            btns.append(" Working… ", style=C_BTN)
        body.append_text(btns)
        return Panel(body, title=f"{verb} · {p['scope']}",
                     border_style=C_BAND, width=68)

    def _action_stream_panel(self, p) -> Panel:
        """Render a D4 progress-reporting action's live state: verb, latest
        message, an optional pct bar, and a Working…/Close button."""
        eng = self._eng
        verb = p.get("verb", "Action")
        body = Text()
        if p.get("done"):
            if p.get("error"):
                body.append(f" ✗ failed · {str(p['error'])[:60]}\n\n", style=C_WARN)
            else:
                body.append(" ✓ done\n\n", style=C_READY)
        else:
            body.append(f" {eng.spin()} working…\n\n", style=C_HEADER)
        title = str(p.get("title") or "")
        if title:
            body.append(f" {title[:60]}\n", style=C_META)
        pct = p.get("pct")
        if isinstance(pct, (int, float)):
            filled = round(max(0.0, min(100.0, pct)) / 100 * 40)
            bar = Text(" [")
            bar.append("█" * filled, style=C_READY)
            bar.append("·" * (40 - filled), style=C_DIM)
            bar.append(f"] {pct:5.1f}%")
            body.append_text(bar)
            body.append("\n")
        msg = str(p.get("msg") or "")
        if msg:
            body.append(f" {msg[:62]}\n", style="white")
        body.append("\n")
        btn = Text(" ")
        btn.append(" Close " if p.get("done") else " Cancel ",
                   style=C_BTN_SEL if p.get("done") else C_BTN)
        body.append_text(btn)
        return Panel(body, title=verb, border_style=C_BAND, width=68)

    def _refresh(self) -> None:
        if self._eng.progress is not None:
            self.query_one("#progress", Static).update(self._panel())

    def on_key(self, event) -> None:
        event.stop()
        eng = self._eng
        # Delegate the state transition to the engine's tested core, then close
        # once it clears the run (unarmed-cancel / done-close) or refresh in
        # place (unarmed-arm keeps the dialog up, now working).
        eng._key_progress(canonical_key(event.key))
        if eng.progress is None:
            self.dismiss(None)
        else:
            self._refresh()


class MsgViewScreen(ModalScreen[None]):
    """Native modal recent-messages viewer (#88 F4) -- the last overlay migrated.

    A read-only peek at a worktree's latest-session conversation tail plus its
    session registry (every session's FULL id + title, so the operator can copy
    an id out for a manual ``copilot --resume <id>``). Like ``ProgressScreen`` it
    is **live**: the payload loads on a daemon thread (``_msgview_worker``) that
    populates the engine-owned ``self.msgview`` dict under a lock, and an
    ``on_mount`` interval repaints while ``loading`` (plus once more on the
    loading -> loaded transition) so the result appears promptly. It mirrors the
    former ``_key_msgview`` exactly (↑/↓ scroll; Esc/q/Tab/Enter close).

    The state + loader stay on the engine because the worker references
    ``self.msgview`` by identity (a late result for a viewer the operator already
    closed / reopened is dropped). This screen is the native shell that renders
    and scrolls that state, dismissing itself once the engine clears it.
    """

    CSS = """
    MsgViewScreen { align: center middle; background: $background 55%; }
    MsgViewScreen > #msgview { width: auto; height: auto; max-height: 90%; }
    """

    def __init__(self, eng) -> None:
        super().__init__()
        self._eng = eng
        self._loading_last = True

    def compose(self) -> ComposeResult:
        yield Static(self._panel(), id="msgview")

    def on_mount(self) -> None:
        self.set_interval(0.1, self._on_tick)

    def _on_tick(self) -> None:
        mv = self._eng.msgview
        if mv is None:
            # A direct engine poke (e.g. a unit test) cleared the viewer out from
            # under us -- close if we're still the top screen.
            if self.app.screen is self:
                self.dismiss(None)
            return
        loading = bool(mv.get("loading"))
        # Repaint while the loader thread is resolving, plus exactly one final
        # repaint on the loading -> loaded transition so the result renders; a
        # settled viewer is static, so we then stop churning (scroll keys
        # repaint synchronously in on_key).
        if loading or self._loading_last:
            self._refresh()
        self._loading_last = loading

    def _refresh(self) -> None:
        if self._eng.msgview is not None:
            self.query_one("#msgview", Static).update(self._panel())

    def _panel(self) -> Panel:
        eng = self._eng
        mv = eng.msgview
        if mv is None:
            # Cleared before this screen finished mounting; render empty and let
            # the interval dismiss us on its next tick.
            return Panel(Text(""), border_style=C_DIM, width=92)
        rec = mv["rec"]
        pw = 88
        title = f" {rec.get('title', '')}"
        meta = (f" {rec.get('id4')} · {rec.get('machine')} · {rec.get('env')}"
                f" · {rec.get('state')}")

        # Assemble the scrollable body, then window it by the scroll offset.
        body: list[Text] = []
        # Sessions section (diagnostic): every session's FULL id + title so the
        # operator can copy an id out (terminal selection) to resume it by hand.
        # The head is marked ``● current``.
        sess = mv.get("sessions") or []
        if sess:
            body.append(Text(" Sessions (select an id to copy):", style=C_HEADER))
            for s in sess:
                sid = str(s.get("id", ""))
                is_head = bool(s.get("is_head"))
                marker = "●" if is_head else "○"
                mark_style = "bold #7ee787" if is_head else C_DIM
                tag = " current" if is_head else ""
                state = str(s.get("state", "") or "")
                if state and state != "active":
                    tag = f" {state}"
                body.append(Text(f" {marker} {sid}{tag}", style=mark_style))
                stitle = str(s.get("name", "") or "").strip()
                title_row = f"     {stitle}" if stitle else "     (untitled)"
                for seg in eng._wrap_text(title_row, pw - 2):
                    body.append(Text(seg, style="white" if stitle else C_FAINT))
            body.append(Text(""))
            body.append(Text(" Recent messages (current session):",
                             style=C_HEADER))

        if mv.get("loading"):
            spin = "⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏"[(eng.frame // 2) % 10]
            body.append(Text(f" {spin} Loading recent messages…", style=C_FAINT))
        elif mv.get("error"):
            body.append(Text(f" ⚠ {mv['error']}", style=C_CAUTION))
        elif not mv.get("messages"):
            body.append(Text(" (no conversation messages in the latest session)",
                             style=C_FAINT))
        else:
            for m in mv["messages"]:
                is_user = m.get("role") == "user"
                who = "you" if is_user else "agent"
                who_style = "bold #4aa3ff" if is_user else "bold #7ee787"
                body.append(Text(f" ▍ {who}", style=who_style))
                for seg in eng._wrap_text(m.get("text", ""), pw - 5):
                    body.append(Text("   " + seg, style="white"))
                body.append(Text(""))

        avail = 18
        total = len(body)
        max_scroll = max(0, total - avail)
        scroll = min(mv.get("scroll", 0), max_scroll)
        mv["scroll"] = scroll
        window = body[scroll:scroll + avail]

        out = Text()
        out.append(title + "\n", style=C_HEADER)
        out.append(meta + "\n\n", style=C_DIM)
        for ln in window:
            out.append_text(ln)
            out.append("\n")
        if total > avail:
            more = total - avail - scroll
            out.append("   … %d more line(s) below" % more if more > 0
                       else "   (end)", style=C_DIM)
            out.append("\n")
        out.append("\n")
        sid = mv.get("session_id") or ""
        foot = " Esc close · ↑/↓ scroll"
        if sid:
            # Full id (not truncated) so terminal selection copies a usable
            # `copilot --resume <id>` argument.
            foot = f" current session {sid} ·" + foot
        out.append(foot, style=C_FAINT)
        return Panel(out, title="Recent messages", border_style=C_BAND, width=92)

    def on_key(self, event) -> None:
        event.stop()
        eng = self._eng
        # Delegate the scroll/close transition to the engine's tested core, then
        # close once it clears the viewer or repaint the new scroll position.
        eng._key_msgview(canonical_key(event.key))
        if eng.msgview is None:
            self.dismiss(None)
        else:
            self._refresh()


def _normalize_form_fields(raw: object) -> list[dict]:
    """Normalize a request-input spec into a clean field list for the form.

    Accepts the ``[{name, type, options?, allow_other?}]`` shape
    ``steering.parse_request_input`` produces (surfaced on a task's
    ``card.request_input``). Drops non-dict / un-named entries, defaults an
    unknown/absent type to ``text``, keeps only a non-empty ``options`` list for
    a choice/multichoice (an empty one degrades to a free-text field), and
    carries ``allow_other`` (the "Other…" affordance). Never raises -- a
    malformed spec degrades to a shorter (or empty) form, so the modal always
    renders."""
    if not isinstance(raw, list):
        return []
    valid_types = {"text", "textarea", "choice", "multichoice"}
    choice_types = {"choice", "multichoice"}
    out: list[dict] = []
    for item in raw:
        if not isinstance(item, dict):
            continue
        name = item.get("name")
        if not isinstance(name, str) or not name.strip():
            continue
        ftype = item.get("type")
        ftype = ftype if isinstance(ftype, str) and ftype in valid_types else "text"
        field: dict = {"name": name.strip(), "type": ftype}
        if ftype in choice_types:
            opts = item.get("options")
            options = [str(o) for o in opts if str(o).strip()] if isinstance(opts, list) else []
            if not options:
                # A choice with no options can't be answered -- treat as text.
                field["type"] = "text"
            else:
                field["options"] = options
                if item.get("allow_other"):
                    field["allow_other"] = True
        out.append(field)
    return out


class PivotCardScreen(ModalScreen[None]):
    """Read-only scrollable card-detail modal (A5 -- the DISPATCH pivot 'card').

    Renders the card a blocked worker posted -- its title, one-line status, an
    optional link to the rich artifact, and a scrollable body -- so the operator
    can read the full brief before steering. Purely informational: no field
    entry, no subprocess. Esc/q/Enter close; ↑/↓/PgUp/PgDn scroll the body (the
    native ``VerticalScroll`` owns scrolling once focused)."""

    CSS = """
    PivotCardScreen { align: center middle; background: $background 55%; }
    PivotCardScreen > #card-frame {
        width: 92; height: auto; max-height: 90%;
        border: round #ffaf00; background: $surface; padding: 0 1;
    }
    PivotCardScreen #card-scroll { height: auto; max-height: 24; }
    PivotCardScreen #card-foot { color: grey; height: auto; padding: 1 0 0 0; }
    """
    BINDINGS = [
        Binding("escape", "close", show=False),
        Binding("q", "close", show=False),
        Binding("enter", "close", show=False),
    ]

    def __init__(self, row_title: str, card: dict) -> None:
        super().__init__()
        self._row_title = row_title
        self._card = card or {}

    def compose(self) -> ComposeResult:
        with Vertical(id="card-frame"):
            with VerticalScroll(id="card-scroll"):
                yield Static(self._body(), id="card-body")
            yield Static("↑/↓ scroll · Esc close", id="card-foot")

    def on_mount(self) -> None:
        self.query_one("#card-frame", Vertical).border_title = "Card"
        self.query_one("#card-scroll", VerticalScroll).focus()

    def _body(self) -> Text:
        card = self._card
        t = Text()
        title = card.get("title") or self._row_title
        if title:
            t.append(f"{title}\n", style=C_HEADER)
        status = card.get("status")
        if status:
            t.append(f"{status}\n", style="white")
        link = card.get("link")
        if link:
            t.append(f"{link}\n", style="#4aa3ff underline")
        body = card.get("body")
        if title or status or link:
            t.append("\n")
        if body:
            t.append(str(body), style="white")
        elif not (title or status or link):
            t.append("(empty card)", style=C_FAINT)
        return t

    def action_close(self) -> None:
        self.dismiss(None)


#: Env override for the steer-draft directory (tests / operator escape hatch).
_STEER_DRAFTS_ENV = "AGENT_WORKTREES_STEER_DRAFTS"
#: Internal sentinels for the "Other…" affordance (never a real option value).
_OTHER_SENTINEL = "\x00other"
_OTHER_LABEL = "Other…"


def _steer_drafts_dir() -> Path:
    """Directory holding saved steer drafts (partial answers). Overridable via
    ``AGENT_WORKTREES_STEER_DRAFTS``; defaults to ``~/.agent-worktrees/steer-drafts``."""
    override = os.environ.get(_STEER_DRAFTS_ENV)
    return Path(override) if override else Path.home() / ".agent-worktrees" / "steer-drafts"


def _steer_draft_path(task_id: str) -> Path | None:
    """Per-task draft file path (``<drafts>/<sanitized-task-id>.json``), or
    ``None`` when the task id has no filesystem-safe characters."""
    tid = "".join(c for c in str(task_id) if c.isalnum() or c in "-_")
    return _steer_drafts_dir() / f"{tid}.json" if tid else None


#: Matches an http(s) URL in card prose (stops at whitespace / closing brackets).
_URL_RE = re.compile(r"https?://[^\s<>\)\]]+")


def _linkify(text: str, style: str) -> Text:
    """Render ``text`` as Rich ``Text`` with any http(s) URL turned into a
    clickable OSC-8 hyperlink (underlined), so the operator can click it -- or
    hover to reveal the full URL -- instead of reading a bare string. Non-URL
    spans keep the base ``style``. (Click-through depends on the terminal; over
    SSH/mux it degrades to a hover/inspectable link, which is why the picker is
    usually driven locally.)"""
    base = Style.parse(style) if style else Style()
    t = Text()
    pos = 0
    for m in _URL_RE.finditer(text):
        if m.start() > pos:
            t.append(text[pos:m.start()], style=base)
        url = m.group(0)
        # Don't swallow trailing sentence punctuation into the link target
        # (a URL that ends a sentence, e.g. "…see https://x/y." ).
        trail = ""
        while url and url[-1] in ".,;:!?)]}'\"":
            trail = url[-1] + trail
            url = url[:-1]
        if url:
            t.append(url, style=base + Style(link=url, underline=True))
        if trail:
            t.append(trail, style=base)
        pos = m.end()
    if pos < len(text):
        t.append(text[pos:], style=base)
    return t


class _AutoExpandTextArea(TextArea):
    """A docked steer input that grows with its content and follows the
    Copilot-CLI editing mechanic.

    * Height is CSS ``auto`` (bounded by ``min_height``/``max_height``), so the
      box grows one row per line of content and caps out (then scrolls) -- no
      manual line math, no off-by-one.
    * **Enter accepts + advances** focus to the next field (or the button row on
      the last one); **Shift+Enter inserts a newline** (grow the box) -- matching
      the operator's Copilot-CLI muscle memory. Windows Terminal emits ``ESC``+
      ``CR`` for Shift+Enter (not the Kitty ``\\x1b[13;2u`` form), which Textual
      would otherwise collapse to a plain ``enter``; ``_register_shift_enter_key``
      (module scope) restores the distinct ``shift+enter`` key. **Alt+Enter** and
      **Ctrl+J** remain wired as newline fallbacks for terminals that report those
      distinctly instead.
    * **Ctrl+Left / Ctrl+Right switch tabs** even while the box has focus: a
      ``TextArea`` natively binds these to cursor word-movement, which would
      otherwise swallow them before the screen's tab bindings fire, so we forward
      them to the screen's ``next_tab`` / ``prev_tab`` actions here."""

    def __init__(self, *args, min_height: int = 3, max_height: int = 12, **kw) -> None:
        super().__init__(*args, **kw)
        self._min_height = min_height
        self._max_height = max_height

    def on_mount(self) -> None:
        self.styles.height = "auto"
        self.styles.min_height = self._min_height
        self.styles.max_height = self._max_height

    def autosize(self) -> None:
        # Back-compat no-op: CSS ``height: auto`` now does the growing.
        return

    def on_key(self, event) -> None:
        key = event.key
        if key in ("ctrl+left", "ctrl+right"):
            # Tab-switching wins over the TextArea's native word-movement while a
            # box is focused (operator request): the TextArea would otherwise
            # consume these as cursor_word_left/right and the screen's ctrl+←/→
            # tab bindings would never fire. Forward to the screen's tab actions.
            event.prevent_default()
            event.stop()
            action = "action_next_tab" if key == "ctrl+right" else "action_prev_tab"
            fn = getattr(self.screen, action, None)
            if callable(fn):
                fn()
        elif key in ("shift+enter", "alt+enter", "ctrl+j"):
            # Insert a newline (grow the box). ``shift+enter`` is the primary
            # mechanic, but a mux (psmux) or a terminal without the enhanced
            # keyboard protocol collapses it to a bare ``enter`` -- so ``alt+enter``
            # and ``ctrl+j`` (LF, distinct from CR/enter in Textual) are wired as
            # always-distinguishable, mux-safe fallbacks.
            event.prevent_default()
            event.stop()
            self.insert("\n")
        elif key == "enter":
            # Accept + advance (Copilot-CLI mechanic) -- do NOT insert a newline.
            # Using the public on_key handler (not the private _on_key) keeps this
            # robust across Textual upgrades.
            event.prevent_default()
            event.stop()
            adv = getattr(self.screen, "_advance_focus", None)
            if callable(adv):
                adv(self)


class _SteerRadioSet(RadioSet):
    """A single-select that keeps ``Space`` = toggle-and-stay but makes ``Enter``
    = toggle-**and-advance** (the steer form's keyboard flow). Enter that lands on
    "Other…" focuses the revealed free-text box instead of advancing."""

    BINDINGS = [
        Binding("enter", "toggle_and_advance", show=False),
        Binding("space", "toggle_button", show=False),
    ]

    def action_toggle_and_advance(self) -> None:
        self.action_toggle_button()
        # The selection settles asynchronously (pressed_index updates after the
        # button's Changed message), so defer the advance until after refresh.
        self.call_after_refresh(self._notify_advance)

    def _notify_advance(self) -> None:
        adv = getattr(self.screen, "_advance_after_choice", None)
        if callable(adv):
            adv(self)


class _SteerSelectionList(SelectionList):
    """A multi-select where ``Space`` toggles-and-stays (pick several) and
    ``Enter`` toggles the highlighted option **and advances**. Enter that toggles
    "Other…" on focuses the revealed free-text box."""

    BINDINGS = [
        Binding("enter", "toggle_and_advance", show=False),
    ]

    def action_toggle_and_advance(self) -> None:
        self.action_select()
        self.call_after_refresh(self._notify_advance)

    def _notify_advance(self) -> None:
        adv = getattr(self.screen, "_advance_after_choice", None)
        if callable(adv):
            adv(self)


class SteerButtonRow(Widget):
    """A single-line row of Picker-style buttons (Confirm/Save/Cancel), focusable
    as one region: ←/→ move the cursor, Enter/Space press. Matches the picker's
    ``C_BTN``/``C_BTN_SEL`` button aesthetic rather than the heavier Textual
    ``Button`` widget. Calls ``on_press(key)`` when a button is pressed."""

    can_focus = True

    def __init__(self, buttons: list[tuple[str, str]], on_press, **kw) -> None:
        super().__init__(**kw)
        self._buttons = list(buttons)  # [(key, label), ...]
        self._on_press = on_press
        self._idx = 0

    def render(self):
        t = Text()
        for i, (_key, label) in enumerate(self._buttons):
            if i:
                t.append("  ")
            focused = self.has_focus and i == self._idx
            t.append(f" {label} ", style=C_BTN_SEL if focused else C_BTN)
        return t

    def on_key(self, event) -> None:
        if event.key == "left":
            self._idx = (self._idx - 1) % len(self._buttons)
            self.refresh()
            event.stop()
        elif event.key == "right":
            self._idx = (self._idx + 1) % len(self._buttons)
            self.refresh()
            event.stop()
        elif event.key in ("enter", "space"):
            self._on_press(self._buttons[self._idx][0])
            event.stop()

    def press(self, key: str) -> None:
        """Programmatic press (used by tests / click)."""
        self._on_press(key)

    def on_focus(self) -> None:
        self.refresh()

    def on_blur(self) -> None:
        self.refresh()

    def on_click(self, event) -> None:
        event.stop()
        self.focus()
        # Hit-test the click against each button's rendered span so a mouse
        # press acts on the button under the cursor (not merely the focused one).
        x = int(getattr(event, "x", 0))
        pos = 0
        for i, (_key, label) in enumerate(self._buttons):
            if i:
                pos += 2  # the "  " separator between buttons
            width = len(label) + 2  # the " label " span
            if pos <= x < pos + width:
                self._idx = i
                self.refresh()
                self._on_press(self._buttons[i][0])
                return
            pos += width


class PivotFormScreen(ModalScreen[dict]):
    """Docked card + tabbed elicitation modal (the DISPATCH-pivot 'Steer' surface).

    A Copilot-CLI-style layout: the card's prose fills the top (a scrollable
    ``#steer-card`` that takes all the height the docked input doesn't need), and
    a **docked** elicitation section sits at the bottom -- one **tab per question**
    (``TabbedContent``; a single question skips the tab bar), each a single-select
    (``RadioSet``), multi-select (``SelectionList``), or free-form
    auto-expanding text box (up to 10 lines). A choice/multichoice that declares
    ``allow_other`` gains an **"Other…"** entry that reveals a free-text box.
    Beneath sits a single-line Picker-style button row: **Confirm** (submit),
    **Save** (persist a draft and close -- resume later, survives a kill/Escape),
    **Cancel** (discard).

    On **Confirm** the collected ``{name: value}`` answer is returned via
    ``dismiss(dict)`` (a multichoice value is a list); ``dismiss(None)`` on
    Save/Cancel/Escape. The caller substitutes those values into the action's
    ``run`` template (the steer transport) -- this screen never runs a command
    and never carries a verdict; it only gathers the operator's answer.

    Esc saves a draft and closes (nothing is lost); Ctrl+S saves explicitly."""

    CSS = """
    PivotFormScreen { align: center middle; background: $background 55%; }
    PivotFormScreen > #steer-frame {
        width: 90%; height: 90%;
        border: round #ffaf00; background: $surface; padding: 0 1;
    }
    PivotFormScreen #steer-card { height: 1fr; }
    PivotFormScreen #steer-dock { height: auto; max-height: 65%; padding: 0; }
    PivotFormScreen .steer-qlabel { color: #ffaf00; height: auto; padding: 1 0 0 0; }
    PivotFormScreen .steer-note { color: grey; height: auto; padding: 1 0 0 0; }
    PivotFormScreen TextArea { border: round grey; background: $surface; }
    PivotFormScreen Input { border: round grey; background: $surface; }
    PivotFormScreen RadioSet, PivotFormScreen SelectionList {
        border: none; background: $surface; height: auto;
    }
    PivotFormScreen #steer-foot { color: grey; height: auto; padding: 1 0 0 0; }
    PivotFormScreen #steer-buttons { height: 1; padding: 0; }
    """
    BINDINGS = [
        Binding("escape", "escape_close", show=False),
        Binding("ctrl+s", "save", show=False),
        Binding("ctrl+right", "next_tab", show=False),
        Binding("ctrl+left", "prev_tab", show=False),
    ]

    def __init__(self, card: dict, fields: list[dict], submit_label: str,
                 task_id: str = "") -> None:
        super().__init__()
        self._card = card or {}
        self._fields = fields or []
        self._submit_label = submit_label or "Steer"
        self._task_id = str(task_id or "")
        # Per-question runtime refs, filled during compose:
        #   {name, type, options, allow_other, primary, other}
        self._q: list[dict] = []

    # ---- compose ------------------------------------------------------------
    def compose(self) -> ComposeResult:
        with Vertical(id="steer-frame"):
            with VerticalScroll(id="steer-card"):
                yield Static(self._card_prose(), id="steer-card-body")
            with Vertical(id="steer-dock"):
                yield from self._compose_questions()
                yield Static(self._foot(), id="steer-foot")
                yield SteerButtonRow(
                    [("confirm", "Confirm"), ("save", "Save"), ("cancel", "Cancel")],
                    self._on_button, id="steer-buttons",
                )

    def _compose_questions(self):
        if not self._fields:
            yield Static("(this card requests no input — Confirm to acknowledge)",
                         classes="steer-note")
            return
        if len(self._fields) == 1:
            yield from self._compose_one(self._fields[0], 0)
            return
        with TabbedContent(id="steer-tabs"):
            for i, f in enumerate(self._fields):
                with TabPane(f["name"], id=f"tab-{i}"):
                    yield from self._compose_one(f, i)

    def _compose_one(self, f: dict, i: int):
        name, ftype = f["name"], f["type"]
        options = list(f.get("options", []))
        allow_other = bool(f.get("allow_other"))
        rec = {"name": name, "type": ftype, "options": options,
               "allow_other": allow_other, "primary": None, "other": None}
        yield Static(self._q_label(f), classes="steer-qlabel")
        if ftype == "choice":
            btns = [RadioButton(o, value=(j == 0)) for j, o in enumerate(options)]
            if allow_other:
                btns.append(RadioButton(_OTHER_LABEL))
            rs = _SteerRadioSet(*btns, id=f"q-{i}")
            rec["primary"] = rs
            yield rs
            if allow_other:
                other = _AutoExpandTextArea(id=f"other-{i}")
                other.display = False
                rec["other"] = other
                yield other
        elif ftype == "multichoice":
            sels = [(o, o) for o in options]
            if allow_other:
                sels.append((_OTHER_LABEL, _OTHER_SENTINEL))
            sl = _SteerSelectionList(*sels, id=f"q-{i}")
            rec["primary"] = sl
            yield sl
            if allow_other:
                other = _AutoExpandTextArea(id=f"other-{i}")
                other.display = False
                rec["other"] = other
                yield other
        else:  # text -> single-line Input; textarea -> free-form auto-expand box
            if ftype == "text":
                w: Widget = Input(id=f"q-{i}")
            else:
                w = _AutoExpandTextArea(id=f"q-{i}")
            rec["primary"] = w
            yield w
        self._q.append(rec)

    # ---- rendering helpers --------------------------------------------------
    def _card_prose(self) -> Text:
        card = self._card
        t = Text()
        title = card.get("title")
        if title:
            t.append(f"{title}\n", style=C_HEADER)
        status = card.get("status")
        if status:
            self._append_linked(t, str(status), "white")
            t.append("\n")
        link = card.get("link")
        if link:
            t.append_text(_linkify(str(link), "#4aa3ff underline"))
            t.append("\n")
        body = card.get("body")
        if title or status or link:
            t.append("\n")
        if body:
            self._append_linked(t, str(body), "white")
        elif not (title or status or link):
            t.append("(no card detail)", style=C_FAINT)
        return t

    @staticmethod
    def _append_linked(t: Text, text: str, style: str) -> None:
        """Append ``text`` to ``t``, rendering any http(s) URLs as clickable
        Rich hyperlinks (OSC-8) so the operator can click them (or hover to see
        the full URL) rather than eyeballing a bare string."""
        t.append_text(_linkify(text, style))

    @staticmethod
    def _q_label(f: dict) -> str:
        hints = {"textarea": "free text", "text": "free text",
                 "choice": "choose one", "multichoice": "choose any"}
        hint = hints.get(f["type"], "")
        if f.get("allow_other"):
            hint += " · Other… for free text"
        return f"{f['name']}" + (f"  ({hint})" if hint else "") + ":"

    def _foot(self) -> str:
        return ("Enter accept+next · Shift+Enter newline · Space toggle · "
                "Ctrl+←/→ tabs · Ctrl+S save · Esc save+close  ·  "
                "Confirm submits (never a vote)")

    # ---- lifecycle ----------------------------------------------------------
    def on_mount(self) -> None:
        self.query_one("#steer-frame", Vertical).border_title = f"Steer — {self._submit_label}"
        # Choice defaults: pre-select the first real option (RadioSet index 0).
        restored = self._load_draft()
        if restored:
            self._restore(restored)
        # Focus the first question's input (or the card scroll when there is none).
        target = self._q[0]["primary"] if self._q else self.query_one("#steer-card", VerticalScroll)
        try:
            target.focus()
        except Exception:
            pass

    # ---- dynamic "Other…" reveal --------------------------------------------
    def _rec_for(self, widget) -> dict | None:
        for rec in self._q:
            if rec["primary"] is widget:
                return rec
        return None

    def _question_index(self, widget) -> int:
        """Index of the question a widget belongs to (its primary OR its Other
        box), or -1."""
        for i, rec in enumerate(self._q):
            if rec["primary"] is widget or rec.get("other") is widget:
                return i
        return -1

    def on_radio_set_changed(self, event) -> None:
        # Reveal/hide the "Other…" free-text box for this question (display only;
        # focus is handled on Enter by _advance_after_choice so Space stays put).
        rec = self._rec_for(event.radio_set)
        if not rec or not rec.get("other"):
            return
        other_idx = len(rec["options"])  # "Other…" is appended after the options
        rec["other"].display = getattr(event, "index", -1) == other_idx

    def on_selection_list_selected_changed(self, event) -> None:
        rec = self._rec_for(event.selection_list)
        if not rec or not rec.get("other"):
            return
        selected = list(getattr(event.selection_list, "selected", []) or [])
        rec["other"].display = _OTHER_SENTINEL in selected

    # ---- keyboard flow: advance + tab cycling -------------------------------
    def _activate_tab(self, i: int) -> None:
        try:
            self.query_one("#steer-tabs", TabbedContent).active = f"tab-{i}"
        except Exception:
            pass

    def _advance_to_next_question(self, i: int) -> None:
        """Focus the next question's input (switching tabs), or the button row
        (Confirm) when there is none left."""
        if 0 <= i and i + 1 < len(self._q):
            self._activate_tab(i + 1)
            try:
                self._q[i + 1]["primary"].focus()
            except Exception:
                pass
        else:
            try:
                br = self.query_one(SteerButtonRow)
                br._idx = 0  # highlight Confirm
                br.focus()
            except Exception:
                pass

    def _advance_focus(self, widget) -> None:
        """Enter from a free-form / Other box: advance to the next question."""
        self._advance_to_next_question(self._question_index(widget))

    def _advance_after_choice(self, widget) -> None:
        """Enter from a choice/multichoice: if the toggle activated the "Other…"
        box, focus it (keep typing); otherwise advance to the next question."""
        rec = self._rec_for(widget)
        if rec and rec.get("other") is not None:
            if rec["type"] == "choice":
                other_active = getattr(widget, "pressed_index", -1) == len(rec["options"])
            else:
                other_active = _OTHER_SENTINEL in (getattr(widget, "selected", []) or [])
            if other_active:
                rec["other"].display = True
                try:
                    rec["other"].focus()
                except Exception:
                    pass
                return
        self._advance_to_next_question(self._question_index(widget))

    def _cycle_tab(self, direction: int) -> None:
        if len(self._q) <= 1:
            return
        try:
            tabs = self.query_one("#steer-tabs", TabbedContent)
        except Exception:
            return
        try:
            cur = int(str(tabs.active).split("-")[1])
        except Exception:
            cur = 0
        i = (cur + direction) % len(self._q)
        tabs.active = f"tab-{i}"
        try:
            self._q[i]["primary"].focus()
        except Exception:
            pass

    def action_next_tab(self) -> None:
        self._cycle_tab(1)

    def action_prev_tab(self) -> None:
        self._cycle_tab(-1)

    # ---- collect / draft ----------------------------------------------------
    def _collect(self) -> dict:
        values: dict = {}
        for rec in self._q:
            name, ftype = rec["name"], rec["type"]
            options, allow_other = rec["options"], rec["allow_other"]
            prim, other = rec["primary"], rec["other"]
            if ftype == "text":
                values[name] = prim.value
            elif ftype == "textarea":
                values[name] = prim.text
            elif ftype == "choice":
                idx = getattr(prim, "pressed_index", -1)
                if allow_other and idx == len(options):
                    values[name] = other.text if other else ""
                elif 0 <= idx < len(options):
                    values[name] = options[idx]
                else:
                    values[name] = ""
            elif ftype == "multichoice":
                selected = list(getattr(prim, "selected", []) or [])
                members = [s for s in selected if s != _OTHER_SENTINEL]
                if (allow_other and _OTHER_SENTINEL in selected
                        and other and other.text.strip()):
                    members.append(other.text.strip())
                values[name] = members
        return values

    def _restore(self, values: dict) -> None:
        for rec in self._q:
            name, ftype = rec["name"], rec["type"]
            options, allow_other = rec["options"], rec["allow_other"]
            prim, other = rec["primary"], rec["other"]
            if name not in values:
                continue
            v = values[name]
            if ftype == "text":
                prim.value = str(v)
            elif ftype == "textarea":
                prim.text = str(v)
                prim.autosize()
            elif ftype == "choice":
                btns = list(prim.query(RadioButton))
                if str(v) in options:
                    target = options.index(str(v))
                elif allow_other and other is not None:
                    target = len(options)  # "Other…"
                    other.text = str(v)
                    other.display = True
                    other.autosize()
                else:
                    target = -1
                for j, b in enumerate(btns):
                    b.value = (j == target)
            elif ftype == "multichoice":
                members = v if isinstance(v, list) else [v]
                extras = []
                for m in members:
                    if str(m) in options:
                        try:
                            prim.select(prim.get_option_at_index(options.index(str(m))))
                        except Exception:
                            pass
                    else:
                        extras.append(str(m))
                if allow_other and other is not None and extras:
                    other.text = ", ".join(extras)
                    other.display = True
                    other.autosize()
                    try:
                        prim.select(prim.get_option_at_index(len(options)))
                    except Exception:
                        pass

    def _write_draft(self) -> None:
        path = _steer_draft_path(self._task_id)
        if not path:
            return
        try:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(
                json.dumps({"task_id": self._task_id, "values": self._collect()}),
                encoding="utf-8",
            )
        except OSError:
            pass

    def _load_draft(self) -> dict:
        path = _steer_draft_path(self._task_id)
        try:
            if path and path.exists():
                data = json.loads(path.read_text(encoding="utf-8"))
                if isinstance(data, dict) and isinstance(data.get("values"), dict):
                    return data["values"]
        except (OSError, ValueError):
            pass
        return {}

    def _delete_draft(self) -> None:
        path = _steer_draft_path(self._task_id)
        try:
            if path and path.exists():
                path.unlink()
        except OSError:
            pass

    # ---- actions ------------------------------------------------------------
    def _on_button(self, key: str) -> None:
        if key == "confirm":
            self._confirm()
        elif key == "save":
            self.action_save()
        else:
            self._cancel()

    def _confirm(self) -> None:
        values = self._collect()
        self._delete_draft()
        self.dismiss(values)

    def _cancel(self) -> None:
        self._delete_draft()
        self.dismiss(None)

    def action_save(self) -> None:
        self._write_draft()
        self.dismiss(None)

    def action_escape_close(self) -> None:
        # Preserve work: Esc saves a draft (so nothing is lost if you step away)
        # then closes without submitting.
        self._write_draft()
        self.dismiss(None)


class MaintenanceView:
    """Encapsulated Maintenance-pivot body sub-view (#88 F5, slice 5a).

    A cohesive sub-view carved out of the picker's monolithic
    ``PickerScreen.build_body`` into its own component, mirroring
    :class:`ProfilesView` and per the incremental componentization strategy
    (#88 F5): peel cohesive sub-views off the God-object one at a time, under a
    moratorium on new full-screen-at-once renders, until the shared
    ``sel=(zone,index)`` focus model shrinks to just the chrome.

    This component owns the Maintenance pivot's **rendering** (slice 5a -- the
    body entry ``build`` plus the four row helpers ``_selectall_row`` /
    ``_header`` / ``_group_row`` / ``_row``) and now its **selection model**
    (slice 5b): the state ``maint_sel`` plus the grouping / multi-select
    behaviour (``maint_groups`` / ``maint_records`` / ``_maint_ids`` /
    ``_toggle_maint`` / ``_toggle_maint_all`` / ``_toggle_group``).
    ``PickerScreen`` exposes a ``maint_sel`` ``@property`` shim and one-line
    delegating methods so its call sites (``_open_maint_menu``, ``_dispatch_key``,
    ``_activate``, the executor poll) and the test suite address them unchanged.
    The component reads engine-owned shared infrastructure via ``self._eng``: the
    scoped ``cleanup_rows`` data layer (used by non-Maintenance code too), the
    ``_checkbox`` glyph helper (shared with the Worktrees gutter), the status
    line (``debug``), the tab bar, and the button row. A later slice makes this a
    focusable Textual widget.
    """

    def __init__(self, eng) -> None:
        self._eng = eng
        self.maint_sel = ListSelection()   # Maintenance multi-select (#1345)

    # ---- Maintenance grouping + multi-select (#1345; moved here #88 F5 5b) ---
    def maint_groups(self):
        """Maintenance rows grouped by display state, in MAINT_GROUP_ORDER."""
        rows = self._eng.cleanup_rows()
        by = {}
        for r in rows:
            by.setdefault(r.get("state", "?"), []).append(r)
        groups = [(st, by.pop(st)) for st in MAINT_GROUP_ORDER if st in by]
        groups.extend(by.items())   # any unlisted states, first-seen order
        return groups

    def maint_records(self):
        """Flat Maintenance row list in grouped display order (indexes the
        ("C", i) stops -- must match build's ordering)."""
        out = []
        for _st, rows in self.maint_groups():
            out.extend(rows)
        return out

    def _maint_ids(self):
        return {r["id4"] for r in self.maint_records()}

    def _toggle_maint(self, i):
        recs = self.maint_records()
        if 0 <= i < len(recs):
            wid = recs[i]["id4"]
            now_on = self.maint_sel.toggle(wid)
            self._eng.debug = (f"{'selected' if now_on else 'deselected'}"
                               f" {wid} · {len(self.maint_sel)} selected")

    def _toggle_maint_all(self):
        ids = self._maint_ids()
        if self.maint_sel.toggle_all(ids):
            self._eng.debug = f"selected all · {len(ids)}"
        else:
            self._eng.debug = "cleared selection"

    def _toggle_group(self, gi):
        groups = self.maint_groups()
        if 0 <= gi < len(groups):
            st, rows = groups[gi]
            ids = {r["id4"] for r in rows}
            if self.maint_sel.toggle_all(ids):
                self._eng.debug = f"selected {st} · {len(ids)}"
            else:
                self._eng.debug = f"deselected {st} · {len(ids)}"

    # ---- Maintenance row rendering (#1345; moved here in #88 F5 slice 5a) ----
    def _selectall_row(self, width, focus):
        eng = self._eng
        ids = self._maint_ids()
        all_on = self.maint_sel.all_selected(ids)
        glyph, gc = eng._checkbox(all_on)
        nsel = self.maint_sel.count(ids)
        t = Text("  ")
        t.append(glyph, style=gc)
        t.append("  ")
        t.append("Select all", style=C_LABEL)
        t.append(f"   ({nsel}/{len(ids)} selected)", style=C_DIM)
        t.append(" " * max(0, width - t.cell_len))
        if focus:
            t.stylize(C_SEL)
        return t

    def _header(self, ccols, width):
        # 4-cell checkbox gutter, then the normal column header.
        t = Text("    ")
        body = header_text(ccols, max(1, width - 4), indent=0)
        t.append_text(body)
        if t.cell_len < width:
            t.append(" " * (width - t.cell_len))
        return t

    def _group_row(self, state, rows, width, focus):
        eng = self._eng
        ids = {r["id4"] for r in rows}
        all_on = self.maint_sel.all_selected(ids)
        glyph, gc = eng._checkbox(all_on)
        t = Text("  ")
        t.append(glyph, style=gc)
        t.append("  ")
        head = Text(f"── {state} ", style=C_SECTION)
        head.append(f"({len(rows)}) ", style=C_DIM)
        t.append_text(head)
        t.append("─" * max(0, width - t.cell_len - 1), style=C_DIM)
        t.append(" ")
        if focus:
            t.stylize(C_SEL)
        return t

    def _row(self, d, ccols, width, selected, checked, pulse):
        glyph, gc = self._eng._checkbox(checked)
        t = Text(" ")
        t.append(glyph, style=gc)
        t.append("  ")
        body = row_text(d, ccols, max(1, width - 4), selected=False, pulse=pulse)
        t.append_text(body)
        if t.cell_len < width:
            t.append(" " * (width - t.cell_len))
        if selected:
            t.stylize(C_SEL)
        return t

    def build(self, add, width, sel):
        """Emit the Maintenance pivot body into ``add`` (the ``build_body`` VRow
        sink). Mirrors the former inline ``build_body`` maintenance branch
        exactly; group sections are opened via ``add(..., new_section=...)`` so
        this component never touches the closure's ``cur_section``/``vrows``.

        Split into ``build_chrome`` (the machine-scope + Cleanup/Sync button
        region) and ``build_data`` (the select-all row, column header, and the
        scrolling group/row list) so the concerns render into separate widgets;
        ``build`` emits both in order, byte-identically (#88 NF3)."""
        self.build_chrome(add, width, sel)
        self.build_data(add, width, sel)

    def build_chrome(self, add, width, sel):
        eng = self._eng
        btn_focus = sel == ("BTN", 0)
        add(eng.tab_bar(width, sel == ("M", 0)))
        recs = self.maint_records()
        total = sum(_size_mb(w) for w in recs)
        nsel = self.maint_sel.count(self._maint_ids())
        reclaim = sum(_size_mb(w) for w in recs if w["id4"] in self.maint_sel)
        suffix = f"{len(recs)} candidates · ~{total} MiB"
        if nsel:
            suffix += f"  ·  {nsel} selected · ~{reclaim} MiB"
        add(Text(""))
        add(eng.two_button_row(
            "Cleanup…", "Sync…", btn_focus, eng.btn_idx, suffix, width),
            stop=("BTN", 0))
        add(Text(""))

    def build_data(self, add, width, sel):
        eng = self._eng
        groups = self.maint_groups()
        # Checkbox column reserves 4 cells in front of the data columns.
        ccols = fit(CLEAN_SPECS, width - 1 - 4, "title", 12)
        add(self._selectall_row(width, sel == ("SA", 0)),
            stop=("SA", 0))
        add(self._header(ccols, width), kind="colhdr")
        li = 0
        for gi, (state, rows) in enumerate(groups):
            add(self._group_row(state, rows, width, sel == ("GH", gi)),
                stop=("GH", gi), kind="section",
                new_section=f"{state} ({len(rows)})")
            for rec in rows:
                d = dict(rec, mib=f"{_size_mb(rec)}M")
                checked = rec["id4"] in self.maint_sel
                add(self._row(d, ccols, width, sel == ("C", li),
                              checked, eng.pulse),
                    stop=("C", li), data=rec)
                li += 1


class WorktreesView:
    """Encapsulated Worktrees-list body sub-view (#88 F5, slice 7).

    The picker's **primary** body -- the machine's worktree list, grouped into
    Active / Recent / Completed / Unowned sections, with the multi-select
    checkbox gutter, per-row disposition/preview dimming, focus + selection
    highlight layering, and the decorative live worktree-status-core pulse
    sub-lines. It is the largest and most-coupled body, so it is carved out
    **last**, once the componentization pattern was proven three times over
    (Profiles / Maintenance / Tasks).

    This slice moves the **rendering** -- the whole Worktrees branch of
    ``build_body`` into ``build``. Because the list's multi-select **state**
    (``wt_sel`` / ``wt_anchor``) and its range/toggle behaviour thread deeply
    through the shared key-dispatch + focus machinery (``_dispatch_key``,
    ``_reconcile_wt_sel``, range-select, focus tracking) -- which is exactly the
    ``sel``/``stops`` chrome the *final* native-focus step addresses -- that
    state stays on ``PickerScreen`` and is read here via ``self._eng``, along
    with the list data (``current_list`` / ``list_records``), the multi-select
    predicates (``_wt_multiselect_active`` / ``_cleanable``), the shared
    ``_checkbox`` glyph, and the chrome rows (``tab_bar`` / ``new_worktree_row``
    / ``active_button``). A later slice makes this a focusable Textual widget.
    """

    def __init__(self, eng) -> None:
        self._eng = eng

    def build(self, add, width, sel):
        """Emit the Worktrees-list body into ``add`` (the ``build_body`` VRow
        sink). Mirrors the former inline ``build_body`` worktrees branch exactly;
        group sections are opened via ``add(..., new_section=...)`` so this
        component never touches the closure's ``cur_section``/``vrows``.

        Split into ``build_chrome`` (the machine-scope + New/Clean/Sync button
        region -- the fixed chrome the NF3 focusable-region slices target) and
        ``build_data`` (the column header + the scrolling section/row list), so
        the two concerns can render into separate widgets; ``build`` emits both
        in order, byte-identically (#88 NF3)."""
        self.build_chrome(add, width, sel)
        self.build_data(add, width, sel)

    def build_chrome(self, add, width, sel):
        eng = self._eng
        btn_focus = sel == ("BTN", 0)
        add(eng.tab_bar(width, sel == ("M", 0)))
        add(Text(""))  # breathing room above the buttons
        add(eng.new_worktree_row(width, btn_focus, eng.btn_idx),
            stop=("BTN", 0))
        add(Text(""))  # breathing room below the buttons

    def build_data(self, add, width, sel):
        eng = self._eng
        btn_focus = sel == ("BTN", 0)
        cols, sections = eng.current_list()
        # The checkbox gutter's two left cells (box + margin) are ALWAYS
        # reserved so the table never shifts. Since #88 NF5-5 (mouse support in
        # the native list) the box GLYPH is also always shown per row, so
        # multi-select is discoverable/clickable at rest (not only once a set is
        # being held).
        lcols = fit(cols, width - 2, "title", 14)
        add(header_text(lcols, width, indent=2), kind="colhdr")
        # Preview which worktrees an action targets, directly on the list:
        # when the Clean/Sync button is merely focused, dim the rows that
        # action can't touch. (The old live-filter preview driven by an open
        # Clean/Sync dialog was retired with #88 F4 -- that dialog is now a
        # centered ScopeDlgScreen carrying its own impact list.)
        preview = None
        preview_ids = None
        if btn_focus:
            ab = eng.active_button()
            preview = {"K": "clean", "SY": "sync"}.get(ab)
        li = 0
        for label, rows in sections:
            sec = Text(f"  ── {label} ", style=C_SECTION)
            sec.append("─" * (width - sec.cell_len), style=C_DIM)
            add(sec, kind="section", new_section=label)
            if not rows:
                add(Text("    (none)", style=C_DIM))
            for rec in rows:
                add(self._row_text(rec, li, sel, width, lcols,
                                   preview, preview_ids),
                    stop=("L", li), data=rec)
                # worktree-status-core live pulse (#2917): a dim, expiring
                # sub-line carrying the agent's current intent, derived from
                # the assistant.intent stream. Decorative (no stop) so it is
                # never focusable and never affects selection. copilot-extensions
                # #228: the line no longer expires -- ``live_pulse`` grades its
                # colour/glyph: 'awaiting' renders an amber ⏳ ("this needs me"),
                # 'fresh' a dim ⟳, 'stale' a dimmer ⟳; the last intent lingers
                # (greyed) so a dormant worktree still shows what it was doing.
                _pulse = rec.get("live_pulse")
                _intent = (rec.get("live_intent") or "").strip()
                if _pulse and _intent:
                    if _pulse == "awaiting":
                        _pstyle, _pglyph = C_PULSE_AWAIT, "⏳ "
                    else:
                        _pstyle = C_DIM if _pulse == "fresh" else "grey30"
                        _pglyph = "⟳ "
                    pline = Text("      ", style=_pstyle)
                    pline.append(_pglyph, style=_pstyle)
                    pline.append(_clip(_intent, max(1, width - 9), "l"),
                                 style=_pstyle)
                    add(pline)
                li += 1

    def _row_text(self, rec, li, sel, width, lcols, preview, preview_ids):
        """Render one worktree row's fully-styled Text. Extracted from
        ``build_data`` so the native list's incremental checkbox repaint (#171)
        renders a single row through the SAME path as a full rebuild -- keeping
        the two byte-identical. ``sel`` drives the focus/selection highlight; the
        native list passes a sentinel (focus is the amber cursor, not baked in)."""
        eng = self._eng
        focused = sel == ("L", li)
        is_sel = rec["id4"] in eng.wt_sel
        # Always show the per-row checkbox glyph (#88 NF5-5): with mouse support
        # the box is a discoverable, clickable multi-select affordance, so it
        # renders at rest rather than only when a set is already held.
        box = eng._checkbox(is_sel)
        txt = row_text(rec, lcols, width, False, pulse=eng.pulse, mark=box)
        if rec.get("hidden") and not focused:
            # Revealed bridge/system worktree -> dim it (#1422).
            txt.stylize("grey42")
        elif (preview_ids is not None and rec["id4"] not in preview_ids
              and not focused):
            txt.stylize("grey35")   # outside the net set
        elif preview and not focused and not (
            eng._cleanable(rec) if preview == "clean"
            else rec.get("ff_eligible")
        ):
            txt.stylize("grey35")   # out of this action's scope
        # Focus / selection highlight, layered last so it reads as one state
        # (#2258 follow-up): green invert = focused AND selected, plain invert =
        # focused only, grey background = selected but the cursor has moved off.
        if focused and is_sel:
            txt.stylize(C_SEL_ON)
        elif focused:
            txt.stylize(C_SEL)
        elif is_sel:
            txt.stylize(C_SEL_BG)
        return txt


class TasksView:
    """Encapsulated registered-pivot (Tasks) body sub-view (#88 F5, slice 6).

    A cohesive sub-view carved out of the picker's monolithic
    ``PickerScreen.build_body`` into its own component, mirroring
    :class:`ProfilesView` / :class:`MaintenanceView` and per the incremental
    componentization strategy (#88 F5).

    This slice moves the registered pivot's **rendering** -- the body entry
    (``build``) plus the two row helpers (``_status_row`` for the load/count/empty
    header line, ``_row`` for one task entry). The registered pivot is
    **read-only** (its task list is background-loaded by a
    ``RegisteredPivotRuntime``), so there is no editable state to move: the data
    helpers (``_task_state`` / ``_task_rows`` / ``_task_groups``) and the
    pivot-scoping context (``_reg_pivot`` / ``_pivot_machine`` /
    ``_pivot_machine_id`` / ``_pivot_runtime``, all shared with dispatch + the
    task action sub-menu) stay on ``PickerScreen`` and are read here via
    ``self._eng``. A later slice makes this a focusable Textual widget.
    """

    def __init__(self, eng) -> None:
        self._eng = eng

    # ---- Registered-pivot (Tasks) row rendering (moved here #88 F5 slice 6) --
    def _status_row(self, reg, state, rows, err, width):
        """The header line for a registered pivot: a count, a load spinner, or
        the empty/error hint."""
        eng = self._eng
        account = bool(getattr(reg, "account_scoped", False))
        machine = eng._pivot_machine() or "this machine"
        # An account-scoped pivot (CodeSpaces) is a cross-machine shared resource:
        # its status counts items, not "on <machine>".
        where = "" if account else f" for {machine}"
        t = Text("  ")
        if state == "loading":
            t.append(f"{eng.spin()} ", style=C_LOAD)
            t.append(f"loading {reg.label.lower()}{where}…", style=C_LOAD)
        elif state == "error":
            t.append("✗ ", style=C_WARN)
            t.append(f"{reg.label} unavailable: {err or 'command failed'}", style=C_META)
        elif not rows:
            t.append(reg.empty_hint, style=C_DIM)
        else:
            t.append("●", style=C_PULSE[eng.pulse])
            tail = f" {reg.label.lower()}" if account else f" on {machine}"
            t.append(f" {len(rows)}{tail}", style=C_LABEL)
        t.append(" " * max(0, width - t.cell_len))
        return t

    def _row(self, reg, rec, width, selected):
        """One task entry: title, then dim badges (labels) + subtitle."""
        title = str(rec.get(reg.title_field) or rec.get(reg.id_field) or "(untitled)")
        t = Text("    ")
        t.append(title, style="grey85" if not selected else C_HEADER)
        badges: list[str] = []
        for f in reg.badge_fields:
            v = rec.get(f)
            if isinstance(v, (list, tuple)):
                badges.extend(str(x) for x in v)
            elif v:
                badges.append(str(v))
        for b in badges:
            t.append(f"  [{b}]", style=C_ENV.get(b, "cyan"))
        if reg.subtitle_field:
            sub = rec.get(reg.subtitle_field)
            if sub:
                t.append(f"  · {sub}", style=C_DIM)
        t.append(" " * max(0, width - t.cell_len))
        if selected:
            t.stylize(C_SEL)
        return t

    # ---- D1: declarative columns + summary rendering ----------------------
    @staticmethod
    def _col_width(col) -> int:
        """The effective render width for a declarative column: the manifest
        ``width`` when set, else a header-derived fallback (min 6) so a
        width-less column still renders sanely."""
        return col.width if col.width else max(6, len(col.header))

    def _summary_line(self, reg, summary, width):
        """The D1 ``summary`` header line: ``reg.summary_template`` with
        ``{token}``s filled from the provider's summary dict. Missing tokens
        degrade to empty (never raises). ``None`` when there is nothing to show."""
        if not reg.summary_template or not summary:
            return None

        class _Default(dict):
            def __missing__(self, k):
                return ""

        safe = _Default({k: ("" if v is None else str(v)) for k, v in summary.items()})
        try:
            text = reg.summary_template.format_map(safe)
        except (KeyError, IndexError, ValueError):
            text = reg.summary_template
        t = Text("  ")
        t.append(text, style=C_LABEL)
        t.append(" " * max(0, width - t.cell_len))
        return t

    def _banner_line(self, summary, width):
        """A prominent alert line rendered from the provider's summary payload:
        the reserved ``banner_text`` (+ optional ``banner_level``:
        info|warn|error). Distinct from the D1 ``summary`` template line -- a
        styled, unmissable notice (e.g. an actionable missing-``codespace``-scope
        remedy, #980). ``None`` when the summary carries no banner."""
        if not summary:
            return None
        text = summary.get("banner_text")
        if not text:
            return None
        level = str(summary.get("banner_level") or "warn").strip().lower()
        icon, style = {
            "error": ("\u2717", f"bold {C_WARN}"),   # cross mark -> red (error)
            "warn": ("\u26a0", "#d7af00"),            # warning sign -> amber
            "info": ("\u2139", C_LABEL),              # info source -> grey
        }.get(level, ("\u26a0", "#d7af00"))
        t = Text("  ")
        t.append(f"{icon} ", style=style)
        t.append(str(text), style=style)
        t.append(" " * max(0, width - t.cell_len))
        return t

    def _column_header(self, reg, width):
        """The column-header row for a columns-declaring pivot."""
        t = Text(" ")
        for i, col in enumerate(reg.columns):
            if i:
                t.append(PAD)
            w = self._col_width(col)
            t.append(_clip(col.header.upper(), w, col.align), style=C_HEADER)
        t.append(" " * max(0, width - t.cell_len))
        return t

    def _column_row(self, reg, rec, width, selected):
        """One entry rendered across the pivot's declarative columns."""
        t = Text(" ")
        for i, col in enumerate(reg.columns):
            if i:
                t.append(PAD)
            w = self._col_width(col)
            val = rec.get(col.key, "")
            cell = _clip("" if val is None else str(val), w, col.align)
            # Per-value palette colouring (reusing the picker's own vocabulary)
            # takes precedence; the column's literal ``style`` is the fallback.
            style = _palette_style(col.palette, val) or (col.style or "")
            t.append(cell, style=style)
        t.append(" " * max(0, width - t.cell_len))
        if selected:
            t.stylize(C_SEL)
        return t

    def _column_subtitle(self, reg, rec, width):
        """An optional dim second metadata line under a column row (e.g. the
        claiming worktree + its title). Rendered from ``reg.subtitle_field`` when
        the entry supplies it; ``None`` otherwise. Non-selectable (decorative)."""
        if not reg.subtitle_field:
            return None
        sub = rec.get(reg.subtitle_field)
        if not sub:
            return None
        t = Text("     ")
        t.append(str(sub), style=C_DIM)
        t.append(" " * max(0, width - t.cell_len))
        return t

    def build(self, add, width, sel):
        """Emit the registered-pivot (Tasks) body into ``add`` (the
        ``build_body`` VRow sink). Mirrors the former inline ``build_body``
        registered branch exactly; group sections are opened via
        ``add(..., new_section=...)`` so this component never touches the
        closure's ``cur_section``/``vrows``.

        Split into ``build_chrome`` (the machine-scope row -- Tasks has no button
        region) and ``build_data`` (the status line + the scrolling task list) so
        the concerns render into separate widgets; ``build`` emits both in order,
        byte-identically (#88 NF3)."""
        self.build_chrome(add, width, sel)
        self.build_data(add, width, sel)

    def build_chrome(self, add, width, sel):
        eng = self._eng
        add(eng.tab_bar(width, sel == ("M", 0)))
        add(Text(""))

    def build_data(self, add, width, sel):
        eng = self._eng
        reg = eng._reg_pivot()
        state, rows, err = eng._task_state()
        add(self._status_row(reg, state, rows, err, width))
        # A prominent provider alert (e.g. the actionable missing-`codespace`-
        # scope remedy, #980), rendered from the summary's reserved banner_* keys
        # -- placed above the D1 summary line so it is unmissable, and shown even
        # when the list is empty (the scope-gap case).
        banner_line = self._banner_line(eng._task_summary(), width)
        if banner_line is not None:
            add(banner_line)
        # D1: a declarative summary/header line (e.g. budget headroom), when the
        # pivot declares a `summary` template and the provider supplied a summary.
        summary_line = self._summary_line(reg, eng._task_summary(), width)
        if summary_line is not None:
            add(summary_line)
        add(Text(""))
        if state not in ("ready", "idle") or not rows:
            return
        if reg.columns:
            # Table render. Enrich each row with the claiming worktree's title
            # (the account-scoped correlation), then render a column header, and
            # either a flat list or -- when ``group_field`` is set -- grouped
            # sections (``── repo @ account ──``). An optional dim subtitle line
            # follows each row.
            eng._enrich_pivot_rows(reg, rows)
            add(self._column_header(reg, width), kind="section")
            if reg.group_field:
                groups: dict[str, list] = {}
                order: list[str] = []
                for li, rec in enumerate(rows):
                    g = str(rec.get(reg.group_field) or "· ungrouped")
                    if g not in groups:
                        groups[g] = []
                        order.append(g)
                    groups[g].append((li, rec))
                for g in order:
                    sec = Text(f"  ── {g} ", style=C_SECTION)
                    sec.append("─" * max(0, width - sec.cell_len), style=C_DIM)
                    add(sec, kind="section", new_section=g)
                    for li, rec in groups[g]:
                        add(self._column_row(reg, rec, width, sel == ("T", li)),
                            stop=("T", li), data=rec)
                        sub = self._column_subtitle(reg, rec, width)
                        if sub is not None:
                            add(sub)
                return
            for li, rec in enumerate(rows):
                add(self._column_row(reg, rec, width, sel == ("T", li)),
                    stop=("T", li), data=rec)
                sub = self._column_subtitle(reg, rec, width)
                if sub is not None:
                    add(sub)
            return
        li = 0
        for grp, entries in eng._task_groups():
            sec = Text(f"  ── {grp} ", style=C_SECTION)
            sec.append("─" * max(0, width - sec.cell_len), style=C_DIM)
            add(sec, kind="section", new_section=grp)
            for _idx, rec in entries:
                add(self._row(reg, rec, width, sel == ("T", li)),
                    stop=("T", li), data=rec)
                li += 1


class ProfilesView:
    """Encapsulated Profiles-configurator sub-view (#88 F5, slices 1-3).

    A cohesive sub-view carved out of the picker's monolithic
    ``PickerScreen.build_body`` into its own component, per the incremental
    componentization strategy (#88 F5): rather than convert the whole
    ``sel=(zone,index)`` focus model to widgets in one big-bang, we peel cohesive
    sub-views off the God-object one at a time and impose a **moratorium on new
    full-screen-at-once renders**.

    This component owns the Profiles pivot's **entire rendering** (slices 1-2) and
    now its **grid-editing model** (slice 3): the state -- ``grid`` (pending
    edits), ``applied`` (last-applied snapshot), ``pcol`` (cursor column),
    ``targets`` / ``host_cols`` (the matrix axes), ``_prof_unavailable`` -- plus
    the pure grid behaviour (``grid_dirty`` / ``pending_count`` / ``cell_locked``
    / ``profiles_present`` / ``_column_sels`` / ``toggle_cell``). ``PickerScreen``
    exposes thin ``@property`` / method **shims** onto these so its existing call
    sites (``setup``, ``_dispatch_key``, the Apply/progress path) and the test
    suite address them unchanged. The Apply/load *plumbing* (``_apply_profiles``,
    ``_start_profiles_run``, ``_commit_applied_profiles``, the background column
    loader) still lives on the engine and reads this state through the shims, to
    be pulled in by a follow-up slice. A later slice makes this a focusable
    Textual widget.
    """

    def __init__(self, eng) -> None:
        self._eng = eng
        self.pcol = 0                 # Profiles matrix column cursor
        self.grid = {}                # (target_idx, host_idx) -> bool present
        self.applied = {}             # last-applied snapshot of the grid
        self.targets = []
        self.host_cols = list(_DEFAULT_HOST_COLS)   # config-bound in setup()
        self._prof_unavailable = set()  # host-col idxs that couldn't load (#1370)
        # Real per-host column load / Apply plumbing (own-column model). The
        # source hooks are bound in PickerScreen.setup(); fixtures/tests leave
        # them None and keep the seeded self·agent diagonal.
        self._prof_lock = threading.Lock()
        self._prof_load = None        # src.load_profile_column (real sources)
        self._prof_apply = None       # src.apply_profile_column (real sources)
        self._prof_loading = False    # columns are streaming in
        self._prof_loaded = False

    # ---- grid-editing model (state owned here; PickerScreen shims delegate) --
    def grid_dirty(self):
        return any(self.grid.get(k) != self.applied.get(k) for k in self.grid)

    def pending_count(self):
        return sum(1 for k in self.grid if self.grid.get(k) != self.applied.get(k))

    def profiles_present(self):
        return sum(1 for v in self.grid.values() if v)

    def cell_locked(self, ti, hi):
        """A machine always has a profile for THIS repo with itself as host
        (self · agent) -- force-checked, not editable."""
        t = self.targets[ti]
        _lbl, hm, he = self.host_cols[hi]
        return t["machine"] == hm and t["env"] == he and t["agent"]

    def _column_sels(self, hi):
        """Build the TargetSel list for host column ``hi`` from the grid."""
        out = []
        for ti in range(len(self.targets)):
            if self.grid.get((ti, hi)):
                out.append(self._target_sel(ti))
        return out

    def toggle_cell(self):
        """Toggle the focused grid cell (Space on a Profiles row). Reads the
        focused row from the engine's ``sel``; reports via the engine's status
        line. Locked / unavailable cells are read-only no-ops."""
        eng = self._eng
        if not self.host_cols:
            return                       # no profile hosts -> nothing to toggle
        if self.pcol in self._prof_unavailable:
            _lbl, hm, he = self.host_cols[self.pcol]
            eng.debug = (f"{hm} {he}: profiles unavailable "
                         "(remote unreachable or needs upgrade) · read-only")
            return
        ti = eng.sel[1]
        if self.cell_locked(ti, self.pcol):
            eng.debug = "self · agent profile is mandatory (locked)"
            return
        key = (ti, self.pcol)
        self.grid[key] = not self.grid.get(key, False)
        t = self.targets[ti]
        _lbl, hm, he = self.host_cols[self.pcol]
        host = f"{hm} {he}"
        eng.debug = (f"{'+' if self.grid[key] else '-'} {host} → {t['label']}"
                     " (pending Apply)")

    # ---- real per-host column load + Apply plumbing (own-column model) -------
    def _target_sel(self, ti):
        """The TargetSel a target row represents (kind = agent|shell)."""
        t = self.targets[ti]
        return profiles_mod.TargetSel(
            t["machine"], t["env"], "agent" if t["agent"] else "shell")

    def start_load(self):
        """Background-load every host's saved column into the grid.

        Read-only: each host's column is fetched (local in-process, remote over
        SSH) and projected onto the grid; ``applied`` is snapshotted to match so
        the freshly-loaded state reads as 'no pending changes'.
        """
        self._prof_loading = True

        def work():
            from . import profiles_io
            cols = {}
            for hi, (_lbl, hm, he) in enumerate(self.host_cols):
                try:
                    cols[hi] = self._prof_load(hm, he)
                except Exception:
                    cols[hi] = None   # load failure -> unmanaged (default column)
            with self._prof_lock:
                # Don't clobber edits the user already started before the load
                # resolved -- only project columns onto a pristine grid.
                if not self.grid_dirty():
                    unavail = set()
                    for hi, sels in cols.items():
                        if sels is profiles_io.UNAVAILABLE:
                            # Unreachable / too-old remote: we can't know its
                            # real column, so mark it read-only. Seed just the
                            # locked self-diagonal so the grid stays consistent;
                            # cells render as "?" and are never editable or
                            # applied (#1370).
                            unavail.add(hi)
                            for ti in range(len(self.targets)):
                                self.grid[(ti, hi)] = self.cell_locked(ti, hi)
                            continue
                        if sels is None:
                            # Unmanaged host: render the DEFAULT column
                            # (minimal per-agent + bare cross-machine; see
                            # profiles.is_default_on), replacing the retired
                            # emit-everything default. The user can still curate
                            # from here and Apply.
                            _hlbl, hm, he = self.host_cols[hi]
                            for ti in range(len(self.targets)):
                                self.grid[(ti, hi)] = (
                                    profiles_mod.is_default_on(
                                        self._target_sel(ti), hm, he)
                                    or self.cell_locked(ti, hi))
                            continue
                        keys = {s.key for s in sels}
                        for ti in range(len(self.targets)):
                            on = self._target_sel(ti).key in keys or \
                                self.cell_locked(ti, hi)
                            self.grid[(ti, hi)] = on
                    self._prof_unavailable = unavail
                    self.applied = dict(self.grid)
                self._prof_loading = False
                self._prof_loaded = True

        threading.Thread(target=work, name="profiles-load", daemon=True).start()

    def apply(self):
        """Open the Apply confirmation: list exactly which terminal profiles
        each changed host column will gain/lose, *before* touching anything.

        Confirming runs the per-host progress dialog (local writes mirror to the
        terminal profiles, remote writes go over SSH). This is destructive to
        the terminal app's profile list, so the confirm step (and its explicit
        add/remove diff) is mandatory -- the regeneration is not silent.
        """
        eng = self._eng
        if eng.mock_mode:
            # Mock mode (explicit dev sandbox): simulate the apply, no writes.
            self.applied = dict(self.grid)
            eng.debug = f"Applied · {self.profiles_present()} profiles (mock)"
            return
        if not callable(self._prof_apply):
            # Real launch but the source exposes no apply hook -- surface it
            # honestly instead of silently pretending success. The real data
            # sources always provide it; this guards a misconfigured source.
            eng.debug = "Apply unavailable · source has no profiles IO hook"
            return
        changed = []
        diffs = {}
        for hi in range(len(self.host_cols)):
            if hi in self._prof_unavailable:
                continue             # read-only column: never diffed or applied
            added, removed = [], []
            for ti in range(len(self.targets)):
                now = bool(self.grid.get((ti, hi)))
                was = bool(self.applied.get((ti, hi)))
                if now != was:
                    (added if now else removed).append(self._target_sel(ti))
            if added or removed:
                changed.append(hi)
                diffs[hi] = (added, removed)
        if not changed:
            eng.debug = "Apply · nothing changed"
            return
        # Migrated to a native Textual ``ModalScreen`` (#88 F4): the confirm is a
        # pushed screen that owns the stack, backdrop, focus, and key routing and
        # returns its verdict via ``dismiss(True|False)``. Confirming runs the
        # per-host progress dialog; cancelling is a no-op.
        cf = {"changed": changed, "diffs": diffs}

        def _after(confirmed):
            if confirmed:
                self._start_run(cf)
            else:
                eng.debug = "Apply cancelled"
        eng.app.push_screen(ProfConfirmScreen(cf, list(self.host_cols)), _after)

    def _start_run(self, cf):
        """Execute the confirmed Apply: one progress item per changed host.
        Drives the engine's shared maintenance progress/executor infrastructure
        (the same ``ProgressScreen`` all maintenance ops use)."""
        from . import maintenance
        eng = self._eng
        changed = cf["changed"]
        diffs = cf.get("diffs", {})
        n_add = sum(len(diffs[hi][0]) for hi in changed if hi in diffs)
        n_rem = sum(len(diffs[hi][1]) for hi in changed if hi in diffs)
        items, tasks = [], []
        for hi in changed:
            _lbl, hm, he = self.host_cols[hi]
            key = f"{hm}/{he}"
            items.append({"id4": key, "title": f"{hm} {he}",
                          "machine_env": f"{hm} {he}", "hi": hi,
                          "state": "pending"})
            tasks.append((key, self._make_apply_task(hm, he, hi)))

        eng.executor = maintenance.MaintenanceExecutor("profiles", tasks)
        eng.progress = {
            "verb": "Apply profiles", "op": "profiles",
            "scope": f"{len(changed)} host column(s)",
            "items": items, "recs": [], "picked": [],
            "ticks": 0, "steps": 3, "done": False, "armed": True,
            "include_unused": False, "include_conversations": False,
            "n_add": n_add, "n_rem": n_rem,
        }
        eng.executor.start()
        eng._open_progress()

    def _make_apply_task(self, machine, env, hi):
        """A progress task that writes one host column; ``ok`` drives ✓/✗."""
        sels = self._column_sels(hi)

        def _run():
            ok, detail = self._prof_apply(machine, env, sels)
            return {"ok": bool(ok), "reason": detail, "detail": detail}
        return _run

    def commit_applied(self):
        """After an Apply run, advance ``applied`` for every host that succeeded
        (matched by the executor's per-item DONE state). Called from the engine's
        progress-close path (``_key_progress``)."""
        p = self._eng.progress
        if not p or p.get("op") != "profiles":
            return
        for it in p["items"]:
            if it.get("state") == "done":
                hi = it["hi"]
                for ti in range(len(self.targets)):
                    self.applied[(ti, hi)] = self.grid.get((ti, hi), False)

    def build_chrome(self, add, width, sel):
        # Profiles lives under Configuration with its own host-column axes -- no
        # machine-scope row and no top button region, so its chrome is empty
        # (the Apply/Reset buttons ride the bottom of the data). Uniform with the
        # other views' build_chrome/build_data split (#88 NF3).
        return

    def build_data(self, add, width, sel):
        self.build(add, width, sel)

    def build(self, add, width, sel):
        """Emit the Profiles pivot body into ``add`` (the ``build_body`` VRow
        sink). Mirrors the former ``PickerScreen._build_profiles`` exactly."""
        if not self.host_cols:
            # No Profiles host columns -- no ``copilot`` machine in
            # machines.yaml exposes a native-terminal (windows/linux) env, so
            # ``_DEFAULT_HOST_COLS`` ([]) is the only fallback. Render a
            # placeholder instead of indexing the empty column list, which used
            # to raise IndexError in ``_visible_pcols`` when the operator
            # arrowed into the Profiles pivot (issue #149).
            add(Text(
                "  No profile hosts configured -- add a copilot machine with a "
                "windows/linux env to machines.yaml.",
                style=C_DIM,
            ))
            add(Text(""))
            add(self._profiles_button_row(width, sel == ("BTN", 0),
                                          self._eng.btn_idx),
                stop=("BTN", 0))
            return
        colw = self._col_widths()
        lblw = 30
        vis = self._visible_pcols(width, lblw)
        if vis is None:
            return self._transposed(add, width, sel)
        lo, hi, ml, mr = vis
        add(self._legend(width))
        hdr = Text(" " + "TARGET \\ HOST".ljust(lblw - 1), style=C_HEADER)
        hdr.append("‹" if ml else " ", style=C_HINT)
        for j in range(lo, hi + 1):
            if j > lo:
                hdr.append(" ")
            hdr.append_text(self._host_header_cell(j, colw[j]))
        hdr.append("›" if mr else " ", style=C_HINT)
        hdr.append(" " * max(0, width - hdr.cell_len))
        add(hdr, kind="colhdr")
        for ti, t in enumerate(self.targets):
            row_sel = sel == ("PR", ti)
            agent = t["agent"]
            base = "grey78" if agent else "grey54"
            r = Text(" ")
            # The active target row label gets the same subtle active shading the
            # active host column header uses, so both cursor coordinates read.
            lbl_text = self._tlabel(t, lblw - 1, base)
            if row_sel:
                lbl_text.stylize("on grey23")
            r.append_text(lbl_text)
            r.append(" ")
            for j in range(lo, hi + 1):
                if j > lo:
                    r.append(" ")
                locked = self.cell_locked(ti, j)
                ch, style = self._cell_visual(ti, j, locked)
                if row_sel and j == self.pcol:
                    style = "grey50 on grey23" if locked else C_SEL
                r.append(ch.center(colw[j]), style=style)
            r.append(" " * max(0, width - r.cell_len))
            add(r, stop=("PR", ti), data=t)
        add(Text(""))
        add(self._profiles_button_row(width, sel == ("BTN", 0),
                                      self._eng.btn_idx),
            stop=("BTN", 0))

    def _transposed(self, add, width, sel):
        """Too narrow for a grid: one host is the header, each target a
        space-toggleable checkbox row. ◀▶ switches which host you're editing.
        Mirrors the former ``PickerScreen._build_profiles_transposed`` exactly."""
        eng = self._eng
        _lbl, hm, he = self.host_cols[self.pcol]
        add(self._legend(width))
        head = Text(" HOST  ", style=C_HEADER)
        head.append(hm, style=eng._hl(C_HEADER, True, False))
        head.append(" ", style=eng._hl("", True, False))
        head.append(he, style=eng._hl(C_ENV.get(he, C_HEADER), True, False))
        head.append(f"   ‹ {self.pcol + 1}/{len(self.host_cols)} ›  ◀▶ host",
                    style=C_HINT)
        if self.pcol in self._prof_unavailable:
            head.append("  · unavailable (needs upgrade)", style=C_DISABLED)
        head.append(" " * max(0, width - head.cell_len))
        add(head, kind="colhdr")
        for ti, t in enumerate(self.targets):
            agent = t["agent"]
            base = "grey78" if agent else "grey54"
            locked = self.cell_locked(ti, self.pcol)
            ch, cstyle = self._cell_visual(ti, self.pcol, locked)
            present = self.grid.get((ti, self.pcol), False)
            box = f"[{ch}]" if (present or ch == "✗") else "[ ]"
            r = Text(" ")
            r.append(" " + box + " ", style=cstyle)
            r.append_text(self._tlabel(t, width - 8, base))
            if sel == ("PR", ti):
                r.stylize("grey50 on grey23" if locked else C_SEL)
            r.append(" " * max(0, width - r.cell_len))
            add(r, stop=("PR", ti), data=t)

    # ---- render helpers (owned by the component) ------------------------
    def _col_widths(self):
        return [max(len(f"{m} {e}"), 3) + 2 for _lbl, m, e in self.host_cols]

    def _host_header_cell(self, j, colw):
        """One Profiles host-column header: machine (config) name in the header
        slot color + env in its per-env color, centered to the column width.
        The active host (the column being edited) gets the SAME subtle shading
        the machine tabs use for an active-but-unfocused tab -- never the
        inversion cursor, since the real cursor lives in the grid cell."""
        _lbl, m, e = self.host_cols[j]
        active = j == self.pcol
        unavail = j in self._prof_unavailable
        name_base = C_DISABLED if unavail else ("bold white" if active else C_TABOFF)
        env_base = C_DISABLED if unavail else C_ENV.get(e, name_base)
        cell = Text()
        cell.append(m, style=self._eng._hl(name_base, active, False))
        cell.append(" ", style=self._eng._hl("", active, False))
        cell.append(e, style=self._eng._hl(env_base, active, False))
        pad = max(0, colw - cell.cell_len)
        left = pad // 2
        out = Text(" " * left)
        out.append_text(cell)
        out.append(" " * (pad - left))
        return out

    def _visible_pcols(self, width, lblw):
        """Which host columns are visible. Returns (lo, hi, more_left, more_right)
        windowed around the cursor column; or None if not even one column fits
        (caller switches to transposed mode)."""
        colw = self._col_widths()
        n = len(colw)
        if n == 0:
            return None                # no host columns -- caller placeholders
        if self.pcol >= n:
            self.pcol = n - 1          # host set shrank; clamp the cursor column
        avail = width - lblw - 4   # reserve for ‹ / › markers
        if avail < colw[self.pcol]:
            return None
        lo = hi = self.pcol
        used = colw[lo]
        while True:
            grew = False
            if hi + 1 < n and used + 1 + colw[hi + 1] <= avail:
                hi += 1
                used += 1 + colw[hi]
                grew = True
            if lo - 1 >= 0 and used + 1 + colw[lo - 1] <= avail:
                lo -= 1
                used += 1 + colw[lo]
                grew = True
            if not grew:
                break
        return lo, hi, lo > 0, hi < n - 1

    def _tlabel(self, t, w, base):
        """Target label: 'machine env · agent', env token colored, padded to w."""
        seg = Text()
        seg.append(f"{t['machine']} ", style=base)
        seg.append(t["env"], style=C_ENV.get(t["env"], base))
        seg.append(f" · {'agent' if t['agent'] else 'shell'}", style=base)
        if seg.cell_len < w:
            seg.append(" " * (w - seg.cell_len))
        return seg

    def _cell_visual(self, ti, j, locked):
        """(glyph_char, style) for a matrix cell, reflecting applied vs pending."""
        if j in self._prof_unavailable:
            # Column we couldn't load (unreachable / too-old remote): show an
            # "unknown" marker, not a fabricated selection (#1370).
            return "?", C_DISABLED
        present = self.grid.get((ti, j), False)
        applied = self.applied.get((ti, j), False)
        agent = self.targets[ti]["agent"]
        if locked:
            return "✓", "grey50"
        if present and applied:
            return "✓", (C_PULSE[self._eng.pulse] if agent else "#37b7ff")  # active
        if present and not applied:
            return "✓", "bold #ff9e3b"      # pending add (alternate highlight)
        if applied and not present:
            return "✗", "bold #ff5f5f"      # pending removal
        return "·", C_DIM                   # inactive

    def _profiles_button_row(self, width, focus, active_idx):
        eng = self._eng
        dirty = self.grid_dirty()
        if not dirty:
            active_idx = 0          # Reset is unavailable -> not selectable
        n = self.pending_count()
        t = Text("  ")
        # Apply
        if dirty:
            alabel = f" ✓ Apply ({n}) "
            astyle = C_BTN_SEL if (focus and active_idx == 0) else "bold black on #ff9e3b"
        else:
            alabel = " ✓ Applied "
            astyle = C_BTN_SEL if (focus and active_idx == 0) else "bold black on green"
        t.append(alabel, style=astyle)
        t.append("   ")
        # Reset (only meaningful when dirty)
        if not dirty:
            rstyle = "grey42 on grey15"
        else:
            rstyle = eng._btn_style(focus, active_idx == 1)
        t.append(" ↺ Reset ", style=rstyle)
        suffix = ("proposed changes are NOT active yet" if dirty
                  else "selection active · Enter applies from anywhere")
        if t.cell_len + 4 + len(suffix) <= width:
            t.append("    " + suffix, style=C_DIM)
        t.append(" " * max(0, width - t.cell_len))
        return t

    def _legend(self, width):
        """One dim line keying the grid's agent/shell rows (and any unreachable
        column) to plain language, so a round-trip edit doesn't silently drop
        the bare-SSH ``shell`` profiles (#1369)."""
        t = Text("  ")
        t.append("agent", style=C_LABEL)
        t.append(" = launch worktree", style=C_DIM)
        t.append("   ")
        t.append("shell", style=C_MUTED)
        t.append(" = plain SSH login shell", style=C_DIM)
        if self._prof_unavailable:
            t.append("   ")
            t.append("?", style=C_DISABLED)
            t.append(" = remote unavailable (needs upgrade)", style=C_DIM)
        t.append(" " * max(0, width - t.cell_len))
        return t


class PickerApp(App):
    CSS = """
    Screen { background: $surface; }
    PickerScreen { width: 100%; height: 100%; }
    /* NF compose tree (#88): fixed-height chrome, body fills the rest. */
    PickerScreen > #nf-title  { width: 100%; height: 1; }
    PickerScreen > #nf-pivots { width: 100%; height: 1; }
    PickerScreen > #nf-chrome { width: 100%; height: 2; }
    PickerScreen > #nf-machine { width: 100%; height: auto; }
    PickerScreen > #nf-buttons { width: 100%; height: auto; }
    PickerScreen > #nf-body-data   { width: 100%; height: 1fr; }
    PickerScreen > #nf-footer { width: 100%; height: 2; }
    /* NF5-5 native OptionList data body (opt-in via
       AGENT_WORKTREES_PICKER_NATIVE_LIST): picker palette + the amber cursor
       used by the native modals; matches the base type so it targets the
       _PickerNativeData subclass. */
    PickerScreen > OptionList#nf-body-data {
        border: none; background: $surface; padding: 0;
        /* #171: hide the native vertical scrollbar. It (a) is redundant -- the
           picker draws its own ▲/▼ "N more above/below" chrome borders (which
           track ``self.top`` via _ensure_visible, independent of this widget),
           and (b) is the ROOT of the description line-wrap jitter: a shown
           scrollbar shrinks the content region by its width, so rows padded to
           the full widget width overflow and wrap to 2 lines. Worse, the width
           flips as the scrollbar appears/disappears (or is re-measured during a
           single-row replace), so the wrap flickers in and out per keystroke.
           With no scrollbar the content width equals the widget width and is
           constant, so full-width rows fit exactly and never wrap -- fixing the
           jitter for BOTH the full-rebuild and the incremental repaint paths. */
        scrollbar-size-vertical: 0;
    }
    PickerScreen > OptionList#nf-body-data:focus {
        background-tint: $surface 0%;
    }
    PickerScreen > OptionList#nf-body-data > .option-list--option-highlighted,
    PickerScreen > OptionList#nf-body-data:focus
        > .option-list--option-highlighted {
        background: #ffaf00; color: black; text-style: bold;
    }
    /* NF5-5 pinned section header (hidden -> takes no space until scrolled). */
    PickerScreen > #nf-body-sticky { width: 100%; height: 1; }
    """

    def __init__(self, source, live=False, mock_mode=None):
        super().__init__()
        self._source = source
        self._live = live
        self._mock_mode = mock_mode
        self.result = None            # set by the screen on a launch decision

    def compose(self) -> ComposeResult:
        yield PickerScreen(self._source, self._live, mock_mode=self._mock_mode)
